const DATA={"meta":{"built":"2026-11-10","sources":["99 Sqn Ground Cat Syllabus, Apr 2021 (uncontrolled)","C-17A IR(E)T Study Guide, XXIV Sqn Globemaster Flt, Jul 26 (uncontrolled)"]},"groundcat":{"lims":[["Airframe speeds",[["Max airspeed (clean)","350 KCAS / .825M"],["Max airspeed, <16,000 klbs fuel","300 KCAS / .825M"],["Max airspeed, <40 klbs fuel & >124 klbs frt, PA 15,000–27,728 ft","330 KCAS / .825M"],["Thrust reverse – flight extend/stow","Max 350/.825, Min 250/Vmma"],["Thrust reverse – ground extend/stow","182 kts"],["Slats extend / retract","280 KCAS/.62M  •  270 KCAS/.62M"],["Flaps 1/2","250 KCAS / .62M"],["Flaps 3/4","190 KCAS / .62M"],["Flaps full","175 KCAS / .62M"],["Flap extension / retraction rate","2 deg/sec  •  3 deg/sec"],["Gear retracting","225 KCAS/0.62M (>200 KCAS may not fully retract)"],["Gear retraction / extension time","13 sec  •  17 sec"],["Gear extending / down & locked","250 KCAS / 0.62M"],["Cargo door/ramp opening or closing","250 KCAS / 0.74M"],["Troop doors, air deflectors","250 KCAS / 0.62M"],["Pilots' window","205 KCAS / 0.62M"],["Ldg gear door removed","250 KCAS/M0.62 (vibration with rear door removed >225 KCAS/M0.62)"],["3-engine climb schedule","250 KCAS/Vmma <10,000 ft; 270 KCAS/.66M >10,000 ft"],["Holding airspeed","230 kts / Vmma"],["Max rate of descent","20,000 fpm"],["Min RAT operating IAS","130 KCAS"]]],["Ground & manoeuvring",[["Max wind for take-off and landing","Head 40 kts • Tail 10 kts • Crosswind 30 kts"],["Max taxi speed paved / unpaved","40 kts  •  30 kts"],["Max speed over cables","40 kts"],["Control surface gust protection","70 kts for 72 hrs after Hyd 2 & 3 pressurised"],["Gust protection pressure limit","1200–2000 PSIG"],["Nosewheel steering – rudders / tillers","10 +/- 2 deg  •  63 +/- 4 deg"],["Nosewheel steering in direction of failed system","23 +/- 4 deg"],["Nosewheel steering restriction","Do not exceed 20 deg above 490K and taxi speeds of 20 kts"],["Min runway length x width","3500 ft x 90 ft"],["Min taxiway width","50 ft"],["180 degree turn","143 ft"],["Min asymmetric turn / star turn","116 ft  •  80 ft"],["Combat offload min / recommended distance","1000 ft  •  1500 ft"],["Backing","2% slope at 586,000 lbs (sea level, 90°F)"]]],["Weights",[["Max taxi weight","586,000 lbs"],["Max take-off weight","585,000 lbs"],["Max zero fuel weight","447,400 lbs"],["Max 3/4 flap landing weight","586,000 lbs"],["Max full flap landing weight","502,100 lbs"]]],["Fuel",[["Max fuel for normal brake landing","<165K, or <4k in ER compartment"],["Fuel quantity outboard / inboard","37,760 lbs  •  84,540 lbs"],["Allowable fuel imbalance","8,000 lbs wing-to-wing and inboard-to-outboard"],["Fuel dump auto stop","20,000 lbs"],["“LOW FUEL”","16,000 lbs"],["“FUEL QTY X”","4,000 lbs"],["Fuel freezing – F-34, F-44, Jet A-1","-47°C"],["Fuel freezing – Jet A, F-24, F-27","-40°C"]]],["Engine",[["N1 normal / max / idle","0–99%  •  100.5%  •  24% +/- 3%"],["N2 normal / max / idle","0–99%  •  100%  •  60% +/- 5%"],["Starter disengage","51% N2"],["EGT start / normal","495°C  •  0–624°C (MCT)"],["EGT caution / max","625–654°C  •  655°C for <5 min (max, DRT, air start, reverse)"],["Oil pressure normal ops","70–250 PSIG – do not operate below 70 PSIG"],["Oil low pressure ground / air","0–70 PSIG  •  0–80 PSIG"],["Oil temperature normal / max","39–163°C  •  177°C transient, 20 min only"],["Oil caution ranges low / high","0–39°C  •  163–176°C"],["Min oil temp for take-off","50°C"],["Power rating","40,440 lbs flat rated"],["Consecutive starts","2 without cooling; 3rd after 15 min; 4th and 5th after 10 min each"],["Starter limits","15 min max motoring; >90 sec counts as a start attempt"],["Starter cooling time","5 min per 30 sec of operation, up to 40 min"]]],["Brakes, hydraulics & APU",[["Brake temperature normal","-99 to 650°C"],["Brake temperature caution / warning","651–750°C  •  751°C"],["Hydraulic normal quantity","4–23 quarts"],["Hydraulic caution quantity","0–4 quarts"],["Hydraulic reservoir capacity","28 quarts"],["APU starter limit","1 minute"],["APU max starts","3 per rolling 1 hour cycle"],["APU time between start attempts","5 minutes"]]],["Temperature & G",[["Max OAT for take-off","49°C up to 2500 ft PA, then per fig 5-4 in -1"],["Hot weather ops caution","43°C or greater may result in FROZEN GAINS"],["Planning technique for fuel freeze","Assume TAT = SAT + 20°C at cruise; keep TAT at least 3°C above fuel freezing point"],["G limits, flaps or slats extended","0 to 2.0g"],["G limits, abrupt rolling push/pull with flaps or slats","0.4 to 1.6g"],["Reverse thrust pushover","0g"],["Max bank","70°"]]],["SPRO (semi-prepared)",[["Max fuel","92,000 lbs"],["Max taxi 30 kts","<435K AUW / <410K ZFW / <82K fuel"],["Max taxi 20 kts","<447K AUW / <415K ZFW / <82K fuel"],["Max taxi 15 kts","<447K AUW / >82K fuel"],["Max AUW normal / reduced pressure","486 klbs  •  435 klbs"],["Max ZFW normal / reduced pressure","415 klbs  •  410 klbs"],["Max fuel normal / reduced pressure","92 klbs  •  82 klbs"],["% MAC limit",">32% with AUW >435 klbs"]]]],"systems":[{"name":"Hydraulics","items":[{"q":"How many independent hydraulic systems are fitted to the C17? At what pressure should they provide hydraulic power?","a":"Four and 4000 psi"},{"q":"Individual Primary and secondary flight control surfaces, (eg Upper Rudder) are powered by how many different hydraulic systems?","a":"Two (and continue to operate at a reduced capacity with just one(."},{"q":"The Hydraulic system is controlled via the Hydraulic System Panel (HSP) and in turn by how many Hydraulic System Controllers (HSC)? According to the MEL how many HSCs are required for flight?","a":"Two and two."},{"q":"You are in the cruise and operating the Hydraulic system in the normal way. Pressure from the Primary pump suddenly drops; below what pressure would the Secondary pump energise? Should the Primary pump come back online, what pressure would it need to achieve for the Secondary pump to de-energise?","a":"3400 psi and 3850 psi."},{"q":"You are in the cruise and operating the Hydraulic system in the normal way. The system pressure in No 2 or 3 systems drops and activates the Secondary pump. If the Secondary pump can not provide enough pressure, which pump will automatically activate?","a":"The Transfer pump."},{"q":"Above what temperature will the AUX Hydraulic pumps automatically shut down?","a":"135°C (Aux pumps also shut down for low system fluid quantity, less than 0.4 gallons)"},{"q":"Where are the four hydraulic reservoirs located? Which system can be manually topped up via its AUX sump?","a":"In the centre of the fuselage cargo compartment and System 2."},{"q":"The Hydraulic Fire Shutoff Valve stops the suction line flow from the reservoir to which two hydraulic pumps of each system when the Fire T handle is pulled? Which electrical bus powers the Hydraulic Fire Shutoff Valve?","a":"The Primary + Secondary pumps and the Battery Bus."},{"q":"Gust damping accumulators are powered from systems 2 and 3. Once fully pressurised how long will the systems remain affective before a full re-pressurisation is required?","a":"72 hours as long as accumulator pressure remains between 2000 and 1200 psi."},{"q":"What is the primary purpose of the Transfer Pump, (XFER Pump)?","a":"To assist in landing gear retraction or cargo door/ramp closing in the event of No. 2 or 3 engine loss."},{"q":"You have lost all fluid in system 3. Will the XFER Pump function?","a":"No. The XFER Pump mechanically transfers pressure, not fluid, between systems 2 and 3. If there is no fluid then pressure can be transferred."},{"q":"If the XFER Pump on the HSP fails. From where else can you control the XFER Pump?","a":"From the Loadmaster Forward Control Panel and Loadmaster Aft Control Panel."},{"q":"The No. 4 system contains a Ram Air Turbine, (RAT). When and why would a RAT be useful?","a":"To provide Hydraulic power to the primary flight controls on the No 4 system during an all engine failure."},{"q":"Below what speed should not fly to allow correct hydraulic power from the RAT? Which services should you not use when the RAT is the sole means of hydraulic power?","a":"130 kts. You should not attempt to reposition the flaps or use speed brakes. Large\nhydraulic loads will cause aircraft control issues (particularly in the roll axis)."},{"q":"Why do you operate the AUX pump during engine start?","a":"(Ref -1 section 2 ‘Engine start procedure’) To prime the EDPs to provide lubrication and prevent cavitations. Engine driven pumps also are a high load for the engine and increase the risk of a hung start"},{"q":"Having started Engine number 2 we activate the XFER pump before turning on No 3 AUX pump in anticipation for No 3 engine start. Why?","a":"(Ref -1 section 2 ‘Engine start procedure’) You are checking the ability of the XFER pump to transfer hydraulic power from system 2 into system 3. Checking in this direction will allow ensure the ability to retract the landing gear after a failure of the No 3 engine."}]},{"name":"Engines","items":[{"q":"The F117−PW−100 is a dual spool, single stage fan, high bypass ratio (6:1) turbofan with a maximum flat rate of how much thrust?","a":"40,400 lb @ ISA sea level."},{"q":"The engines will produce constant thrust up to the Thrust Break Temperature. What is the Thrust Break Temperature? What happens above it?","a":"Thrust Break Temperature is the ambient temperature beyond which EPR and thrust begin to rapidly decrease.\n-Max thrust is flat rated up to 87*F or 31*C at Sea Level\nNOTE: 1c-17A-1-1 further breaks this down as\n--Max thrust rating break temperature for 6,700 feet and below is standard plus 15.6°C. --Max thrust rating break temperature for above 6,700 feet is variable with altitude from standard day plus 15.6 to standard minus 2°C\n--INT thrust rating break temperature is standard day plus 10°C --MCT rating break temperature is standard day plus 10°C\nAbove the Thrust Break Temperature the thrust produced degrades in a linear fashion."},{"q":"Each engine is controlled by a dual channel (A and B) digital EEC mounted on the Engine Fan Case. What are the two electrical power sources for each EEC? How is it decided which electrical power source will provide power to the EEC?","a":"The PMA for the engine and the DC Bus associated with that engine,(note; N2 must be above 10% N2 for the PMA and the fuel switch must be on or the starter button pressed for the DC Bus).The source with the higher Voltage will power the EEC, at idle and above this should be the PMA."},{"q":"The EEC continuously monitors and verifies data from the throttle and the A/PDMC to ensure that the commanded EPR setting is maintained. Does a mechanical link between the throttles and engines exist?","a":"No. Each throttle is connected to a dual resolver which in turn sends electronic signals to the EEC."},{"q":"The EEC has three modes of operation that provide normal and alternate modes of thrust control, what are they? What must you consider when operating in the most basic of these?","a":"EPR, N1 and N2 modes. When operating in N2 mode Reverse Thrust and Auto Throttle are unavailable. Additionally, no limit protection exists in N2 mode."},{"q":"Describe what has happened to an engine for it to be classified as ‘Low EGT Margin’.","a":"The engine gradually loses EGT operating margin over time resulting from normal deterioration of internal engine components. The loss of operating margin causes the engines to run slightly hotter than normal to obtain equivalent thrust."},{"q":"Above what ambient air temperature and what EGT should you be concerned about a Low EGT Margin engine?","a":"24°C and 665°C."},{"q":"What annunciator does the C17 have to help alleviate the fact EFCS will initially mask the roll and yaw motions of a single engine failure?","a":"THRUST LOSS annunciator (and associated MASTER CAUTION)."},{"q":"How many A/PDMCs are fitted to the C17? Where do they receive information from?","a":"Two. The EECs."},{"q":"Which system bleeds fan duct air to cool the high pressure compressor and the high and low pressure turbine cases in flight? What does this system do?","a":"The Active Clearance Control System. The EEC modulates three valves which supply piccolo tubes that help cool the engine case and flanges. This reduces blade tip clearance thus increasing fuel efficiency in the cruise."},{"q":"What is the maximum engine oil pressure?","a":"There is no maximum! The relief valve in the pump prevents excessive pressure."},{"q":"The maximum oil volume is 28 quarts. What is the maximum quantity displayed to the crew?","a":"23 quarts, (28 max minus 5 unusable quarts)."},{"q":"Fuel is normally supplied to the engine under pressure from the fuel boost pumps. However, up to what altitude and pitch angle will the engine be able to suction feed fuel using the engine driven pumps and deliver MAX thrust rating power?","a":"10,000 ft and 21.5°"},{"q":"The ignition system consists of two independent systems, A and B. Which electrical power sources power each system?","a":"System A is powered by the AC Emergency Bus and System B is powered from AC\nBUS 1, 2, 3, and 4 respectively."},{"q":"To help prevent engine surge during ground manoeuvring, how much reverse thrust should you use? What else can you do to help reduce the risk of engine surge?","a":"Use only the level and duration of reverse thrust required to accomplish the desired manoeuvre. The use of engine bleed air and engine anti ice will reduce the likelihood of engine surge."},{"q":"True or False; The SED monitors the EGT independently and in addition to the A/PDMC?","a":"True. If the SED senses an over temp, it will send a signal to the WCC, unlike the A/PDMC it does not track or record time of event. It provides a positive warning should the A/PDMC’s or MFD’s be inoperative, such as during engine start with battery power only."},{"q":"How many loops of the fire detection system must be serviceable for flight?","a":"(ref MEL) At least one loop per engine must be serviceable."},{"q":"What will pulling the Engine Fire Handle accomplish?","a":"FIRE X discharge circuit is armed.\nGenerator field is de-energized.\nFuel and hydraulic fire shutoff valves are electrically closed isolating the affected engine as follows:\nIf the fuel switch is on, fuel will be shut off at the fuel control and at the wing spar. If the fuel switch is off, only the valve at the wing spar will close. There is sufficient fuel between the spar and the engine to run for about 1.5 minutes.\nThe hydraulic fire shutoff valve is electrically closed isolating the affected engine.\nRespective ENG fuel light and FUEL cue on WAP illuminate ON, if not already on.\nSignal to the Electronic Engine Control (EEC) to shut off the air/oil heat exchanger and turbine cooling systems.\nSilence the CAWS, if not already silenced."},{"q":"You discharge fire agent A, the fire does not extinguish. How long should you wait before you discharging agent B?","a":"30 Seconds."}]},{"name":"Engine Operation","items":[{"q":"It is the 10th of the month and you are starting the engines. Halfway through the engine start you realise you have selected the Engine Ignition to A, what must you do?","a":"Nothing. Changing the Engine Ignition source during the start could result in a Tail Pipe Fire"},{"q":"You are starting the engines and the fuel flow immediately exceeds 700 pph with no light up. What are your next actions?","a":"Stop the Start and carry out the Engine Clearing Procedure."},{"q":"During Engine Shut Down, you turn the Engine Shut Off switch on the number three engine to OFF – it fails to shut down. What must you do next? What could have caused the engine to not shut down?","a":"You must immediately pull the engine Fire X Pull Handle. It is possible that the Fuel Control Unit CB has popped and no signal had been sent to shut the fuel off at the\nengine. Pulling the engine Fire X Pull Handle will shut the fuel off but at the wing spar not the engine so the engine could run for one and a half minutes."},{"q":"During engine start you notice that the engine appears to be accelerating slowly and the EGT is high. What could be developing? What must you do to stop it?","a":"A Hung Start. You must carry out the Engine Clearing Procedure, it is possible for a Hot Start to develop from this condition."},{"q":"Describe what quantifies a Hot Start.","a":"A hot start is a Start EGT over temperature event and may be accompanied by a tailpipe fire. During engine start, if fuel flow exceeds 700 pph between X ENG SHUT OFF switch on and EGT rise or the start limit of 495 °C is exceeded or about to be exceeded, stop the start and perform the Engine Clearing Procedure."},{"q":"During engine start, “N2 MODE X” appears on the WAP. What could have caused this? What must you now do?","a":"It is possible you have started the engines with the Probe Heats ON. Turn the Probe Heats off straight away and allow the engine to run at Idle for one minute before shutting the engine down and restarting the engine with the Probe Heats OFF."},{"q":"The ATIS says the temperature is 9°C and you see packed snow on the taxiway. What ignition should you use?","a":"A & B. A & B should be used when the temperature is Zero and below or the use of anti icing is anticipated."},{"q":"Upon examining the F700 you notice the No 4 Aux Hydraulic Pump is unserviceable. Is the aeroplane fit to fly?","a":"(ref v3 MEL; -1 section 2) Possibly. From a main operating base the MEL details 4 fitted and 4 required. However, away from a main operating base only 3 are required\nin order to complete a one-time flight to a repair capable facility. Collar the CB and select the pump on. In the case of number 1 or 4 engines Aux pumps being unserviceable you would select the engine’s primary pump to on and document this fact. If it is engines number 2 or 3, you should prime the system using the transfer pump."},{"q":"State the eight conditions that would cause you to “STOP START”.","a":"– ENGINE START Button fails to illuminate of valve fails to open -No N2 rotation -No oil pressure -Low oil pressure (at or below 5 psi after ENG SHUT OFF Switch is ON) -Abnormal or no fuel flow indication after ENG SHUT OFF Switch is ON -No ignition within 20 seconds after ENG SHUT OFF Switch is ON -No N1 RPM indications after 40% N2 RPM (30% OAT 0*C or less) -Hot Start"},{"q":"Once the starter button has popped out how long must you wait for the light to go out? If it does not go out what are your next actions?","a":"30 seconds. If the light does not go out then the starter valve has not closed, you must remove all air sources to the starter valve and shut down the engine."},{"q":"You elect to STOP START. Describe your actions during the engine clearing procedure.","a":"If “STOP START” is announced during the start and the ENGINE START button is still engaged, accomplish the following:\nENG SHUT OFF Switch - OFF\nContinue motoring the engine for 30 seconds, then pull the ENGINE START button out. This will ensure that the engine is cleared of any fuel accumulated in the combustion chamber. If a simultaneous start is in progress, continue to motor the engine until the other engine start is complete to avoid possible damage to the other starter due to supply pressure fluctuations. If an immediate restart is anticipated, motor the engine until the EGT is below 190 °C. Observe normal starter duty cycle limitations.\nIf the ENGINE START button has already popped out:\nENG SHUT OFF Switch - OFF Reengage the starter below 20% N2 RPM. Motor for 30 seconds, then pull the ENGINE START button out."},{"q":"List the seven conditions that require an immediate engine shut down?","a":"(ref -1 section 3) Engine Fire Engine Disintegration (or continuous engine sparking)\nEngine Seizure Uncontrollable Overspeed Severe Engine Vibration Severe Compressor Stall (Uncontrollable EGT or Engine does not respond to Throttle\nMovement) Engine/Fuel Pylon Leak"},{"q":"Shortly after Take Off you suffer a failure of the number 1 engine. During the subsequent EMERGENCY ENGINE SHUTDOWN what must you do to the Aux Hydraulic Pump? Why?","a":"(ref -1 section 3) The pump should be depressurized- this ensures that if system 1 or 4 is affected, the SCEFCs will detect a hydraulic system failure. This will cause the SCEFCs to switch to the Tandem Control Valve module to the operational engine’s hydraulic system which will reduce the probability of a flap failure being declared. You are attempting to alleviate a flaps fail condition by switching control of the SCEFC tandem control valve module to the number 4 engine. By removing all pressure from the number 1 system you ‘trick’ the system into think there has been a failure of the number 1 system so it switches control to the number 4 system. This procedure also works in reverse from the number 4 to number 1 system."},{"q":"You suffer a four engine flameout. Bad luck. At what stage does the -1 say should you transition from the FOUR ENGINE FLAMEOUT drill to the Ditching/Forced Landing Drill?","a":"(ref -1 section 3) 10,000’ AGL."},{"q":"Having suffered your four engine flameout you are attempting a forced landing with slats retracted and flaps up and a gross weight of 420,000lb. What should your approach speed be?","a":"(ref -1 section 3) 191kts."},{"q":"Describe the symptoms of a Compressor Stall or Surge?","a":"(ref -1 section 3) – Abnormal EGT/RPM indications -Abnormal engine noises (pops/bangs) -EGT/RPM approaching or exceeding limits -Failure pf an engine to respond to throttle movements -Accompanied by THRUST LOSS light"}]},{"name":"Fuel","items":[{"q":"What are the typical fuels permitted for standard non contingency C-17A ops? Where can this info be found on the a/c?","a":"(-1, Part 5, Specified Fuel, Table 5-3) The specified fuel for the aircraft is JP8. Alternate fuels include: JP4, JP5, JP8/SPK, JP8+100, Jet A, Jet A + FII, CI, LI, SDA100, Jet A-1, Jet B, TS-1/RT, AN-8. Painted on fuselage next to crew entry door."},{"q":"Which of these fuels will adversely affect performance?","a":"(-1, Part 5, Alternate Fuels) Alternative fuel usage will not adversely affect performance with the exception of JP-5 which increases fuel consumption by 0.5%."},{"q":"On a global in July, you are offered AN-8 fuel in Wellington, NZ for a flight to MPA. Should you consider taking it?","a":"(-1, Part 5, Cold Fuel Temperature Flight Operations) Yes, if TAT cannot be maintained a minimum of 3° C above the freezing point of the primary fuel (i.e., polar operations), choose an alternative fuel that has a lower freezing point. AN-8 is a cold weather Antarctic fuel designed to perform to -58C. The seasonal Artic jet stream is active during winter and can be unusually cold."},{"q":"What does MOAT mean on a jet plan?","a":"MOAT is the coldest forecast SAT expected en-route."},{"q":"You notice the MOAT is -76C on the jet plan having taken AN-8. What should you consider?","a":"(-1, Part 5, Cold Fuel Temperature Flight Operations) For planning purposes on long endurance high altitude flights, assume a 20 °C temperature rise (i.e., TAT = SAT + 20) at typical C-17 cruise altitudes and Mach numbers. Plan speeds and altitudes so as to keep the total air temperature a minimum of 3 °C above the freezing point of the worst- case fuel on-loaded for that flight. In this case, during the flight, it will probably be\nnecessary to increase speed or to descend to a lower altitude to avoid the TAT approach 3 °C of the -58C freezing point of the onboard fuel."},{"q":"What is the allowable design fuel imbalance for sustained operations?","a":"(-1, Part 5, Fuel System) The allowable design fuel imbalance for sustained operations is 8,000 pounds between wings. The minimum fuel in the outboard tanks is 30,000 pounds when total fuel is greater than 152,000 pounds. The allowable design fuel imbalance for sustained operations is 8,000 pounds between the inboard tank and outboard tank when total fuel is less than 152,000 pounds."},{"q":"At what fuel tank levels do deck angles become critical and what restrictions are there?","a":"(-1, Part 5, Fuel System) With less than 4,000 lb of fuel per tank, deck angle and lateral g become increasingly more critical. Below 1,000 lb per tank, deck angle should be restricted to +\\-3 degrees and lateral g manoeuvres should be minimized so as not to\ncause boost pump cavitation and engine flame out on approach. If an inboard tank SCHD light appears on the overhead fuel panel, the limitation on that tank should be increased by 1,000 lb."},{"q":"Where does LOW FUEL present and what does this mean to you?","a":"(-1, Part 3, ‘LOW FUEL’) Indicated total fuel is <16000lbs (-1, Part 5, Low Fuel Operations) The maximum airspeed is 300 KCAS/Mach 0.825 when total aircraft fuel is below 16,000 lb.\n(-1, Part 5, Low Fuel Operations CAUTION) The AFCS can be commanded to exceed\nthe configuration placard speed limit when total aircraft fuel weight is below 16,000 lb. The overspeed limit for the AFCS (AP/ATS/FD) is set to 300 knots when total aircraft fuel weight is below 16,000 lb., regardless of the current configuration placard. The CAWS alerts and barber pole indications will be correct.\n(-1, Part 5, Low Fuel and Heavy Payload Operations) The maximum airspeed is 330 KCAS/Mach 0.825 when total aircraft fuel weight is below 40,000 lbs, total payload is greater than 124,000 lbs, and the pressure altitude is between 15,000 and 27,728 feet."},{"q":"You have been tasked for an Aeromed at BAS having already loaded 130k of freight. You are in the cruise Mach.825 FL270 and are asked to make good LAM 1 minute earlier than expected with 160nm to run. How can you achieve this?","a":"(-1, Part 5, Low Fuel and Heavy Payload Operations) Possibly unachievable. The maximum airspeed is 330 KCAS/MACH 0.825 when total aircraft fuel weight is below 40,000 lbs, total payload is greater than 124,000 lbs, and the pressure altitude is between 15,000 and 27,728 feet.\nApprox. 20 mins (160nm) to make up 1 min, therefore a TAS increase of 3kts required. This could possibly be achieved by either climb or descent depending on wind/temp profile. Speeding up is not an option."},{"q":"During a tac descent the inboard fuel schedule light illuminates and FUEL annunciates on the WAP. In addition, an outboard AFT fuel pump illuminates LOW. Why might this profile trigger these conditions?","a":"(-1, Part 1, Fuel Quantity Indicating System NOTE) At pitch attitudes beyond +/-5 degrees (FQGS) −10° to +18°, fuel quantities may be inaccurate. During extreme manoeuvres, such as tactical descents, the error may be as much as 10,000 pounds.\n(-1, Part 1, List of Illustrations, Fuel System Panel (16 NOTE)) Outboard fuel tank(s) AFT boost pump LOW light may illuminate if pitch attitude exceeds 10 degrees nose low with tank fuel quantity below 34,000 lbs. Outboard fuel tank(s) FWD boot pump LOW light may illuminate if pitch attitude exceeds 15 degrees nose low with tank fuel quantity below 27,000 lbs."},{"q":"When using fuels JP-8/SPK, JP-4, or Jet B, what should be considered as an entry in PERF Factors?","a":"(-1, Part 2, Fuel Grade Properties, CG Adjustments – JP-8/SPK, JP-4, Jet B) The computed CG may be approximately 2% MAC further aft than actual CG and the total calculated aircraft weight may be too low. When the CG error is present, a heavier stick may be noticed during take-off rotation due to a slight mis-trim of the stabilizer. To account for the error in computed aircraft gross weight, use Delta Take-off Gross Weight input of 6,400 lb in the TOLD planning process. The fuel quantity error will self- correct shortly after take-off once the fuel cools."},{"q":"During the after take-off checks the loadmaster reports fuel leaking from the pylon. What are your actions?","a":"(-1, Part 2, ‘Engine or Pylon Fuel Leaks’) If fuel leaks from a wing pylon in flight, airflow\nwill normally dissipate leaking fuel away from the associated engine exhaust. The engine may continue to be operated in flight but will be promptly shut down if it is determined that the fuel leak poses a risk of in-flight fire. Unless a greater emergency\nexists, the Engine Fire/Emergency Engine Shutdown procedure shall be accomplished no later than 10 minutes prior to landing to ensure sufficient engine cooling.\nIf the engine must remain running until landing, comply with the following restrictions:\n– Request a fire truck to be available near the runway.\n– Avoid use of reverse thrust on the associated engine.\n– After landing, but before slowing to taxi speed, pull the fire handle of the associated engine to preclude fuel from leaking into the exhaust and subsequent engine fire.\n– When N2 decreases below 20% RPM, engage the starter until EGT falls below 190C."},{"q":"What rate does fuel dumping occur and what guidance do we have?","a":"(-1, Part 3, Fuel Dumping, Fuel Dumping Rate) The dump rate is approximately 6700lbs/min (JP-8). This rate assumes that all tanks are full at the start of dumping and that all boost and transfer pumps are on. If one pump in any of the tanks fails, fuel can still be dumped at a reduced rate. The only effect is the increased length of time.\n(ref BZ2350.102 FUEL DUMPING) BZ2350.102.1 Fuel Dumping Occurrence Report. Immediately after landing, AS Captains are to submit a Fuel Dumping Occurrence Report (format at BZ2350.102.2) to the DOC who is to forward it to OC Fuels and Lubricants Flt, copied to the Stn Flt Safety Officer and OC 2 Gp STANEVAL. OC Fuels and Lubricants Flt is to retain a copy of Fuel Dumping Occurrence Reports for a period of not less than 3 years. (OM Pt A 8.3.18 refers.)"},{"q":"On recovering with a load exceeding 120k what is likely to be your Vg in bad weather above FL150?","a":"Alternate design speed Vg 270kts (399200lbs, fuel <40000lbs)"},{"q":"What fuel considerations do you have to make on electing to make a full flap approach?","a":"(-1, Part 2, Approach Procedures CAUTION) ER Full flap steep approach/assault landings are prohibited with more than 165,000 pounds total fuel unless there is less\nthan 4,000 pounds of fuel in the four extended range compartments combined."}]},{"name":"Ancillary & Emergency Equipment","items":[{"q":"After ditching, how would pax get to the FEDS hatches?","a":"(-1, Part 1, Emergency Equipment, Escape Ladders) There are four semirigid escape ladders, one stowed at each FEDS hatch area. These ladders are stowed in canvas wrap containers approximately one foot below each hatch. Pulling down on a release handle on the fuselage side wall directly below each ladder will release a securing pin on the wrap allowing the ladder to freefall to the cargo/ramp floor.\nw/TCTO 2420. Escape ladder release handles on the fuselage sidewall are disabled and have been replaced with alternate release lanyards. The aft ladders are stowed with the alternate release lanyards secured outboard near the fuselage sidewall release handle location. The forward ladders are partially deployed, with the remaining ladder\nstowed in a retainer assembly on each side of the upper catwalk. Both of the forward alternate release lanyards will be routed to the Forward Loadmaster Station and secured to the forward bulkhead area. Pulling down on any of the alternate release lanyards will release the securing pin and allow the stowed ladder to free-fall to the cargo/ramp floor."},{"q":"The FEDS is activated by the detonation of an explosive charge called an initiator (Figure 1-304). The detonation is transmitted to the hatch cutting charges and life raft retractors by energy transmission lines. The system has a total of seven initiators. The initiators are located where?","a":"(-1, Part 1, Emergency Equipment, Flotation Equipment Deployment System) Maintenance/ditching hatch (M/D) area, right side, M/D hatch jamb; hatch may be opened from outside the aircraft to allow external access (FS 411).\nNOTE The HMSA may be installed in place of the maintenance/ditching hatch. The modified hatch weighs approximately 40 pounds, and is not hinged. The hatch cannot be opened from outside the aircraft.\nForward outboard corner of the forward loadmaster station ceiling panel (FS 280).\nFEDS hatch openings, fuselage frame member bordering each life raft assembly. Forward hatches at left and right sides (FS 426). Aft hatches at left and right sides (FS 1196).\nUpper leading edge of left-wing root fairing, accessible through an external latch cover, outboard of FS 580."},{"q":"The quick release pins on the M/D hatch and forward loadmaster station initiator handles are solenoid guarded. The solenoid guards are released when either of two FED ARM toggle switches is positioned to ARM. Where are these 2 switches?","a":"(-1, Part 1, Emergency Equipment, Flotation Equipment Deployment System) One switch is located on the pilot's side of the overhead panel, and another at the forward loadmaster station panel (Figure 1-305). The FED ARM switch is a three-position momentary toggle switch spring loaded to the neutral position."},{"q":"How many and what capacity do the life rafts have?","a":"(-1, Part 1, Emergency Equipment, Life Rafts) The three 46-man life rafts are stowed in individual, hardpack, assemblies attached to the cargo compartment ceiling below the FEDS openings. Over-load capacity is 69 persons. Each raft is equipped with the required survival equipment. N.B.138 POB limit is based on one life raft failing and overload capacity on the other two or on the other hand 3 x 46 of normal capacity."},{"q":"How many escape ropes are there?","a":"(-1, Part 1, Emergency Equipment, Escape Ropes) There are 10 escape ropes, each stowed at or near an emergency exit for ditching or ground evacuation."},{"q":"The -1 suggests we have 6 first aid kits typically on board and with provision for 20 more but where and how are RAF C17s scaled? 2x Daily Use First-Aid Kit (DUFAK). As a minimum, one DUFAK is to be carried for every 100 seats fitted. 1x Stbd side FS375 aft of the fwd ALM position. 1x ALM stowage drawer. 1x Emergency Medical Kit (ELFAK). One to be carried on aircraft fitted with seats for 30 or more passengers operating more than 60 mins flying time, at still air cruising speed, from an airfield at which qualified medical assistance could be expected to be available. 1 x stowage locker (no controlled drugs inc. morphine). 7) How many fire extinguishers are on board, what is the agent and on which type of fire are they effective?","a":"(-1, Part 1, Emergency Equipment, Hand Fire Extinguishers) 9 Portable hand fire extinguishers are provided in the following areas: 2x Cockpit - Left and right side (FS 222)\n1x Crew rest area - Inboard face of right-hand avionics rack (FS 306) 6x Cargo compartment - Left side at FS 471, 670, and 1055. Right side FS 481, 677, and 1055 each extinguisher contains one quart of bromo-chlorodifluoromethane, equivalent to HALON 121, and weighs approximately five pounds.\nThis agent is highly effective against chemical and electrical fires."},{"q":"What frequencies does the ELT operate on?","a":"(-1, Part 1, Emergency Equipment, Emergency Locator Transmitter) The beacon transmitter operates simultaneously on 121.5 MHz, 243 MHz, and 406.028 MHz. The ELT also has an audible buzzer to acoustically signal its position and advise the aircrew of system test indications/results or (inadvertent) activation."},{"q":"Where is the underwater beacon located and what is its endurance and range?","a":"(-1, Part 1, Emergency Equipment, Underwater Locator Beacon) The underwater locator beacon is attached to the Cockpit Voice Recorder (CVR). The beacon is a mercury battery powered acoustic pulse generator (Pinger) which provides a signal that can be heard underwater for approximately 2 miles in any direction for 30 days. This signal is activated by a water sensitive switch. The beacon is contained in a high strength aluminium alloy case which permits operation to a depth of 20,000 feet.\n10) By how much extra seat capacity can the std 54 seat configuration be enhanced with the palletised seats?\na) (-1, Part 1, Seats, Palletized Seats) The aircraft may be configured with up to 9 pallets of palletized seats for an additional 135 seats (189 total but can only utilise 188 due a\nsecond ALM!).\nb) Current DDH limitations on pax with palletised seats is 102 pax or 138 POB with DDH approval."},{"q":"In the heads what does the annunciator DO NOT USE THIS TOILET IF LIGHT IS ON indicate?","a":"(-1, Part 1, Water/Waste System, Waste Disposal) A full waste tank annunciator located adjacent to the flush button illuminates when the waste tank is full."},{"q":"How much of the sortie will the CVR record?","a":"(-1, Part 1, Miscellaneous Equipment, Cockpit Voice Recorder) The digital CVR system stores 2 hours of audio in solid state memory. The entire 2 hours is stored in a low- quality format in one memory location and the last 30 minutes is stored in a high- quality format in another location."},{"q":"When does the FDR start/stop to operate? record? and how much history can it capture to memory?","a":"(-1, Part 1, Miscellaneous Equipment, Flight Data Recorder System) The system operates continuously as soon as it is powered from the electrical bus and the system passes power-on BIT. Recording starts when any three engines are operating and the left and right parking brakes are released. Recording stops when weight-on-wheels is true and either: 1) three engines are not operating (N2 less than 50 per-cent), or 2) left or right parking brakes are set.\nThe system records data in solid state memory. The system stores summary data as well as significant special events (abnormal G loading, abnormal engine operation, etc.), and approximately 1000 flight hours of ASIP data.\nTechnically there is a difference between the data storage capacity on the jets as there are 2 different storage devices which deal with storing data from 4 sources:\nIAT - Individual Aircraft Tracking LESS - Load and Environmental Spectra Survey (ASIP) MFOQA - Mil Flying Operation Quality Analysis (RAF post flight download v USAF download every 120hrs)\nMISHAP - Crash Data"},{"q":"What is the accuracy of the a/c clocks?","a":"(-1, Part 1, Miscellaneous Equipment, Clock) Clock accuracy is within 8 seconds per day."}]},{"name":"Mission Computer","items":[{"q":"How many Mission Computers are fitted to the C17? What are they also known as?","a":"(-1-2, Part 1, Mission Computer/Electronic Display System) Two identical MCs, also\nreferred to as Core Integrate Processors (CIPs)"},{"q":"What does a Mission Computer do?","a":"(-1-2, Part 1, Mission Computer/Electronic Display System, Mission Computer System) Each MC can provide navigation and guidance, take-off and landing data computation, weight and balance calculations, airdrop, rendezvous, station keeping, and flight operations. The MC provides navigation guidance to the F/D, AP, and ATS."},{"q":"Describe the different types of annunciations the Mission Computer generates?","a":"(-1-2, Part 1, Mission Computer Display Annunciations) -Category I – Scratch pad only: generated as a result of an improper input of data, prompts to facilitate data entry, and improper requests to perform certain functions.\n-Category II – Message annunciations: MSG annunciations alert the crew to conditions that impact the operation of the MC or CCU but do not degrade the mission capability of the aircraft.\n-Category III – Status annunciations: STS annunciations are used to alert the crew to those avionics ’subsystem failures or LRU faults that degrade the mission capability of the aircraft and EFCS failures that can degrade the flying qualities of the aircraft. EFCS annunciations take precedence over all others are accompanied by a WAP cue EFCS MCD and Master Caution light."},{"q":"Having an Inboard Fuel Schedule light, you are seeking to see if any fuel remains in the ER tanks. Where would you look?","a":"(-1-2, Part 1, List of Illustrations, Weight and Centre of Gravity Pages) WT/CG -> Fuel Quantity Pages."},{"q":"When entering a Cruise Altitude in the Route Data Page, such as 310/350. What conditions must be met for the Mission Computer to consider a climb to FL350?","a":"(-1-2, Part 1, Flight Planning, Cruise Altitudes) Vertical profile inserts climbs when the\nnext altitude or increment can be attained. Each new altitude will have a minimum of 5 minutes at cruise."},{"q":"Having fully entered a flight plan into the mission computer, you notice a small subscript ‘C ’after each waypoint on the right-hand side of the screen. What does it mean?","a":"(-1-2, Part 1, List of Illustrations, Flight Plan Page Format) CAT I Route has been selected in the CFG/OPER lateral revision pages."},{"q":"Flying across the Atlantic you suffer an engine failure and are required to complete a drift down procedure. How would you find your drift down altitude?","a":"(-1-2, Part 1, List of Illustrations, Performance Pages) The drift down altitude can be found in the Engine Out Performance under Drift Down altitude."},{"q":"Upon examining your Engine Out performance, you notice SAR. What is SAR? What must you consider when applying it?","a":"(-1-2, Part 1, Engine Out Performance at Waypoint Page, Still Air Range) SAR is Still Air Range and is based on the current predicted flight plan altitude and gross weight at the waypoint, drift down to the engine out maximum altitude and ending when the EFOB is zero."},{"q":"Why is it important to enter the temperature deviation at each way point along a flight plan?","a":"(-1-2, Part 1, Calculation Frequency/Accuracy/Speed) Unless temp dev’s are entered the MC assumes standard day temperature in doing fuel calculations. Temperature deviations are used to calculate MAX ALT and fuel burn off as well as to calculate the TAS (for ETEs) from the CAS/Mach for the flight plan’s altitude."},{"q":"In flight, within what distance and what height block will the Mission Computer use Air Data Computer and Inertial Reference System data to update the flight plan? Beyond these limits what will it use?","a":"(-1-2, Part 1, Atmospheric Model) The atmospheric model extends to 200NM and +/- 4000 ’of current altitude and is updated every 5 minutes. Beyond that, the MC uses spot winds and temp dev’s as entered in the DEFINE/REVIEW waypoint page.\nb) the Wind schedule as entered in the WINDS page, wind factors entered on the ROUTE DATA page, and if none of those exist then 0 wind and standard temps."},{"q":"Define Max Alt?","a":"(-1-2, Part 1, Maximum Altitude and Cruise Altitude) 300 foot per minute cruise ceiling. It is calculated using present weight, LRC, and the appropriate four-engine MCT or three-engine INT. It is rounded down to the nearest hundreds and dynamically updates."},{"q":"You are avoiding weather and have found yourself 20 miles from track with no offset inserted, the flight plan does not appear to be updating, why?","a":"(1-2, Part 1, Calculation Frequency/Accuracy/Speed) The 5-minute active flight plan\nperiodic update is inhibited when: on a path descent, more than 15NM off flight plan. The MC considers offsets entered on the PROG 1 page as on the flight plan. Calculations do not factor in intercepts to or from offsets; i.e., no adjustments to ETEs, ETAs, fuel burn off, etc"},{"q":"Having entered a hold, the Prog Page 1 is giving you two options – Hold Immediate Exit or Hold Exit. What do they do?","a":"(-1-2, Part 1, Holding Pattern Exit and Flight Path Lateral Offset or Holding Pattern Immediate Exit)\nSelection *Hold Exit prompts the MC to exit the holding pattern the next time the\nholding fix is crossed, allowing sequencing of the fix and continuation of the flight plan.\nSelection *Hold IMM Exit an immediate return from the present position to the holding\nfix is flown by shortening the inbound leg. An automatic exit occurs upon sequencing the holding fix."},{"q":"With GPS updating enabled, how is PPOS normally determined?","a":"(-1-2, Part 1, Present Position Determination, Aided Inertial Navigation) Normally, PPOS is a solution computed in one IRU, blended from its inertial and GPS data. This solution is used as long as GPS updating is selected and either IRU 1 or 4 is healthy with its GPS solution passing reasonableness criteria."},{"q":"You are in the cruise and you believe the aircraft has entered Degraded Mode. What are the symptoms of Degraded Mode? How long should you wait in Degraded Mode before actioning the drill for Permanent Degraded mode?","a":"(-1-2, Part 3, Degraded Mode, Temporary Degraded Mode and Permanent Degraded Mode) The primary indication of Degraded Mode is the phrase DEGRADED MODE highlighted in the centre of the screen on the MCDs operating in MSN and SKE modes. All other MSN/SKE page displays and functions are blank/unavailable. Temporary degraded mode is known to last 4-18 seconds. Degraded Modes which do not lead to MC restarts, or unresolved bus control contention between the CIPs are indications of problems more\nserious than flight plan or database corruption. If, after 3 minutes, MCDs in MSN or SKE modes continue to display DEGRADED MODE and or the cockpit displays continue to flash or are blank, refer to Section III of -1."},{"q":"What are the symptoms of a failure all Mission Computers?","a":"(-1-2, Part 3, Failures) If both MCs fail, there are no WACS alerts. However, all flight displays blank, navigation radios cannot be tuned, and fully automatic cabin pressurization control is lost. If a mission/SKE page is displayed, it is frozen and not updated. Likewise, pressing MCK Mission/SKE keys will not branch to the appropriate page or function. Communication mode pages are not affected and can be accessed by pressing the COMM key.\nFor your consideration; Having had a failure of all Mission Computers you cannot recover MC1 or MC2. In accordance with the drill, you divert to your nearest suitable airfield, now the fun begins! I’ve started you off\nwith some safety points and items to consider, this isn’t an exhaustive list but will hopefully get you going in the right direction. How would you generate Landing/Go around data? What instruments must you use? What configuration will the aircraft be in? What speed is Vmma? What power setting is required to stay above the stall and what instrument do you set it on? Do you have any stall protection? Is the HUD available? Etc etc"}]},{"name":"Performance","items":[{"q":"The engines are \"Flat Rated\" (that is, they will give the max rated thrust of 40,440lbs) up to the \"Thrust Break Temperature\". After this temperature, engine max available thrust, and hence t/o performance, drops off. What is this temperature at sea level? How does this temperature decrease with pressure altitude?","a":"‘-1, section 1, Engines, Engine Thrust’ gives about 87 deg F or 30.5 deg C. Decreases by\nSTD atmospheric lapse rate up to 6700 ft ‘-1-1, Part 2, Factors/conditions affecting engine performance, temperature.’"},{"q":"When flying for endurance (holding), what effect does a drag index of 10 have on the baseline fuel burn? Consider a 4 minute holding pattern in which you will spend 50% of the time (approx) in turns. What effect does using a 20 deg AOB have on the DI=10 fuel burn you have just found? Contrast this with the effect of using 30 deg AOB? Use an ac wt of 400klbs, holding at 10k ft, to derive your answers in pounds per hour.","a":"Baseline is 13478 pph. ‘-1-1, Part 6, Factors/Conditions affecting endurance, Drag Index.’ A D/I of 10 would add 2.4% or 323 pph giving 13801 pph. A bank angle of 20 deg would turn this new burn of 13801 into 14300; 30 deg would give 14800 pph. ‘-1-1, Part 6, Chart Description and Explanation, Effect of Bank Angle on Endurance.’"},{"q":"You are attempting to depart BZN during the winter. The runway has residual snow on it giving an RCR of 5.5 and you will have been de-iced with new Killfrost. The TOLD will not crunch using MAX pwr but will crunch with DRT pwr. What do you have to insert in TOLD to make this valid?","a":"Insert the COF, the RCR and the delta V rotate into TOLD, then compare the CFLs as usual."},{"q":"Why does the approach angle to assault landing reduce from 5 deg towards 3.8 degrees as AUW increases?","a":"Because approach speed increases with weight and the ROD in the approach phase is limited to 1000 fpm. ‘-1-1, Part 9, Definition of Terms, Approach to Assault Landing.’"},{"q":"Touchdown speed is how many knots greater than approach speed for normal and assault landings? Touchdown speed is used by landing TOLD to check which parameter(s)?","a":"4 knots. Tire limit speed and max brake energy speed limits. ‘-1-1, Part 9, Chart Description and Explanation, Approach Speed.’"},{"q":"If the anti-skid system becomes inoperative in flight, what effect would this have on a) maximum brakes-on speed? b) landing distance required?","a":"a) Nil b) Increases. ‘-1-1, Part 9, Factors/Conditions Affecting Approach and Landing, Braking Configuration."},{"q":"Following an EFATO, what speeds should you climb at?","a":"250 kts or MMA whichever is the greater up to 10k ft. 270 kts/M0.66 above this. ‘-1-1, Part 4, Factors/Conditions Affecting Climb Performance, Climb Speed.’"},{"q":"Is turbulence speed (VG – gust penetration speed) a maximum, minimum or optimum speed?","a":"Maximum. ‘-1, Section 5, Acceleration and Load Factors, ‘Structural Design Limitations’ illustration."},{"q":"There is a range penalty for a forward C of G – why? Conversely, why is there no penalty (actually, a benefit) for an aft C of G?","a":"The table is at ‘-1-1, Part 5, Factors/Conditions Affecting Cruise Performance, Center of Gravity.’ The reason is aerodynamic; a fwd Cof G requires more down-lift from the horizontal stabiliser to balance the lift/weight vectors; an aft Cof G reduces the amount of this lift required and therefore reduces the lift-induced-drag, reducing fuel burn."}]},{"name":"Cold Weather Ops","items":[{"q":"After a de-ice you notice residual snow still resides inside the engine nacelles just forward of the fan. Should you continue to start?","a":"‘-1, Section 7, Cold Weather, Before Entering the Aircraft.’ Attempted engine start with ice or frozen precipitation in the nacelles may result in starter failure. Fan blade damage may also occur if the engines are started with ice or frozen precipitation in the lower portion of the engine nacelle."},{"q":"It's a foggy cold morning and although frost remains on the underside of the wings post de-ice, are you legal to depart?","a":"‘-1, Section 7, Cold Weather, Before Entering the Aircraft.’ Takeoff with frost on the lower wing surface is permitted provided it is caused by fuel cooling of the adjacent\nair and that the thickness of the frost is not excessive. To preclude damage to the wing flaps, a coating of ice on the underside of the wing should be removed before departure. A thin coating of frost also is permitted on the fuselage, provided letter and paint lines are visible."},{"q":"During engine start ENG RPM ABNORMAL annunciates on the WAP. What actions should you take?","a":"‘-1, Section 7, Cold Weather, Starting Engines and Warmup.’ A nuisance ENG RPM ABNORMAL WAP message may appear when the start button is released. This message should extinguish as the engine reaches idle speed. If the message remains with N2 RPM stabilized above 54.0%, continue engine operation."},{"q":"During engine start oil pressure fails to indicate. What are your actions?","a":"‘-1, Section 7, Cold Weather, Starting Engines and Warmup.’ An engine start may be\ncontinued without an oil pressure indication provided:\ni) Oil quantity decreases ii) Oil temperature steadily increases iii) If oil pressure is not above 70 psi by the time oil temperature indicates 60 °C, the engine must be shut down and the cause investigated. The use of Type 1 MIL-L- 7808 oil may be desirable for extended operation in extremely cold weather due to its lower viscosity."},{"q":"How are C17A icing conditions defined?","a":"‘-1, Section 7, Cold Weather, Starting Engines and Warmup.’ Icing conditions are present when the OAT on the ground or TAT in flight is 10C (50F) or below, and any of the following conditions are present:\n– visible moisture in any form (rain, snow, sleet, ice crystals, or fog with visibility of one mile or less -Ramps, taxiways and/or runways have surface snow, ice, slush, or standing water on them which may be ingested by the engines or freeze on exterior\nsurfaces"},{"q":"The AUX pumps are slow to generate pressure and top out at 3400psi. What should be considered?","a":"‘-1, Section 7, Cold Weather, Hydraulic Warm Up, Aux Pump Cold Start.’ With ambient temperatures at or below −9 °C (15 °F), the AUX pumps may not initially generate full pressure. If system pressure does not rise to at least 3500 psi within 30 seconds of selecting the pump to AUTO, select the pump to off, wait 30 seconds and proceed as follows. 1. Select the AUX pump to AUTO for 30 seconds, then off for 30 seconds. 2. Repeat for a maximum of 10 cycles or until system pressure indicates at least 3500 psi.\nNOTE Because of the time required to charge the brake accumulators, system No. 2 pressure will remain at approximately 1000 to 2500 psi until the accumulators are filled.\nXFER Pump Cold Start\nWhen ambient temperatures are at or below −9 °C (15 °F), warm up the XFER pump as follows before engine start. 3. Select the No. 2 and 3 AUX pumps to AUTO and verify that both system pressures read at least 3500 psi. Use the AUX pump cold start procedure if necessary. 4. Select the XFER pump to AUTO"},{"q":"You've overnighted in Stockholm and the jet is cold soaked with OAT -8C. How should you warm up the HYDS?","a":"‘-1, Section 7, Cold Weather, Hydraulic Warm Up, Hydraulic Systems Warm Up.’ As early as possible before engine start, turn on all four AUX pumps from the cockpit, and verify that all FCS ACTR panel switches are in EFCS. This configuration will increase the hydraulic temperature at a rate of approximately 0.3 °C per minute. Set all FCS ACTR panel switches to FULL MECH/MECH/OFF during engine start.\n(ref -1, 7-183) After all engines have been started, engine driven hydraulic pumps\nhave been turned on, and hydraulic pressure has stabilized above 3200 psi, complete the following procedure.\nPrior to completing the Before Taxi checklist, check the hydraulic reservoir temperatures. If any temperature is less than 7 °C (45 °F), simultaneously cycle control stick and rudder pedals full stroke in all axes until all reservoir temperatures are greater than 7 °C (45 °F). (ref -1, 7-184) During initial taxi, cycle brakes and nosewheel steering as required to ensure proper operation\n(ref -1, 185) Just prior to takeoff, actuate rudder pedals a minimum two full cycles full deflection to ensure warm fluid at rudder actuator lines."},{"q":"What is the recommended taxi speed on slippery surfaces?","a":"‘-1, Section 7, Cold Weather, Hydraulic Warm Up, Taxi.’ Taxi speed should be as low\nas practical on slippery surfaces and taxi speed of 5 knots or less is recommended while turning."},{"q":"After deicing the aircraft, it begins to snow again. What extra checks are mandated by the -1?","a":"‘-1, Section 7, Cold Weather, Ground Deiicing/Anti Icing, Definitions.’ If frost, icing, or snow conditions are encountered after the aircraft is inspected and considered clean, a Pre-Takeoff Check will be accomplished by the flight crew. If any uncertainty arises, or the holdover time (see definition) has expired, perform a Pre-Takeoff Contamination Check.\n(ref -1, 7-193 WARNING) Test data indicate that frost, ice, or snow formations having a thickness and surface roughness similar to medium or coarse sand-paper on the leading edge and upper surface of a wing can reduce wing lift by as much as 30 percent and increase drag by 40 percent. In-flight structural damage can result from vibrations induced by un-removed accumulations.\nIncomplete aircraft de-icing are frequently reported, particularly at Brize, where ground personel are often unfamiliar with procedure and equipment. The importance of completely de-icing the aircraft can not be over emphasised. The -1 calls for a “clean aircraft concept” that means all deposits of snow, slush, ice and frost\nremoved, not just the wings and tail or control surfaces. The -1 does provide a slight concession “NOTE - A thin coating of frost is permitted on the fuselage, provided letter and paint lines are visible.” If this is the case then I suggest the rest of the aircraft needs de-icing anyway."},{"q":"How are the fan blades protected from ice during ground ops?","a":"‘-1, Section 7, Cold Weather, Ground Fan Blade Ice Shedding.’ Engine anti-ice provides no icing protection to the fan blades. Ice can build up undetected on the fan blades during low engine power ground operations in icing conditions. When icing conditions exist, and OAT is less than 3C, accomplish this procedure to prevent engine damage from ice accumulation on the fan blades and other engine low pressure compressor components. Perform ground ice shedding at intervals not to exceed 10 minutes to control ice build up. Delay takeoff if ice shedding cannot be accomplished according to the prescribe interval.\nWhen conditions permit:\n-Throttles (symmetrical) – set 50-51% N1/Hold for 1 second min (PF) -Throttles – IDLE -Repeat at intervals not to exceed 10 minutes until icing conditions no longer exist"},{"q":"The RSC indicates 10mm of wet snow and forecast indicates freezing rain. Can you legally depart? Land?","a":"Yes, yes- legal. Sensible? Questionable!\n‘-1, Section 7, Cold Weather, Takeoff.’ Takeoff will not be attempted with over ½ inch of slush or water, 1 inch of wet snow, or over 4 inches of dry snow on the runway. Refer to TO 1C-17A-1-1 for performance penalties associated with RSC, either slush or standing water\nTakeoff is “not recommended” during periods of freezing rain."},{"q":"If, whilst climbing, an icing layer is encountered, how can you reduce or help dissipate airframe icing?","a":"‘-1, Section 7, Cold Weather, Climb.’ If excessive ice formations remain on the aircraft after climbing through an icing layer, level off and increase airspeed to obtain at least +10 °C TAT or higher. Ice formations will begin to dissipate within 5 minutes with a TAT of +10 °C or higher. If the speed cannot be increased to obtain + 10 °C TAT, the ice will sublimate and dissipate more slowly. Do not descend through the icing layer to obtain higher temperatures.\nCAUTION This procedure of increasing airspeed should only be accomplished if all engine surfaces are free of all ice."},{"q":"The forecast indicates frost over night prior and you're due to depart 0700L. What should be considered when putting the a/c to bed?","a":"‘-1, Section 7, Cold Weather, Parking.’ Have wheel chocks in place before releasing the parking brake. If moisture has entered the brake assemblies, leaving the parking brakes released will forestall the possibility of the brakes freezing in position. Have\nthe air-craft serviced with fuel and oil and all sumps drained before condensates reach freezing point. Check that all plugs and protective covers for intakes, exhausts, pitot tubes, landing gear, etc., are installed if there is the slightest possibility of blowing or drifting snow, FOD, blizzards, severe winds, etc., or when anticipated downtime is to be lengthy. Service toilet facilities and remove all water, coffee, and other liquids which might freeze.\nCAUTION: For servicing the potable water systems, crew lavatory, and urinal. When the aircraft is exposed to ambient temperatures below 0C/32 °F, the water system must be drained along with all other liquids that may freeze, unless the aircraft interior temperature is maintained above 0C/32 °F."},{"q":"After application of hot AL34 at Brize what is the holdover time with fog present and OAT -3C?","a":"(ref FIH section 8) 0:45 (hot and diluted AL34 is used for de-ice)"},{"q":"When does the clock start for Holdover time?","a":"‘-1, Section 7, Cold Weather, Ground Deicing/Anti icing, Fluid Holdover Times.’ Holdover time begins when the final application of de-icing/anti-icing fluid commences and expires when the de-icing/anti-icing fluid applied to the air-craft loses its effectiveness."},{"q":"With a reported braking action 'poor' what is max xwind at 390KLbs?","a":"‘-1-1, Part 3, List of Charts, Maximum Crosswind.’ RCR 5, 24kts"},{"q":"Kabul reports -22C, what is it below ISA and what is the TEC applied to DH 29 ILS 6350'?","a":"5875' AMSL ~ 6000'AMSL\n2C/1000' -12 degC ISA 15C-12C= 3C But Kabul is -22C. Therefore -22-3= -25C ISA\n6350' = 480' above airfield +50' 530' TEC DH Answers in FIH"},{"q":"What are the perf. penalties associated with de-ice/anti ice fluids during take off? Where can they be found?","a":"(ref -1CL-1) TYPE II/IV ANTI-ICING FLUID PENALTIES – P8 in the 1C-17A-1CL-1 (prompted in the DEICE checklist)."},{"q":"What is the practical aim/use of them regarding the fluid on the wing?","a":"When applied to a clean surface, the fluid forms a protective layer. This layer has a lower freezing point than the frozen precipitation, which melts on contact with the fluid. As the layer becomes diluted by the melting precipitation, it becomes less effective and frozen precipitation can begin to accumulate. The Holdover time is a guideline and determines the protection time during various conditions. During takeoff, within holdover time, the shear stress applied to the fluid increases, the fluid’s viscosity decreases, and the fluid flows off the airplane."},{"q":"What are the approved fluids we are cleared to use on the C-17A?","a":"(ref FIH section 8 Page 120) When operating at RAF airfields, the fluid you can expect to arrive is AL34 diluted to 70% AL34 / 30% Water applied hot for use as a de-icing fluid. If AL34 is to be used for anti-icing it should be applied neat and cold (higher glycol content and viscosity).\n(ref -1, 7-252) Three fluid specifications are authorized for use in deicing/anti-icing as follows: - MIL-A-8243, Type I and Type II – deicing fluids - AMS 1424 Type I – deicing fluid - AMS 1428 Type II, Type III (not used by USAF), Type IV – anti-icing fluids NOTE: MIL-A_8243 Type I or II deicing fluids do not provide any anti-icing benefit and therefore do not have holdover times.\n(ref FIH, section 8) Type III fluid is designed primarily for aircraft with low rotation/take-off speeds. When used for anti-icing, Type III fluids have holdover time\nguidelines typically less than those of a Type II fluid but significantly longer than those of Type I fluids."},{"q":"After a de-ice you may be presented with a card or message on the anti-icing truck frequency (usually painted on the vehicle) which says, for example: A 4 B 75/25 C 1100 D 12/12 What is the decode?","a":"‘-1-1, Section 7, Cold Weather, Deicing/Anti icing Fluids, Holdover Elements.’ An international four element code (A, B, C, D) has been developed for communicating\nanti-ice information between ground crew and aircrew.\nElement A specifies the type of anti-icing fluid used. Fluid type may be either Type I, II or IV.\nElement B specifies the percentage fluid/water mixture to be used when entering the holdover timetables.\nElement C specifies the local time of the beginning of the anti-icing step.\nElement D specifies the date based on local time when anti-icing began."},{"q":"What is the Sqn Policy on departing Brize in regards to crewing in?","a":"(Ref: Part B Basic 5.2.1) For tasks involving the collection of war kit, de-ice, or transatlantic flights, the report time is to be 2.5 hours prior to chocks time. If an aircraft de-ice is required, an additional 30 minute crew-in should be considered. In these cases, the Aircraft Commander is to notify Ascot Ops so that available CDT to complete the task can be reviewed."}]},{"name":"Adverse Weather","items":[{"q":"At what windspeed should the a/c be evacuated to a safe weather area?","a":"‘-1, Section 5, Environmental Limitations, Wind Gust Limitations.’ If winds in excess of 70kts are expected. If this is not possible the aircraft should be moored."},{"q":"How long is the effective gust damping period when considering high winds on the ground?","a":"‘-1, Section 5, Environmental Limitations, Wind Gust Limitations.’ Control surface gust dampening is effective for 72 hours after hyd 2 and 3 systems are shut down. Once accumulator pressure falls below 1200PSIG the system must be pressurized to charge the accumulators for an additional 72 hours of protection."},{"q":"If subject to winds of 70kts or greater on the ground what must be considered before next flight?","a":"‘-1, Section 5, Environmental Limitations, Wind Gust Limitations.’ The control surfaces and points of attachment should be thoroughly checked by maintenance before next flight."},{"q":"What are the crosswind limits?","a":"‘-1, Section 5, Environmental Limitations, Wind Gust Limitations.’ 30kts for landing ‘-1, Section 2, Landing.’ For crosswinds greater than 15 knots, and aircraft gross weight less than or equal to 502,100 lbs, full flaps are recommended to provide improved control characteristics."},{"q":"What is max allowable headwind for takeoff or landing?","a":"‘-1, Section 5, Environmental Limitations, Wind Gust Limitations.’ 40kts."},{"q":"If sustained moderate turbulence is experienced what speed should you consider flying?","a":"‘-1, Section 5, Acceleration and Load Factors, ‘Structural Design Limitations’ Illustration.’ VG - 300kts up to 15000’PA, 290kts above 15000’PA unless ZFW exceeds 399200lbs with less than 40Klbs fuel"},{"q":"What does the magenta area of the APS150 weather radar display represent?","a":"‘-1, Section 1, Weather Radar, Predictive Windshear and Turbulence Detection.’ Within the altitude block, the radar indicates areas of moderate or higher turbulence up to 40NM away in magenta"},{"q":"What do the red, yellow and green areas represent on the APS150 display? Which coloured areas should be avoided?","a":"‘-1, Section 7, Weather Interpretation and Avoidance.’ Red: 12mm/ 0.5” rain/hr always avoid Yellow: 4-12mm rain/hr avoid Green: 1-4mm rain/hr avoid if associated with red and yellow"},{"q":"What can be assumed by the thickness of the yellow or green band adjacent to the red on a APS150 radar display?","a":"‘-1, Section 7, Weather Interpretation and Avoidance.’ Thin bands indicate a sharp gradient and are usually associated with more severe turbulence- these should always be avoided."},{"q":"How should a storm cell be avoided?","a":"‘-1, Section 7, Weather Interpretation and Avoidance, Avoidance Routes.’ Plan early, storms detected beyond 100nm are likely to be severe enough to require avoidance. 20nm separation from single cell but does not include cells separated by less than 40nm. This is 40nm between outer fringes of storm areas not centres.\n(ref -1, 7-40) Planned flight path to be towards the upwind edge of a storm. Suggested minimum is 20nm and 1nm/kt of wind speed downwind of any downwind avoidance. (ICAO suggest 10nm if separated visually below FL250, 15nm FL250-300, 20nm above FL300 or if not visual)."},{"q":"Below what N1 through heavy rain could result in flameout?","a":"‘-1, Section 7, Rain and Hydroplaning.’ <45%N1."},{"q":"If thunderstorms or extremely heavy rain are experienced what procedures should be followed?","a":"‘-1, Section 7, Turbulence, Thunderstorms, and Heavy Rain/Hail.’ Ignition ORIDE Thrust not less than 45%N1 Do not immediately perform a Precautionary Engine Shutdown if an engine rolls back or becomes unresponsive to throttle command unless EGT is uncontrollable or damage is apparent. AP On/Turb Airspeed – Turbulence penetration Altitude – don’t chase the altitude Anti-ice- as required Exit as soon as possible"},{"q":"What are the symptoms of windshear?","a":"‘-1, Section 7, Windshear, Windshear Recognition.’\nHesitant or excessive airspeed build up on takeoff roll Uncommanded airspeed change +/- 10kts of app. Uncommanded FPV+/- 2 deg or VV>500fpm on takeoff/app Excessive radar alt sink rate Excessive nose high/low pitch attitude.\nIn addition the PM should report sudden tail/headwind change >15kts, wind direction change, weather radar indications for areas of red surrounding precipitation and for heavy precipitation along takeoff/app path. APS150 alternating red/black arcs/searchlights on MFD or ND formats."}]},{"name":"Hot Weather Ops","items":[{"q":"Whilst operating the aircraft in hot conditions in which locations should you check for accumulations of sand and dust?","a":"Landing gear struts, hydraulic actuators, controls, instruments and electrical areas. Ref: 1C-17A-1, Section 7, Hot Weather and Desert Operations, Hot Weather, Pre-flight"},{"q":"When using the APU or External Unit to cool the aircraft you should keep the doors and hatches closed. What else can you use to aid cooling, (especially the cockpit)?","a":"Use the Sun Screens."},{"q":"The Avionics Cooling System has how many Cooling Fans? How many are operating at any one time?","a":"The system has three Cooling Fans and the Environmental System Controller decides which two will be in use on any given day. Ref: 1C-17A-1, Section 1, Environmental System, Cooling Fans."},{"q":"During period of high temperature you may consider using the Ground Ops Power. What does it depower?","a":"De-energizes AC buses 2 and 3, Deactivates all DC2 and DC3 distribution channels, Opens left and right side DC Tie Relays, precludes batteries from connecting to the battery bus, disables emergency power relay function, switch power source of avionics cooling from AC bus 2 and 3 to AC bus 1 and 4. Ref: 1C-17A-1, Section 1, Electrical Power Supply System, Ground Operations Power."},{"q":"What conditions must happen to trigger an Avionics Overheat condition?","a":"Avionics rack inlet temperature has exceeded 90°F for more than 5 minutes.\nRef: 1C-17A-1, Section 3, Environmental Procedures, Avionics Overheat."},{"q":"What indications will you get that an Avionics Overheat is occurring?","a":"Master Caution with associated WAP message and the Avionics Warning Horn will sound. Ref: 1C-17A-1, Section 3, Environmental Procedures, Avionics Overheat."},{"q":"What will be depowered when an Avionics Overheat has occurred?","a":"The AC/DC Avionics Buses No. 2 and No. 3. Ref: 1C-17A-1, Section 3, Environmental Procedures, Avionics Overheat."},{"q":"The engines on the C17 are flat rated up to the Thrust Break Temperature. What temperature is the Thrust Break Temperature? What does it signify?","a":"The Thrust Break Temperature occurs at 87°F/31°C MSL, (it actually occurs at ISA + 15.6°C and thus reduces with altitude). Up until the Thrust Break Temperature the\nengine will produce 40’400 lbs of thrust, after the Thrust Break Temperature the amount of thrust will reduce at a (approximately) linear rate. Ref: 1C-17A-1, Section 1, Engines, Engine Thrust."},{"q":"Why do engines become classified as low margin?","a":"It is the natural fatiguing of the engine. Over time the engine has to work harder to produce the 40’400 lbs, the result of this is a higher EGT. Ref: 1C-17A-1, Section 1, Engines, Low EGT Margin."},{"q":"Above what temperature should you consider the potential for the flight controls to revert to Frozen Gains? Why does this occur?","a":"In flight, the EFCS reversion to FROZEN GAINS may occur due to temperature thermals/inversion layers that cause computed SAT to exceed 50C.\nRef: 1C-17A-1, Section 7, Hot Weather, Hot Weather and Desert Operations, Potential Air Data Anomalies."},{"q":"Above what temperature can you not operate the aircraft? Why?","a":"49°C at an airfield pressure altitude of 2’500 ft and then reducing with pressure altitude increase. Above this temperature the ADC sensed data is valid. However, you can input data values above the ADC limit with no annunciation or warning to the crew. If you operate the aircraft above the limit all data will be invalid and thus a dangerous situation exists. Ref: 1C-17A-1, Section 5, Operation Limitations, Environmental Limitations, Outside Air Temperature Limits."},{"q":"Why do True Airspeeds increase with increasing temperature?","a":"Because as the temperature rises the density decreases, this can be seen from the Gas Law; ρ =P/T\nwhere, ρ is density, P is Pressure and T is temperature. If we assume P is that of the air mass at the airfield then as the daytime heating, T, increases the density must decrease.\nIf we now examine the lift formula, Lift = CL1/2ρV²S Where CL is the coefficient of lift, ρ is density, V is the aircraft speed and S is the wing area. Assuming a C17 of 400’000 lbs and with Slats extended and flaps one half. To fly level you must produce enough lift to counteract the 400’000lbs, the wing area and coefficient of lift are constant with no change of configuration. So if density is reducing due to increasing temperature, your speed V must increase to ensure the lift force remains sufficient."},{"q":"How long after landing is it estimated the maximum brake temperature will occur?","a":"10-15 minutes. Ref: 1C-17A-1, QRI, “BRAKE TEMP HIGH”."},{"q":"The temperature is 40°C. How long can you operate the LAIRCM for before you stand increased chance of Turret failure?","a":"Above 38°C after 25 mins there is an increased chance of turret failure. Ref: 1C-17A-1, Section 2, Normal Checks, Before Taxi."}]},{"name":"Ops Manual & Regulations","items":[{"q":"Having eaten a Chicken Tikka Lasagne a passenger appears to be dead. There is no medical officer present, how should you proceed?","a":"On discovery of an unresponsive or apparently dead passenger, first aid should be given. If there is any possibility that further medical assistance could be of benefit,\nthe AS should be landed as soon as possible. If it is obvious that death occurred a significant time beforehand, there is no requirement to divert the ac. The body must be off-loaded into the care of local authorities at the next destination airfield. The airfield authorities should be pre-warned to allow prompt provision of medical staff to pronounce death. The deceased should be afforded due reverence and distress to other passengers should be minimized. Ref: 2 Gp Operations Manual Part A, Section 11 Handling, Notifying and Reporting of Occurrences, Guide to Reportable Occurrences, Reporting Death In The Air."},{"q":"When departing from between which Latitudes should the aircraft be Disinsected?","a":"Between 30°N and 30°S and the following countries: Afghanistan\nAzerbaijan Democratic People’s Republic of Korea Georgia Greece\nKyrgyzstan Republic of Korea Tajikistan Turkey Uzbekistan Ref: 2 Gp Operations Manual Part A, Section 8 Operational Procedures, Disinsection, Disinsection Requirements."},{"q":"According to the 2GP Ops Manual how many minutes flex do you have for planned arrival time at destination before you should consider altering your departure time?","a":"Flt departures may be adjusted if forecast conditions show that arrival times will differ by more than 15 minutes from the planned time of arrival, provided the AS remains within current ATC and diplomatic\nb) clearances. If crews are unable to meet their planned arrival time +/- 15 minutes, the should contact ASCOT Opes who will confirm a new time of arrival, once coordinated with all enabling agencies and against other tasks.\nRef: 2 Gp Operations Manual Part A, Section 8 Operational Procedures, Route Time Keeping by AM AS"},{"q":"How far from a countries coastline, including that of its off-lying islands and dependencies, does its Sovereign Airspace exist? (ie how close can you get without needing a Dip Clear).","a":"12nm Ref: 2 Gp Operations Manual Part A, Section 8 Operational Procedures, Sovereign Airspace and International Boundaries."},{"q":"You require a Take Off alternate. How far away can it be?","a":"Up to 2 hours flight time at one engine inoperative speed Ref: 2 Gp Operations Manual Part A, Section 8 Operational Procedures, Planning Minima For IFR Flights."},{"q":"Under what circumstances will you require two Destination Alternate airfields?","a":"When the weather at destination will below the planning minima for the period one hour before to one hour after planned arrival time and when not weather information can be obtained for destination Ref: 2 Gp Operations Manual Part A, Section 8 Operational Procedures, Planning Minima For IFR Flights."},{"q":"When do you require an Equal Time Point?","a":"When you are more than 90mins still air flying time from a suitable alternate at one engine inoperative cruising speed.\nRef: 2 Gp Operations Manual Part A, Section 8 Operational Procedures, Planning Minima For IFR Flights."},{"q":"According to 2Gp Ops Manual what widths of runways are classified as ‘narrow’ for C17 operations?","a":"A narrow runway is defined at 30m. 18m should be considered the minimum width for normal operating unless a more restrictive limit exists for type-specific ADS. Ref: 2 Gp Operations Manual Part A, Section 8 Operational Procedures, Narrow Runway Operations"},{"q":"You are requested to carry member of the media. Who must you seek approval from?","a":"Carriage of any media personnel, when travelling for media reasons pertinent to the flight should have approval from MCO or DMCO or relevant tasking authority where appropriate Ref: 2 Gp Operations Manual Part A, Section 8 Operational Procedures, Carriage Of Media Personnel"},{"q":"How many passengers can a single ALM supervise before a second ALM or dispensation is sought?","a":"54 Ref: 2 Gp Operations Manual Part A, Section 8 Operational Procedures, Rear Crew Manning"},{"q":"State the crash cats required for C17 aircraft?","a":"Cat 8 with cascade lower to 4 with SO/AOC approval The use of a Nominated Diversion Airfield with a ARFF category one step lower than the aeroplane category as specified in the table is allowed subject to agreement with the aerodrome licence holder and parent stn OC Ops. Ref: 2 Gp Operations Manual Part A, Section 8 Operational Procedures, AS Firefighting and Recue Services (ARFF)"},{"q":"You are tasked to fly to the South of France. The aircraft is parked at Istres FAFB in the open and with a secretly marked package on board. How should it be guarded?","a":"Security seals applied and the aircraft is to be kept continuously under surveillance"},{"q":"As a minimum what must you do to maintain 31 Day currency?","a":"Complete a Take Off and Landing in the AS as PF. The simulator may be used to extend currency an additional 31 days from the date of the simulator; after which, currency must next be maintained in the ac. Ref: Part B Basic, Procedures, Pilot 31 Day Currency."},{"q":"State what equipment must be serviceable for flight within RVSM airspace?","a":"Two primary altitude measurement systems, one automatic altitude control system and one altitude alerting device. Ref: 2 Gp Operations Manual Part A, Section 8 Operational Procedures, RVSM\nAirspace."},{"q":"When may you take part in Land and Hold Short procedures?","a":"ATC clearance to carry out LAHSO should not be accepted by 2 Gp ac. FAA order 8400.10v2 Ch4, section 2 requires that non-US air carriers shall conduct LAHSO only when authorised by their national aviation authority. Ref: 2 Gp Operations Manual Part A, Section 8 Operational Procedures, Land and Hold Short Ops (LAHSO)"},{"q":"Your flight time to Incirlik is four hours and one minute. How long much time must elapse between Pilot’s eating?","a":"FCSIs state that different meals should be provided for pilots, both on the ground and in the air. On tasks in excess of 4 hrs duration, and when the AS is rationed for multi- sectors by the same catering agency, the AS cdr and co-pilot should not eat within 1 hr 30 min of each other at any point within the task, either on the ground or in the air. Ref: 2 Gp Operations Manual Part A, Section 6 Crew Health Precautions, Meal Precautions Prior to and During Flight, FCSIs Airborne Meals."},{"q":"By what distance should you avoid thunderstorms?","a":"Active thunderstorms should be avoided by as wide a margin as practicable. When possible, thunderstorms should be avoided laterally by at least 10NM below FL200 and 20NM above FL200. If overflight of a thunderstorm is unavoidable, a vertical clearance of at least 5000ft should be maintained. Ref: 2 Gp Operations Manual Part A, Section 8 Operational Procedures, Thunderstorms."},{"q":"State the standard Holding Reserve Fuel for an isolated airfield?","a":"2 hrs at normal cruise consumption after arriving overhead the destination airfield Ref: 2 Gp Operations Manual Part A, Section 8 Operational Procedures, Isolated Airfield."},{"q":"State the cross wind limits for NVG Take Off and Landings?","a":"20 kts for runways greater than 120 ft and 15 kts for runways 90 ft to 120 ft. Ref: Operations Manual, Part B Applied, NVG Operations, Crosswind."},{"q":"When landing, between which hours should you aim to use no more than Reverse Idle?","a":"2000 Local and 0700 Local Ref: 2 Gp Operations Manual Part C, RAF Brize Norton Local Procedures, Noise Abatement."},{"q":"You have been prescribed Temazepan, what considerations do you need to make before taking it?","a":"Before using Temazepam for the first-time aircrew should undergo an initial one-off ground trial with the outcome recorded in their logbook\nIt should be taken not less than 6 hours before the start of duty; only in extreme\ncases may it be taken less than 6 hours before flying\nThe normal dose of 10mg is usually adequate for aircrew. 20 mg can be used if absolutely necessary but should not be exceeded\nIt should not be taken in conjunction with alcohol or any centrally acting drugs, such as antihistamines. Over-the-counter drugs should be borne in mind. Therefore, aircrew should not self-medicate when using Temazepan\nIt should not be taken for any longer than 5 days consecutively and should not be taken for more than a total of 20 days in a 60 day period Ref: 2 Gp Operations Manual Part A, Section Crew Health Precautions, Drugs, Sleeping Tablets and other Pharmaceutical Preperations."},{"q":"Aircrew, flying authorisers, flying supervisors, aircraft engineers, Movement personnel, ATC and firefighters are bound by what alcohol and drugs rules?","a":"Armed Forces Act 2006 (as amended by the Armed Forces Act 2011 Effective 1 Nov 13)\nIndividuals are responsible for their condition when reporting for duty. Furthermore, AS cdr should be satisfied that his crew are not suffering from excess alcohol consumption and those leading personnel working in the delivery of aviation similarly should ensure their team members are not intoxicated.\nAll personnel should be in a fit state to perform their duties. There are certain duties that by their very nature are safety-critical where performing that duty with ability impaired by alcohol would result in a risk of death, serious injury to a person, serious damage to property or serious environmental harm. Ref: 2 Gp Operations Manual Part A, Section Crew Health Precautions Alcohol, Drugs and Flying."},{"q":"What alcohol limits and guidance specified in the Part A?","a":"Medical Guidance. DACOS Avn Med has confirmed (Ref H) that adherence to the following limits will ensure personnel subject to the Lower Alcohol Levels in the table above will be fit for duty, as far as alcohol consumption is concerned. Accordingly, no alcohol shall be consumed within 10 hours immediately prior to being liable for flying duties or flying support duties and consumption during the 24 hour period before reporting for duty shall be limited to a maximum of 5 units. Given the variation of alcoholic strengths, individuals should confirm the units per serving to ensure they remain within the direction.\nRef: 2 Gp Operations Manual Part A, Section Crew Health Precautions Alcohol, Drugs and Flying."},{"q":"Above what level should oxygen equipment be available?","a":"Aircraft should not be flown above FL 100 unless it is fitted with serviceable oxygen equipment for all of the crew. Ref: 2 Gp Operations Manual Part A, Section 8 Operational Procedures, Oxygen and Cabin Pressure Requirements"},{"q":"Above what cabin altitude should an aircraft not be flown?","a":"Pressurised aircraft should not be flown with a cabin altitude above 25000 ft in normal operations. Ref: 2 Gp Operations Manual Part A, Section 8 Operational Procedures, Oxygen and Cabin Pressure Requirements, Altitude Limitations."},{"q":"Unless operationally required, above what altitude must aircrew minimise the time?","a":"As decompression illness may occur at altitudes above FL180/18,000feet, although it is rare below FL250/25,000feet, aircrew must minimise time above FL180/18,000feet unless operationally required, and be alert to the onset of symptoms of decompression illness. Ref: 2 Gp Operations Manual Part A, Section 8 Operational Procedures, Oxygen and Cabin Pressure Requirements, Altitude Limitations, Op or Experimental Planned depressurisation, above FL250"},{"q":"Exceptionally, how long can an unpressurised aircraft spend between FL250-FL300?","a":"Exceptionally, Aviation Duty Holders and AM(MF) may authorize unpressurised aircraft to fly for not more than 10 minutes between FL250 and FL300. This authorization may be delegated down to Commanders of 1-star rank and above or nominated Post Holders (Defence Contractor Organizations Ref: 2 Gp Operations Manual Part A, Section 8 Operational Procedures, Oxygen and Cabin Pressure Requirements, Altitude Limitations, Op or Experimental Planned\ndepressurisation, above FL250"},{"q":"Approaching Alpor you are cleared by Muscat ‘FL*** due regard’. What does ‘due regard’ mean to you?","a":"Due Regard. Flying that is conducted outside the UK Flight Information Region (FIR) and Upper Information Region (UIR), in international airspace, but not conducted under ICAO flight procedures, should only be carried out ‘Due Regard’ and approved by the ADH or operation commander Ref: RA 2307, Acceptable Means of Compliance, Due Regard."},{"q":"Due Regard carries a personal responsibility on the part of the Aircraft Commander and/or handling Pilot to maintain separation from other Air Systems, vessels, or objects (such as off shore platforms). In order to ensure an appropriate level of safety, flight under Due Regard should be subject to one or more of the following conditions:","a":"Air Systems should be operated in VMC\nAir Systems should be operated within radar surveillance and under control of a surface or airborne radar facility Air Systems should be equipped with airborne radar and qualified operators sufficient to provide separation between themselves and other Air Systems Ref: RA 2307, Acceptable Means of Compliance, Due Regard."},{"q":"Exiting the Boulevard you are aware of a converging aircraft on your right. Who has right of way?","a":"When two aircraft are converging in the air at approximately the same altitude, the aircraft that has the other on its right must give way, provided that powered aircraft will give way to aircraft towing other aircraft or objects. Ref: RA 2307, Acceptable Means of Compliance, Avoidance of Collisions."},{"q":"Bastion operate omni-directional take off and landing operations. You assess a head on collision situation has developed with an aircraft on reciprocal heading. What should you do to avoid?","a":"When two aircraft are approaching head-on, or approximately so, in the air and there is a danger of collision, each is to alter its course to the right unless doing so would cause a crossing of flight paths Ref: RA 2307, Acceptable Means of Compliance, Avoidance of Collisions."}]}],"ekq":[{"n":1,"q":"The AP has two modes of operation; __________, and __________.","options":{"A":"TAKEOFF, MSN","B":"normal, AP DEGRADED","C":"standard, decluttered","D":"MSN, PROF"},"answer":"B","ref":"1C‐17A‐1, I, AFCS, Autopilot","topic":"Avionics, MC & Nav"},{"n":2,"q":"AP DEGRADED mode will not engage below Vmma with invalid aircraft weights (both MC’s inop, etc).","options":{"A":"True","B":"False"},"answer":"B","ref":"1C‐17A‐1, I, AFCS, AP Degraded Mode Operation (W)","topic":"Avionics, MC & Nav"},{"n":3,"q":"During MC Degraded Modes, the _________ use(s) the last valid altitude and heading data they received prior to the Degraded Mode. Advise ATC as necessary.","options":{"A":"IFF and TCAS","B":"Weather Radar","C":"IRUs","D":"TOLD"},"answer":"A","ref":"1C‐17A‐1, I, COMM & NAV EQPT, Rad ID Eqpt, IFF (N3)","topic":"Avionics, MC & Nav"},{"n":4,"q":"To determine an individual aircraft’s maximum payload weight:","options":{"A":"Add Operating Weight to Maximum Ramp Weight","B":"Add Operating Weight to Maximum Zero Fuel Weight","C":"Subtract Operating Weight from Maximum Zero Fuel Weight","D":"Subtract Operating Weight from Maximum Ramp Weight"},"answer":"C","ref":"1C‐17A‐1, I, THE AIRCRAFT, General Characteristics (N2)","topic":"Limitations & Performance"},{"n":5,"q":"There are normally ____ first aid kits installed on the aircraft with provisions for ____ total","options":{"A":"9; 18","B":"6; 18","C":"6; 26","D":"6; 102"},"answer":"C","ref":"1C‐17A‐1, I, EMERGENCY EQUIPMENT, First Aid Kits","topic":"Emergency procedures"},{"n":6,"q":"There are a total of ____ portable hand fire extinguishers onboard the aircraft with ____ in the cockpit and ____ in the crewrest area","options":{"A":"6; 2; 1","B":"9; 2; 1","C":"9; 2; 2","D":"12; 2; 2"},"answer":"B","ref":"1C‐17A‐1, I, EMERGENCY EQUIPMENT, Hand Fire Extinguishers","topic":"Emergency procedures"},{"n":7,"q":"Bank angles more than _____ degrees are not recommended. The maximum bank angle is ______ degrees.","options":{"A":"30; 45","B":"45; 60","C":"50; 60","D":"60; 70"},"answer":"D","ref":"1C‐17A‐1, V, FLIGHT CONTROL SYSTEM, Bank Angle","topic":"Flight Controls & EFCS"},{"n":8,"q":"On Extended Range aircraft with more than ____ pounds total fuel, delay braking until nose gear touchdown unless there is less than ____ pounds of fuel in the four extended range compartments combined.","options":{"A":"185,000; 1,000","B":"185,000; 4,000","C":"165,000; 1,000","D":"165,000; 4,000"},"answer":"D","ref":"1C‐17A‐1, II, LANDING","topic":"Normal Procedures"},{"n":9,"q":"The maximum allowable crosswind for landing is ____ knots.","options":{"A":"30","B":"40","C":"25","D":"35"},"answer":"A","ref":"1C‐17A‐1, V, ENVIRONMENTAL LIMS, Wind Gust Lims","topic":"Limitations & Performance"},{"n":10,"q":"The maximum landing touchdown sink rate for a steep approach (502,100 lbs) is ____ feet/min","options":{"A":"1100","B":"660","C":"500","D":"1000"},"answer":"B","ref":"1C‐17A‐1, V, STD PROCEDURE LIMS, Max Ldg Touchdown Sink Rate","topic":"Limitations & Performance"},{"n":11,"q":"Landing is not permitted with tailwinds greater than ____ or headwinds greater than ____","options":{"A":"10, 10","B":"15, 10","C":"10, 40","D":"10, 15"},"answer":"C","ref":"1C‐17A‐1, V, ENVIRONMENTAL LIMS, Wind Gust Lims","topic":"Limitations & Performance"},{"n":12,"q":"The APU AUTO SHUT DN ORIDE switchlight will override all automatic shutdowns except ____","options":{"A":"an indicated fire or overspeed","B":"a fire and high EGT","C":"high EGT and overspeed","D":"low oil press and high EGT"},"answer":"A","ref":"1C‐17A‐1, I, AUXILIARY POWER UNIT","topic":"Engines & APU"},{"n":13,"q":"The cargo compartment APU warning horn can be inhibited during ground operations by the ____ switch on the Entrance Light Panel","options":{"A":"OFF/ARM","B":"AGENT DISCH","C":"ORIDE","D":"INTL HORN INHIBIT"},"answer":"D","ref":"1C‐17A‐1, I, FIRE DETECTION & WARNING SYSTEM, APU (N)","topic":"Emergency procedures"},{"n":14,"q":"If APU is inoperative, ensure either a __________ is in place or __________connected before shutting down the last engine.","options":{"A":"loadmaster, air conditioning cart","B":"maintenance crew chief, ground power unit","C":"fire guard/fire extinguisher, air cart","D":"fire truck, lavatory service vehicle"},"answer":"C","ref":"1C‐17A‐1, II, ENGINE SHUTDOWN (N)","topic":"Engines & APU"},{"n":15,"q":"The APU starter operating limit is _____ minute and any APU starter engagement is considered a start attempt. _____ starts may be attempted per rolling one hour cycle with a minimum delay of _____ minutes between attempts.","options":{"A":"1, 4, 10","B":"1, 5, 10","C":"1, 3, 5","D":"1, 4, 5"},"answer":"C","ref":"1C‐17A‐1, V, SYSTEMS LIMS, Engine System, Starter Duty Cycles","topic":"Engines & APU"},{"n":16,"q":"[Block 21C] Activating a missed approach procedure prior to using TOGA (DIR‐TO) _______________. Activating the missed approach procedure using TOGA does not.","options":{"A":"Deletes intervening waypoints","B":"Causes MC degraded mode","C":"Arms missed approach procedure altitude","D":"Engages heading hold"},"answer":"A","ref":"1C‐17A‐1, II, MISSED APPROACH/GO AROUND [BLOCK 21C]","topic":"Normal Procedures"},{"n":17,"q":"[Block 21C] The SC/EFC includes a fixed gains mode that is automatically enabled in the event of air data loss. When the SCEFC FIXED GAIN mode is enabled, asymmetric outboard spoiler deflections are locked out and only symmetric spoiler deflections are commanded","options":{"A":"TRUE","B":"FALSE"},"answer":"A","ref":"1C‐17A‐1, I, FLT CONT SYS, ELEC SPOILER SYSTEM [BLOCK 21C].","topic":"Flight Controls & EFCS"},{"n":18,"q":"[Block 21] Pressing the SPD NAV pushbutton engages/disengages Speed Intervention if selected while in _________ with the NAV SEL Switch not in SKE.","options":{"A":"MSN LNAV","B":"MSN VNAV","C":"TAC","D":"NAV 1"},"answer":"B","ref":"1C‐17A‐1, I, AFCS, Controls & Indicators, AFCS CP, Spd Nav Pushbutton","topic":"Avionics, MC & Nav"},{"n":19,"q":"[Block 21] The value in the AFCS Altitude Window is displayed in both feet and ________ on the MCD’s CONVERT FEET/______ page.","options":{"A":"yards/yards","B":"yards/meters","C":"meters/meters","D":"meters/yards"},"answer":"C","ref":"1C‐17A‐1, I, AFCS, Controls & Indicators, AFCS CP, Altitude Window","topic":"Avionics, MC & Nav"},{"n":20,"q":"Turn on anti-ice when icing conditions exist ie OAT on ground or TAT in flight is ____ ºC or below and either visible moisture is present, or ramp, taxiways or runways have ice, snow, slush","options":{"A":"4                                                                   or standing water on them.","B":"10","C":"6","D":"0"},"answer":"B","ref":"1C‐17A‐1, II, NORMAL CHECKLISTS, STARTING ENGINES","topic":"Engines & APU"},{"n":21,"q":"If excessive ice formations remain on the aircraft after climbing through an icing layer, level off and increase airspeed to obtain at least _____ or higher.","options":{"A":"+3 °C TAT","B":"+6 °C TAT","C":"‐10 °C SAT","D":"+10 °C TAT"},"answer":"D","ref":"1C‐17A‐1, VII, COLD WEATHER, Icing & Cold Weather Ops, Climb","topic":"Cold & Adverse Weather"},{"n":22,"q":"(Cold weather/ ground icing conditions) Use of autothrottles for takeoff is strongly encouraged. If an EPR probe icing condition should occur, the autothrottles will ignore the erroneous EPR and maintain the correct power setting via computed throttle lever","options":{"A":"True","B":"False"},"answer":"A","ref":"1C‐17A‐1, VII, COLD WEATHER, Icing & Cold Weather Ops, Takeoff","topic":"Cold & Adverse Weather"},{"n":23,"q":"(IRCM) The laser is invisible and can injure eyes or skin within _____ feet for a single aft turret or _____ feet if the two forward turrets are installed.","options":{"A":"150; 175","B":"162; 185","C":"175; 197","D":"187; 200"},"answer":"D","ref":"1C‐17A‐1, I, Warning Systems, IRCM Operation (W)","topic":"Hot Weather & IRCM"},{"n":24,"q":"With no source of electrical power to the aircraft and the battery switch OFF, only the __________ bus is powered since it is connected directly to the batteries.","options":{"A":"AC Transfer","B":"Battery","C":"Battery Direct","D":"DC Transfer"},"answer":"C","ref":"1C‐17A‐1, I, Electrical Power Supply System, Batteries","topic":"Electrics & Hydraulics"},{"n":25,"q":"The electrical system is normally operated in the ____ mode with generators No. 1 and No. 2 supplying left side power and generators No. 3 and No. 4 supplying right side power","options":{"A":"Parallel","B":"Alternate parallel","C":"Split‐parallel","D":"Linked"},"answer":"C","ref":"1C‐17A‐1, I, Electrical Power Supply System, AC Electrical System","topic":"Electrics & Hydraulics"},{"n":26,"q":"The battery switch must be ON to provide battery power to the ____","options":{"A":"Transformer rectifiers","B":"Emergency buses","C":"Transfer buses","D":"AC buses"},"answer":"B","ref":"1C‐17A‐1, I, Electrical Power Supply System, AC Emergency Bus","topic":"Emergency procedures"},{"n":27,"q":"As a minimum, the batteries are designed to provide emergency power for up to ____ of operation","options":{"A":"15 minutes","B":"45 minutes","C":"One half‐hour","D":"One hour"},"answer":"C","ref":"1C‐17A‐1, I, Electrical Power Supply System, Batteries (N)","topic":"Electrics & Hydraulics"},{"n":28,"q":"The aircraft batteries provide power to the __________ which provides power to the AC Emergency Bus.","options":{"A":"Static inverter","B":"Transformer rectifier","C":"AC cross tie relay","D":"Generator control unit"},"answer":"A","ref":"1C‐17A‐1, I, Electrical Power Supply System","topic":"Emergency procedures"},{"n":29,"q":"OBIGGS II: If there is a total loss of electrical power during high pressure pneumatic air supply operation, ___________ may result. Immediately shut down the pneumatic cart.","options":{"A":"OBBIGS manifold failure","B":"Fuselage fire","C":"A hung start","D":"Wing manifold failure"},"answer":"B","ref":"1C‐17A‐1, I, Environmental Systems, Bleed Air Supply, Ground (W)","topic":"Fuel & OBIGGS"},{"n":30,"q":"During engine start, ensure engine oil pressure is a minimum of ______ psi before turning the ENG SHUT OFF switch to on.","options":{"A":"5","B":"10","C":"12","D":"14"},"answer":"A","ref":"1C‐17A‐1, II, Engines, Engine Start Procedure (Engine Start Button-1)","topic":"Engines & APU"},{"n":31,"q":"If ENG OIL PRESS X asserts on the WAP during engine start and the pressure is greater than 5 psi, you should","options":{"A":"Monitor oil pressure until idle is achieved and evaluate","B":"Perform the Engine Clearing procedure","C":"Disregard, the engine is operating within normal parameters","D":"Check to see if the engine is responsive to throttle movement"},"answer":"A","ref":"1C‐17A‐1, II, Engines, Engine Start Procedure (Engine Start Button-2)","topic":"Engines & APU"},{"n":32,"q":"Once an engine is stabilized at idle following a start, what is the normal fuel flow?","options":{"A":"400 – 500 pph","B":"500 – 800 gph","C":"800 – 1200 pph","D":"1500 – 1900 pph"},"answer":"C","ref":"1C‐17A‐1, II, Engines, Engine Start Procedure (Stabilized Engine)","topic":"Engines & APU"},{"n":33,"q":"Low EGT margin engines are more susceptible to ENG EGT X alerts on the WAP when OAT is at or above ____ and thrust is at or near maximum thrust?","options":{"A":"24 °C (75 °F)","B":"20 °C (68 °F)","C":"18 °C (65 °F)","D":"27 °C (81 °F)"},"answer":"A","ref":"1C‐17A‐1, I, ENGINES, Engine Thrust, Low EGT Margin","topic":"Engines & APU"},{"n":34,"q":"THRUST LOSS annunciator lights (amber) will illuminate in flight when thrust of a single engine is ______ less than the average EPR of the remaining engines.","options":{"A":"0.10 EPR","B":"0.15 EPR","C":"0.20 EPR","D":"0.25 EPR"},"answer":"B","ref":"1C‐17A‐1, Section 1 Engines","topic":"Engines & APU"},{"n":35,"q":"In the event of boost pump failure, fuel can be suction fed by the engine driven fuel pump at ____ thrust rating up to an altitude of ____ ft and at a pitch angle no greater than 21.5 degrees","options":{"A":"MAX; 20,000","B":"INT; 20,000","C":"MAX; 10,000","D":"INT; 10,000"},"answer":"C","ref":"1C‐17A‐1, Section 1 Engines","topic":"Engines & APU"},{"n":36,"q":"The starter is designed to start the engine with normal starting loads. Excessive loads are applied when the engine driven hydraulic pumps are on. A ______ may result if the pumps are on during engine start.","options":{"A":"Hot Start","B":"Hung Start","C":"Cold Start","D":"Buddy Start"},"answer":"B","ref":"1C‐17A‐1, Section 1 Engines","topic":"Engines & APU"},{"n":37,"q":"Engine Start Buttons: The button will stay in until engine N2 RPM reaches approximately _____ percent.","options":{"A":"18","B":"30","C":"51","D":"55"},"answer":"C","ref":"1C‐17A‐1, Section 1 Engines","topic":"Engines & APU"},{"n":38,"q":"If FIREX AGENT DISCHARGE 1 POWER CB on the __________ is open, the ___________will be inoperative.","options":{"A":"overhead panel, APU Fire Agent DISCH switch","B":"right EPC, APU warning system","C":"left EPC, the APU warning system","D":"overhead panel, the APU fire and overspeed CAWS aural warning"},"answer":"A","ref":"1C‐17A‐1, Part 2 Interior Safety Inspection - Power Off","topic":"Emergency procedures"},{"n":39,"q":"Engine anti‐ice provides icing protection to the engine fan blades.","options":{"A":"True","B":"False"},"answer":"B","ref":"1C‐17A‐1, Section 1 Environmental systems","topic":"Engines & APU"},{"n":40,"q":"Do not change the ENGINE IGNITION source during engine start. Switching sources may result in a","options":{"A":"Hot Start","B":"Hung Start","C":"Tailpipe fire","D":"Sheared starter"},"answer":"C","ref":"1C‐17A‐1, Section 2 - Starting Engines","topic":"Engines & APU"},{"n":41,"q":"To prevent damage to the reverse interlock solenoids, do not move the throttle levers beyond the reverse idle detent until ____","options":{"A":"The pilot not flying says its OK","B":"Either the REV indication is illuminated on the MFD's or until the solenoids are heard to release","C":"Betty says \"thrust reversers deployed\"","D":"The nose wheel makes contact with the runway"},"answer":"B","ref":"1C‐17A‐1, Section 1 - Engines","topic":"Engines & APU"},{"n":42,"q":"If the starter valve will not close after engine start (light remains illuminated more than 30 seconds after the button pops out), which of the following actions could result in a starter failure?","options":{"A":"Selecting another ignition system","B":"Pulling out the starter valve push‐button","C":"Shutting down the engine after removing the bleed air supply","D":"Shutting down the engine before removing the bleed air supply"},"answer":"D","ref":"1C‐17A‐1, Section 2 - Starting Engines","topic":"Engines & APU"},{"n":43,"q":"Delay engine starter re‐engagement for ____ once N2 RPM indication is lost from the MFD engine display to ensure that engine rotation has stopped","options":{"A":"20 seconds","B":"30 seconds","C":"40 seconds","D":"1 minute"},"answer":"C","ref":"1C‐17A‐1, Section 2 - Engines","topic":"Engines & APU"},{"n":44,"q":"In addition to an engine fire and disintegration, the EMERGENCY ENGINE SHUTDOWN Checklist will be run with ____","options":{"A":"Seizure","B":"Engine sparking (continuous)","C":"Engine/pylon fuel leak (on the ground)","D":"All of the above"},"answer":"D","ref":"1C‐17A‐1, Para: 3‐212","topic":"Emergency procedures"},{"n":45,"q":"If an engine reverts to the N2 mode, all engine responses are normal except ____","options":{"A":"No reverse thrust is available during landing ground roll","B":"Touch and go landings are prohibited","C":"That no overspeed protection is provided","D":"The engine will lock 85% N2"},"answer":"C","ref":"1C‐17A‐1, Para: 3‐248","topic":"Emergency procedures"},{"n":46,"q":"If the N1 RPM indication drops to zero or all displays are blank, ____","options":{"A":"The EEC has failed","B":"This could indicate a catastrophic engine failure","C":"Shutdown and restart the engine to reset the EEC","D":"The EEC is running an internal test and the displays will return in 60 seconds"},"answer":"B","ref":"1C‐17A‐1, Para: 3‐210 (W)","topic":"Emergency procedures"},{"n":47,"q":"A Four Engine Flameout is likely to occur when flying through","options":{"A":"Heavy rain","B":"Hail and icing","C":"Volcanic ash","D":"All of the above"},"answer":"D","ref":"1C‐17A‐1, Para: 3‐255","topic":"Emergency procedures"},{"n":48,"q":"Four Engine Flameout: Wings level C‐17 glide ratio is _____.","options":{"A":"2.6 NM/1000 ft","B":"1 NM/1000 ft","C":"3.1 NM/1000 ft","D":"4.5 NM/1000 ft"},"answer":"A","ref":"1C‐17A‐1, Para: 3‐257 Step 9 (N)","topic":"Emergency procedures"},{"n":49,"q":"If experiencing severe engine vibration during flight,","options":{"A":"Execute a Precautionary Engine Shutdown","B":"Advance the engine throttles one at a time (from left to right) to isolate the vibrating engine","C":"Immediately shut down the engine using the Emergency Engine Shutdown Checklist","D":"Retard the engine throttles one at a time (from left to right) to isolate the vibrating engine"},"answer":"C","ref":"1C‐17A‐1, Para: 3‐275","topic":"Emergency procedures"},{"n":50,"q":"There is a maximum of ____ engine start attempts in one hour, followed by a ____ minimum cooling period","options":{"A":"2; 30 minute","B":"3; 45 minute","C":"4; 1 hour","D":"5; 1 hour"},"answer":"D","ref":"1C‐17A‐1, Para: 5‐29","topic":"General Aircraft Knowledge"},{"n":51,"q":"Engine rotation will be completely stopped before the starter is re‐engaged. The exception to this is in an emergency the starter may be re‐engaged after N2 RPM has decreased below____","options":{"A":"18‐24%","B":"20%","C":"0, the starter must always completely stop","D":"10%"},"answer":"B","ref":"1C‐17A‐1, Para: 5‐30 (N)","topic":"Engines & APU"},{"n":52,"q":"The maximum time limit at MAX/DRT thrust is ____ minutes when not needed for engine failure on takeoff, or engine out go around for obstacle clearance","options":{"A":"5","B":"10","C":"7","D":"There is no maximum time limit at MAX/DRT"},"answer":"A","ref":"1C‐17A‐1, Para: Table 5‐2","topic":"Engines & APU"},{"n":53,"q":"Maximum EGT for engine start is ______ degrees (ground) and ______ degrees (air)","options":{"A":"650, 750","B":"500, 655","C":"495, 655","D":"450, 650"},"answer":"C","ref":"1C‐17A‐1, Para: Table 5‐2","topic":"Engines & APU"},{"n":54,"q":"The recommended minimum airspeed for in‐flight reverse thrust is ______ or Vmma, whichever is higher.","options":{"A":"225","B":"200","C":"250","D":"300"},"answer":"C","ref":"1C‐17A‐1, Para: Table 5‐11 Note 3","topic":"Flight Controls & EFCS"},{"n":55,"q":"If flight through contaminated air is experienced with the air conditioning pack(s) operating, the conditioned airflow used for avionics cooling ____","options":{"A":"Is unaffected","B":"Will be contaminated","C":"Is filtered","D":"Is partially filtered"},"answer":"B","ref":"1C‐17A‐1, Para: 1‐715 (W)","topic":"General Aircraft Knowledge"},{"n":56,"q":"If the ambient temperatures are above ____ , avionics cooling air flow must be supplied from conditioned air augmentation (APU or air conditioner ground unit)","options":{"A":"100 degrees F","B":"95 degrees F","C":"90 degrees F","D":"85 degrees F"},"answer":"C","ref":"1C‐17A‐1, Para: 1‐732 (N)","topic":"Engines & APU"},{"n":57,"q":"Pitch Reference Trim is available ____","options":{"A":"Only with APPR mode engaged","B":"With the FCS ACTR Panel PITCH TRIM switch in EFCS","C":"With the FCS ACTR Panel PITCH TRIM switch in MECH","D":"B & C"},"answer":"D","ref":"1C‐17A‐1, Para: 1‐1045, 1‐1045(N)","topic":"Flight Controls & EFCS"},{"n":58,"q":"If the ________________ fails, automatic ground spoilers may not deploy during a rejected takeoff or subsequent landing.","options":{"A":"TOGA switch","B":"Speedbrake/DLC switch","C":"GND SPLR/LAPES switch","D":"Autothrottle disengage button"},"answer":"C","ref":"1C‐17A‐1, Para: 1‐1113 (W)","topic":"Limitations & Performance"},{"n":59,"q":"In frontside flight the default or basic mode for the AFCS pitch axis is the ____ mode","options":{"A":"Altitude select or capture","B":"Vertical Speed/Altitude Hold","C":"Speed Hold or select","D":"Split axis or turbulence"},"answer":"B","ref":"1C‐17A‐1, Para: 1‐1299","topic":"Avionics, MC & Nav"},{"n":60,"q":"The Alpha Speed function provides flight guidance and/or control to limit minimum airspeed to configuration Alpha Speed, which provides safe buffet or stall margin for the existing aircraft configuration (flaps, slats, thrust level, weight and altitude).","options":{"A":"TRUE","B":"FALSE"},"answer":"A","ref":"1C‐17A‐1, Para: 1‐1322","topic":"Limitations & Performance"},{"n":61,"q":"When the FPV drift angle exceeds the limit of the HUD or PFD field of view, pitch information from the flashing FPV is ___________ and only the ________ FPV symbol will provide correct vertical path information.","options":{"A":"Unusable, caged","B":"Useable, actual","C":"Unusable, actual","D":"Useable, caged"},"answer":"A","ref":"1C‐17A‐1, Para: 1‐1457 (W)","topic":"Limitations & Performance"},{"n":62,"q":"The Stall Warning System provides stick shaker and aural “STALL” alerts to pilots when flight conditions (airspeed) approach what range?","options":{"A":".95‐1.05 Vs","B":"1.05‐1.15 Vs","C":"Vmma – Vne","D":"1.33‐1.433 Vs"},"answer":"B","ref":"1C‐17A‐1, Para: 1‐1172","topic":"Flight Controls & EFCS"},{"n":63,"q":"Which action will not re‐arm spoilers for RTO mode during touch and go landings?","options":{"A":"Moving all four throttles to the idle reverse detent","B":"Momentarily pressing the TOGA switch","C":"Advancing at least three throttle levers past a threshold of 60 degrees","D":"Positioning the flap/slat handle to any new detent"},"answer":"A","ref":"1C‐17A‐1, Para: 1‐1116","topic":"Limitations & Performance"},{"n":64,"q":"(IRCM) Ground operations longer than ____ minutes with the outside air temperature above 38 degrees C / 100 degrees F may result in TX x FAIL and degraded IRCM performance","options":{"A":"25","B":"10","C":"5","D":"60"},"answer":"A","ref":"1C‐17A‐1, Para: 2‐1045 ( C )","topic":"Hot Weather & IRCM"},{"n":65,"q":"If takeoff roll or initial climbout is accompanied by unusual aircraft yaw motion or abnormal rudder movement, the EFCS may have reverted to FROZEN GAINS.","options":{"A":"Prior to Vgo, a reject is recommended","B":"If takeoff is continued, repeatedly press EFCS RESET, allowing 1 second between button presses.","C":"Transition to FCC FIXED GAIN is not available until Weight‐off‐wheels and A/R Mode is not engaged","D":"All of the above"},"answer":"D","ref":"1C‐17A‐1, Para: 3‐357","topic":"Flight Controls & EFCS"},{"n":66,"q":"(FCC FIXED GAIN) Large abrupt rudder inputs at speeds over ___ KCAS can overstress the vertical stabilizer and rudders","options":{"A":"250","B":"300","C":"225","D":"200"},"answer":"D","ref":"1C‐17A‐1, Para: Pg 3‐235 ( C )","topic":"Emergency procedures"},{"n":67,"q":"The maximum airspeed for extending the slats is ____; for retracting is ____","options":{"A":"270; 270","B":"280; 280","C":"270; 280","D":"280; 270"},"answer":"D","ref":"1C‐17A‐1, Para: Table 5‐11","topic":"Flight Controls & EFCS"},{"n":68,"q":"If a stall occurs","options":{"A":"Apply smooth, but positive forward stick","B":"Increase thrust to MAX and retract speed brakes (if required)","C":"Roll input to level the wings","D":"All of the above"},"answer":"D","ref":"(-1, Part 6, Flight Characteristics, Stalls, Stall Recovery)","topic":"Flight Controls & EFCS"},{"n":69,"q":"When the reported airfield temperature is ____ degrees C or above, the EFCS can revert to FROZEN GAINS.","options":{"A":"40","B":"43","C":"45","D":"50"},"answer":"B","ref":"(-1, Part 7, Hot Weather and Desert Operations, Potential Air Data Anomalies)","topic":"Hot Weather & IRCM"},{"n":70,"q":"If you encounter FROZEN GAINS, maintain airspeed within +/______ of the airspeed when FROZEN GAINS occurred.","options":{"A":"10 KCAS","B":"20 KCAS","C":"30 KCAS","D":"40 KCAS"},"answer":"C","ref":"(-1, Part 3, EFCS FROZEN GAINS)","topic":"Flight Controls & EFCS"},{"n":71,"q":"TRUE/FALSE If stabilized on approach speed and you encounter FROZEN GAINS, land in FROZEN GAINS.","options":{"A":"TRUE","B":"FALSE"},"answer":"A","ref":"(-1, Part 3, EFCS FROZEN GAINS)","topic":"Flight Controls & EFCS"},{"n":72,"q":"What is the fuel allowance for a typical approach and landing?","options":{"A":"2,500 lbs","B":"3,100 lbs","C":"3,500 lbs","D":"3,800 lbs"},"answer":"D","ref":"(-1-1, Part 11, Mission Planning and Miscellaneous, Approach and Landing Fuel Consumption)","topic":"Fuel & OBIGGS"},{"n":73,"q":"The desired fuel imbalance between left and right wings is _____ pounds and between inboard and outboard tanks is _______ pounds.","options":{"A":"1000; 1000","B":"8000; 1500","C":"8000; 1000","D":"1000; 8000"},"answer":"A","ref":"(-1, Part 2, Cockpit Pre-flight Step 7)","topic":"Normal Procedures"},{"n":74,"q":"If an individual fuel tank indicator on the overhead is inoperative, the totalizer shows","options":{"A":"Correct total fuel","B":"A blank window","C":"A series of dashes","D":"Estimated fuel"},"answer":"A","ref":"(-1, Part 1, List of Illustrations, Total Fuel Indicator NOTE)","topic":"Fuel & OBIGGS"},{"n":75,"q":"When fuel quantities drop below approximately ____ lbs for the inboard tanks and ____ lbs for the outboard tanks, the respective transfer pumps become uncovered and ineffective","options":{"A":"37,400; 24,500","B":"28,000; 12,000","C":"16,000; 4,000","D":"27,500; 16,000"},"answer":"B","ref":"(-1, Part 1, List of Illustrations, Fuel System Panel NOTE)","topic":"Fuel & OBIGGS"},{"n":76,"q":"Fuel dump above ____ feet may cause engine flameout due to loss of fuel pressure","options":{"A":"20,000","B":"15,000","C":"17,500","D":"10,000"},"answer":"A","ref":"(-1, Part 3, Fuel Dumping WARNING)","topic":"Fuel & OBIGGS"},{"n":77,"q":"Normally fuel dump is accomplished with the centre separation valve closed. Confirm that both lights illuminate or","options":{"A":"Check for open feeder circuit breakers","B":"Cycle the dump switch from off to on","C":"Open the separation valve immediately","D":"Discontinue fuel dumping and land as soon as practical"},"answer":"C","ref":"(-1, Part 3, Fuel Dumping Step 10 CAUTION)","topic":"Fuel & OBIGGS"},{"n":78,"q":"OBIGGS II with ASM ALERT WCC(s) will fail when electrically powered for greater than _____ continuous hours with both left and right OBIGGS systems selected OFF or Failed/Disabled.","options":{"A":"11","B":"13","C":"15","D":"17"},"answer":"D","ref":"(-1, Part 1, OBIGGS II)","topic":"Fuel & OBIGGS"},{"n":79,"q":"GPWS Mode 4C (gear down, flaps 1/2 detent or less and below 500 feet radar altitude) is inoperative when ____","options":{"A":"Performing circling approaches","B":"TAWS is active","C":"TACTICAL mode is selected","D":"When flying a \"frontside\" approach"},"answer":"C","ref":"(-1, Part 1, GPWS Modes, Mode 4C NOTE)","topic":"Avionics, MC & Nav"},{"n":80,"q":"During taxi with speed greater than 20 knots with symmetric thrust (15 knots with asymmetric thrust), a 20-degree nose wheel steering angle limit applies if gross weight exceeds ____ lbs or with more than ____ lbs of fuel.","options":{"A":"490,000; 135,000","B":"502,100; 135,000","C":"490,000; 165,000","D":"502,100; 165,000"},"answer":"C","ref":"(-1, Part 5, Operating Limitations, List of Tables, Taxi Limits)","topic":"Landing Gear & Brakes"},{"n":81,"q":"The maximum taxi speed for paved taxiways is ____ knots; maximum taxiway speed for semi prepared taxiways is ____ knots","options":{"A":"30; 40","B":"40; 30","C":"30; 20","D":"20; 30"},"answer":"B","ref":"(-1, Part 5, Operating Limitations, List of Tables, Taxi Limits and Semi-Prepared Airfield Taxi Limits)","topic":"Landing Gear & Brakes"},{"n":82,"q":"Minimum runway/taxiway widths for C 17 operations are:","options":{"A":"150 ft runway, 90 ft taxiway","B":"100 ft runway, 70 ft taxiway","C":"90 ft runway, 50 ft taxiway","D":"75 ft runway, 45 ft taxiway"},"answer":"C","ref":"(Ops Manual Part B Basic Section 1.1)","topic":"Regulations & Ops Manual"},{"n":83,"q":"Do not taxi an aircraft within ___ feet of obstructions without wing walkers monitoring clearance between aircraft and obstructions. With wing walkers, avoid taxi obstructions by at least ___ feet.","options":{"A":"25; 10","B":"25; 25","C":"15; 10","D":"10; 5"},"answer":"A","ref":"(Ops Manual Part B Basic 2.6.2)","topic":"Regulations & Ops Manual"},{"n":84,"q":"From the left seat an imaginary line drawn from the row of rivets inside the number ___ engine cowling at approximately the___ o'clock position closely identifies 25-foot wingtip clearance","options":{"A":"1; 4 -","B":"2; 4","C":"1; 6","D":"3; 4"},"answer":"A","ref":"(Ops Manual Part B Basic 2.6.3)","topic":"Regulations & Ops Manual"},{"n":85,"q":"Taxi Centreline References: While taxiing the aircraft straight ahead, the position of the nosewheel is approximated by __________.","options":{"A":"the inboard screw of the heads-up display (HUD)","B":"the inboard leg of the pilot flying (PF)","C":"the first inboard dot of the lateral deviation indicator in the HUD","D":"all of the above"},"answer":"D","ref":"(Ops Manual Part B Basic 2.6.3)","topic":"Regulations & Ops Manual"},{"n":86,"q":"On a dry surface with symmetric engine thrust and no differential braking, the aircraft can execute a 180 degree turn in _____ feet.","options":{"A":"90","B":"143","C":"116","D":"175"},"answer":"B","ref":"(Ops Manual Part B Basic 2.6.4)","topic":"Regulations & Ops Manual"},{"n":87,"q":"Operating engines in idle reverse thrust for extended periods during high OAT's may cause one or more engine FIREX bottles to discharge uncommanded.","options":{"A":"True","B":"False"},"answer":"A","ref":"(-1, Part 2, Operational Stop Step13 CAUTION)","topic":"Emergency procedures"},{"n":88,"q":"The primary purpose of the transfer pump is to ____ in the event of No. 2 or No. 3 engine loss","options":{"A":"Assist in cargo door/ramp closing","B":"Assist in landing gear retraction","C":"Both A and B","D":"None of the above"},"answer":"C","ref":"(-1, Part 1, Hydraulic System Differences, Transfer Pump)","topic":"Electrics & Hydraulics"},{"n":89,"q":"The HSC determines the on-demand pump operation in the following sequence of priority for hydraulic system No. 3","options":{"A":"Primary, secondary, XFER, AUX pump","B":"Primary, secondary, AUX, XFER pump","C":"Primary, secondary, XFER, AUX pump, RAT","D":"Primary, secondary, XFER pump, RAT"},"answer":"A","ref":"(-1, Part 1, Controls and Indicators, Hydraulic System Controllers)","topic":"Electrics & Hydraulics"},{"n":90,"q":"Do not attempt take-off with any hydraulic reservoir temperature indicating less than ____ degrees C. Low rudder temperature indicates insufficient rate of rudder deflection to correct for an engine failure on take-off","options":{"A":"17","B":"0","C":"7","D":"-7"},"answer":"C","ref":"(-1, Part 2, Line-up Step 4 WARNING)","topic":"Normal Procedures"},{"n":91,"q":"Primary flight controls are powered by how many hydraulic systems?","options":{"A":"1","B":"2","C":"3","D":"4"},"answer":"B","ref":"(-1, Part 3, Hydraulic System (X) Pressure Low, Step 3 NOTE)","topic":"Electrics & Hydraulics"},{"n":92,"q":"If steering commands from the tillers and rudder pedals are in disagreement","options":{"A":"The rudder command will be overridden.","B":"The tiller command will be overridden.","C":"The system blends the rates to provide steering","D":"The greater command is used"},"answer":"A","ref":"(-1, Part 1, Landing Gear System, Nose Wheel Steering)","topic":"Landing Gear & Brakes"},{"n":93,"q":"Which hydraulic system powers the normal brakes?","options":{"A":"No. 1","B":"No. 2","C":"No. 3","D":"No. 4"},"answer":"B","ref":"(-1, Part 1, Landing Gear System, Brake System)","topic":"Landing Gear & Brakes"},{"n":94,"q":"If ground speed on the MFD ND appears excessive:","options":{"A":"No action is required","B":"All four IRU's should be realigned if on the ground","C":"In flight turn off the IRU being used for navigation","D":"Re-align only the IRU in large font on the appropriate NAV SENSORS page"},"answer":"B","ref":"(-1, Part 1, Landing Gear System, Anti-Skid System)","topic":"Landing Gear & Brakes"},{"n":95,"q":"In the event of large disparity between the IRU ground speed and the anti-skid brake controller sensed ground speed, braking capability will be reduced. If in flight, accomplish the landing using ____","options":{"A":"Normal procedures","B":"One brake inoperative procedure","C":"Landing with Erroneous Ground Speed procedure.","D":"Anti-skid inop procedures"},"answer":"C","ref":"(-1, Part 1, Landing Gear System, Anti-Skid System)","topic":"Landing Gear & Brakes"},{"n":96,"q":"What is the maximum airspeed allowable for extending the landing gear?","options":{"A":"225","B":"250","C":"275","D":"300"},"answer":"B","ref":"(-1, Part 5, Operating Limitations, Configuration Limitations)","topic":"Limitations & Performance"},{"n":97,"q":"(Tire cord limits) The maximum wear limit (MWL) is defined as the exposure of the ______ cord layer plus _____ additional landings.","options":{"A":"third, two","B":"third, five","C":"second, five","D":"second, three"},"answer":"A","ref":"(-1, Part 5, Operating Limitations, Tire Limits)","topic":"Landing Gear & Brakes"},{"n":98,"q":"After an MC Degraded Mode, the MC may generate extreme navigation errors, as indicated by PPOS related depictions shifting on the MFD. No sooner than 10 seconds after recovery from a Degraded Mode, perform a FLUSH ALL.","options":{"A":"TRUE","B":"FALSE"},"answer":"A","ref":"(-1-2, Part 1, Radio Update Types, Update Purging CAUTION)","topic":"General Aircraft Knowledge"},{"n":99,"q":"When checking the mission computer bus controller status in the Before Taxi Checklist, if MC1/MC2 are not in proper BC/BU configuration, _____________ may occur.","options":{"A":"Permanent Degraded Mode","B":"Exceptional Restart","C":"Orchestrated Restart","D":"FLUSH ALL message"},"answer":"A","ref":"(-1, Part 2, Before Taxi Step 7 CAUTION)","topic":"Landing Gear & Brakes"},{"n":100,"q":"A personnel restraining harness or parachute is required to be worn ____","options":{"A":"During all emergencies that may require a bailout","B":"During low level flight below 500 AGL","C":"When inspecting aircraft doors after an in-flight door/hatch warning","D":"Only when directed by the aircraft commander"},"answer":"D","ref":"-1, Part 3, Door Warning (In Flight)","topic":"Cargo, Doors & Equipment"},{"n":101,"q":"What is the aircraft configuration for an emergency descent?","options":{"A":"Flaps 1/2; gear down; throttles – IDLE","B":"Speed Brakes – Deployed; Gear down; N2 - 85%","C":"Clean; Throttles – IDLE; Airspeed – 310 Kts","D":"Throttles - IDLE or IDLE REV; Speed Brakes - Deployed (As Required); Airspeed – (As Required)"},"answer":"D","ref":"(-1, Part 3, Emergency Descent)","topic":"Emergency procedures"},{"n":102,"q":"The TO 1C‐17A‐1 provides __________operating instructions under __________ circumstances, but it is not a substitute for __________. Multiple emergencies, adverse weather, terrain, etc. may require modification of the procedures.","options":{"A":"adequate; all; sound judgement","B":"the best possible; most; sound judgement","C":"adequate; most; airmanship","D":"the best possible; most; airmanship"},"answer":"B","ref":"1C‐17A‐1 , Para: iii","topic":"Regulations & Ops Manual"},{"n":103,"q":"Wind component data displayed on the Map and Compass Formats of the MFDs display mission computer‐filtered solutions of air data over the past _____ seconds.","options":{"A":"120","B":"10","C":"60","D":"30"},"answer":"C","ref":"1C‐17A‐1, Section 1, Air Data Computer Instruments, Compass Format, Figure 183, Sheet 9.","topic":"Avionics, MC & Nav"},{"n":104,"q":"When turbulence is encountered or expected, ________ ignition will be used.","options":{"A":"A","B":"B","C":"A&B","D":"either A or B"},"answer":"C","ref":"1C‐17A‐1, Section 2, Cruise Checklist.","topic":"Normal Procedures"},{"n":105,"q":"During a rejected takeoff ____","options":{"A":"Use MAX reverse on all operating engines","B":"All four throttles to idle reverse, then only use symmetrical throttles beyond idle reverse.","C":"Do not use reverse thrust","D":"Use MAX reverse on the side with good engines and MAX brakes on the other side"},"answer":"B","ref":"1C‐17A‐1, Section 3, Miscellaneous Procedures, Rejected Takeoff.","topic":"Emergency procedures"},{"n":106,"q":"Crew duty time begins ____","options":{"A":"When the first crew member reports for flying duties","B":"At alert time","C":"When the crew member arrives at the squadron","D":"As designated by the aircraft commander"},"answer":"A","ref":"Ops Manual Part A, Section 7, CDT.","topic":"Regulations & Ops Manual"},{"n":107,"q":"The maximum CDT for a 1-4 sectors ____ hours; for 5 or more ____ hours","options":{"A":"12; 16","B":"20; 24+45","C":"16; 14","D":"18; 24+45"},"answer":"C","ref":"Ops Manual Part A, Section 7, Normal Peacetime CDT and CRP by type.","topic":"Regulations & Ops Manual"},{"n":108,"q":"Destination Requirements: File two alternates when:","options":{"A":"The period +/-1 hr ETA, the weather conditions are below the applicable planning minima","B":"GPS is the only available NAVAID at destination","C":"No meteorological information is available","D":"A or C"},"answer":"D","ref":"Ops Manual Part A, section 8, Destination Alternates Required.","topic":"Regulations & Ops Manual"},{"n":109,"q":"For RNAV approaches, ensure that the ________ is updating the MC position for civil approaches.","options":{"A":"MGPS","B":"CGPS","C":"Selected GPS source","D":"IRU"},"answer":"C","ref":"1C‐17A‐1 , Section 2, Approach Procedures.","topic":"Avionics, MC & Nav"},{"n":110,"q":"To select the IRU1/MGPS1 blended solution present position (PPOS) with CGPS containment for navigation, use the following configuration :","options":{"A":"Pilot ID switch on (P) pilot side, CGPS UPDATE selected on LSK 2L of NAV SENSORS ‐ CONTROL page 6/7.","B":"Pilot ID switch on (P) pilot side, MGPS UPDATE selected on LSK 2L of NAV SENSORS ‐ CONTROL page 6/7.","C":"Pilot ID switch on (CP) copilot side, DISABLED selected on LSK 2L of NAV SENSORS ‐ CONTROL page 6/7.","D":"Pilot ID switch on either pilot (P) or (CP) copilot side, FLUSH* ALL enabled on NAV SENSORS ‐ CONTROL page 6/7."},"answer":"A","ref":"1C‐17A‐1‐2, Section 1, Performance Based Navigation, Update Status.","topic":"Avionics, MC & Nav"},{"n":111,"q":"The cabin pressurization SEMI mode controls cabin pressure according to","options":{"A":"The baro‐corrected altitude set in the LDG ALT‐FT display window","B":"An optimum schedule determined by the A/PDMC","C":"A schedule of 3000 ft. AGL along the mission computer flight plan","D":"The altitude set in the window on the AFCS panel adjusted for terrain elevation from the NAV database"},"answer":"A","ref":"1C‐17A‐1, Section 1, Environmental Systems, Semiautomatic Mode.","topic":"Pressurisation, ECS & Oxygen"},{"n":112,"q":"When the CREW OXY LOW message illuminates on the WAP, it indicates","options":{"A":"Oxygen quantity remaining in the passenger converter is 2.5 liters or less","B":"Oxygen quantity is less than 7.5 liters or supply pressure is below 60 +/‐ 5 psi","C":"Oxygen quantity remaining in the crew converter is 2.5 liters or less","D":"Oxygen quantity is less than 5 liters or supply pressure is below 60 +/‐ 5 psi"},"answer":"D","ref":"1C‐17A‐1, Section 1, Oxygen System, Crew Oxygen System.","topic":"Pressurisation, ECS & Oxygen"},{"n":113,"q":"(Assuming the aircraft has accelerated to 250 KCAS or VMSR) During a Standard Departure Profile, the PM will engage the desired climb power on the SED _______. During the Alternate Departure Profile, the PM will engage the desired climb power on the SED","options":{"A":"only after slat retraction; only after slat retraction","B":"only after slat retraction; when directed by the PF","C":"when directed by the PF; when directed by the PF","D":"when directed by the PF; only after slat retraction"},"answer":"C","ref":"1C‐17A‐1, Section 2, Takeoff, Standard Departure Profile.","topic":"Normal Procedures"},{"n":114,"q":"Pressing SC ZERO whenever the IRUs are in the ON position erases encryption keys, almanac and position information, forcing the __________ to reacquire. It will take much longer than normal on the next power up for the _________ to synchronize.","options":{"A":"IRUs, IRUs","B":"RADIO UPDATE, IRUs","C":"( C )GPS, ( C )GPS","D":"(M)GPS, (M)GPS"},"answer":"D","ref":"1C‐17A‐1, Section 1, Communication and Navigation Equipment, Mission Computer Display Keyboard.","topic":"Avionics, MC & Nav"},{"n":115,"q":"For an RSC greater than _____ and an RCR less than _____, the actual runway required for takeoff/landing could exceed runway available.","options":{"A":".01, 12","B":"01, 23","C":".00, 5","D":".00, 12"},"answer":"D","ref":"1C‐17A‐1, Section 2, Cockpit Preflight Checklist, Mission Computer Data.","topic":"Avionics, MC & Nav"},{"n":116,"q":"Each successful FCC and SC/EFC preflight BITs (PFBIT) can be considered valid for a period of ____ hours provided FCC, SC/EFC, flight control or hydraulic system integrity have not been compromised during that time period. Reaccomplish the PFBIT if maintenance has been performed on any of these systems.","options":{"A":"24","B":"48","C":"12","D":"72"},"answer":"D","ref":"1C‐17A‐1 , Section 2, Systems Procedures, Flight Controls, FCC and SC/EFC Preflight Bits.","topic":"Flight Controls & EFCS"},{"n":117,"q":"In general, address malfunctions in the following order:","options":{"A":"Aural CAWS, MASTER WARNING, WAP Message, EFCS/MISSION STATUS page","B":"Aural CAWS, MASTER WARNING, MASTER CAUTION, EFCS/MISSION STATUS page","C":". MASTER WARNING, MASTER CAUTION, Cue Alert, WAP Message","D":"WAP Message, MASTER WARNING, MASTER CAUTION, EFCS/MISSION STATUS page"},"answer":"B","ref":"1C‐17A‐1, Section 3, Introduction.","topic":"Regulations & Ops Manual"},{"n":118,"q":"Land as soon as possible means a landing should be accomplished at the nearest suitable airfield, whereas land as soon as practical means landing at the nearest suitable airfield may not be necessary.","options":{"A":"TRUE","B":"FALSE"},"answer":"A","ref":"1C‐17A‐1, Section 3, Landing Considerations.","topic":"Emergency procedures"},{"n":119,"q":"The following rules should be followed regarding circuit breakers:","options":{"A":"Do not reset or cycle any fuel pump circuit breaker.","B":"Never pull and reset circuit breakers as a means to recover lost components unless directed to do so.","C":"Except where prohibited by specific procedures, open circuit breakers may be reset once.","D":"All of the above."},"answer":"D","ref":"1C‐17A‐1, Section 3, Circuit Breakers.","topic":"Emergency procedures"},{"n":120,"q":"Whenever using EFCS RESET, allow ___ seconds after pressing the button for the LRU to be reset and EFCS RESET to extinguish from the WAP, unless directed otherwise in the procedure.","options":{"A":"60","B":"30","C":"10","D":"5"},"answer":"D","ref":"1C‐17A‐1, Section 3, System Malfunction Methodologies, EFCS Reset.","topic":"Flight Controls & EFCS"},{"n":121,"q":"The warning bell signals for Crash Landing are: Immediately after takeoff ______ ring(s), Prepare for crash landing _____ ring(s), Brace for impact ________ ring(s).","options":{"A":"two short, six short, one long","B":"one long, six short, one long","C":"three short, six short, one long","D":"three short, three short, one long"},"answer":"B","ref":"1C‐17A‐1, Section 3, Emergency Signals.","topic":"Emergency procedures"},{"n":122,"q":"The Ground Evacuation checklist is designed to be run by ____________ for the Engines Not Running section and by ____________ for the Engines Running section.","options":{"A":"the loadmaster only, all crew members","B":"any crew member, the pilots only","C":"a single crew member, all crew members","D":"the loadmaster only, the pilots only"},"answer":"C","ref":"1C‐17A‐1, Section 3, Ground Evacuation.","topic":"Emergency procedures"},{"n":123,"q":"Prior to completing a critical action, the PM shall point to the affected switch/handle/lever and verbally seek confirmation from the PF.","options":{"A":"TRUE","B":"FALSE"},"answer":"A","ref":"1C‐17A‐1, Section 3, Crew Co-Ordination.","topic":"Regulations & Ops Manual"},{"n":124,"q":"The GROUND EVACUATION checklist is only located:","options":{"A":"at the beginning of the WARN section","B":"at the end of the EMERGENCY ENGINE SHUTDOWN Procedure","C":"in the Quick Reaction Guide (QRG)","D":"at the end of the FUSELAGE FIRE FILTER Procedure"},"answer":"C","ref":"1C‐17A‐1, Section 3, Quick Reaction Guide.","topic":"Emergency procedures"},{"n":125,"q":"If entering a tactical environment immediately after takeoff, TACTICAL can be selected on the GPWS/TAWS CONTROL page, but the displays will not switch to tactical until the ____","options":{"A":"Aircraft is farther than 15nm from the runway","B":"Aircraft is above 1500 feet AGL","C":"Aircraft is above 2500 feet AGL","D":"Either A or B"},"answer":"D","ref":"1C‐17A‐1, Section 1, List of Tables, ‘GPWS/TAWS WAP Annunciations.’","topic":"Avionics, MC & Nav"},{"n":126,"q":"(Thrust Reverser Status, 3L) When a SPAM runway is selected for emergency return or landing, the MC adds another thrust reverser selection for four engines (4ENG). 4ENG assumes","options":{"A":"two engines in forward thrust and two engines in idle reverse","B":"four engines in idle reverse for 33% of the landing roll out","C":"loss of one engine, one engine in idle reverse, and symmetric engines in maximum reverse","D":"all four engines operating and in maximum reverse thrust"},"answer":"D","ref":"1C‐17A‐1‐2, Section 1, Non Standard Config Page.","topic":"Engines & APU"},{"n":127,"q":"When operating into semi‐prepared runways, aircrews must input the numerical rolling friction factor (RFF) into the mission computer to calculate take‐off data prior to landing","options":{"A":"True","B":"False"},"answer":"A","ref":"Ops Manual Part B Applied 10.3","topic":"Regulations & Ops Manual"},{"n":128,"q":"To back the C‐17 when all four engines overhang a prepared surface, ________","options":{"A":"Stagger the outboard throttles 1/4 to 3/4 knob width relative to the inboard throttles, with the outboards providing greater reverse thrust (frowny face)","B":"Modulate reverse thrust on the inboard engines while holding outboard throttles at or near idle reverse (smiley face)","C":"Move all four throttles to reverse equally","D":"Avoid asymmetric thrust"},"answer":"A","ref":"1C‐17A‐1, Section 2, List of Tables, ‘Reverse Thrust During Ground Manouevring .’","topic":"Engines & APU"},{"n":129,"q":"To back the C‐17 when any outboard engine overhangs an unprepared or debris covered surface, with inboard engines completely over a prepared debris‐free surface ___________","options":{"A":"Stagger the outboard throttles 1/4 to 3/4 knob width relative to the inboard throttles, with the outboards providing greater reverse thrust (frowny face)","B":"Modulate reverse thrust on the inboard engines while holding outboard throttles at or near idle reverse (smiley face)","C":"Move all four throttles to reverse equally","D":"Avoid asymmetric thrust"},"answer":"B","ref":"1C‐17A‐1, Section 2, List of Tables, ‘Reverse Thrust During Ground Manouevring .’","topic":"Engines & APU"},{"n":130,"q":"If a GPWS/TAWS aural or visual warning is received during an approach in Instrument Meteorological Conditions (IMC), ____. Exceptions will be annotated in command guidance.","options":{"A":"Execute a missed approach or go around","B":"Check radar altimeter and continue if at a safe altitude","C":"Check GPWS since it may be malfunctioning","D":"Confirm your position with approach control and continue if you are on a published segment of the approach"},"answer":"A","ref":"1C‐17A‐1, Para: 2‐167 (W)","topic":"Avionics, MC & Nav"},{"n":131,"q":"The F/D Traffic Collision Avoidance System (TCAS) submode is engaged by pressing the ____ when a TCAS Resolution Advisory (RA) is present and the A/R mode is not engaged","options":{"A":"PPI button on the MFD","B":"AP disengage switch on either control stick","C":"TCAS button on the MCK","D":"TOGA button"},"answer":"B","ref":"1C‐17A‐1, Section 1, AFCS, Other AFCS Functions.","topic":"Avionics, MC & Nav"},{"n":132,"q":"A target aircraft is within 6NM and could be potentially hazardous. This is ____","options":{"A":"Other Traffic","B":"Proximate Traffic","C":"A Traffic Advisory (TA)","D":"A Resolution Advisory (RA)"},"answer":"C","ref":"1C‐17A‐1, Section 1, Warning Systems, TCAS.","topic":"Avionics, MC & Nav"},{"n":133,"q":"The PPI SKE and ND MAP formats depict only ____ altitudes for TCAS traffic","options":{"A":"Absolute","B":"Actual","C":"AGL","D":"Relative"},"answer":"D","ref":"1C‐17A‐1, Section 1, Warning Systems, TCAS Fig 1-210 Sheet 4.","topic":"Avionics, MC & Nav"},{"n":134,"q":"The Standard Departure Profile uses a select MC data element, __________, and aero performance data, rather than an MC calculated solution, to validate the aircraft flight path meets or exceeds a given climb gradient when flown as published.","options":{"A":"CLB RATE / ALT 4 ENG","B":"CFL","C":"MC COF: ACT","D":"MC COF: REQ"},"answer":"C","ref":"1C‐17A‐1, Section 2, Takeoff, Standard Departure Profile.","topic":"Normal Procedures"},{"n":135,"q":"BLOCK 19‐>: Use the lower of the following two altitudes to determine the planned 3‐engine acceleration altitude:","options":{"A":"MC ACC ALT, MIN IFR Altitude","B":"1000 feet AFE, ODP Altitude","C":"SDP LOA, MSA","D":"MOCA, OROCA"},"answer":"A","ref":"1C‐17A‐1, Section 3, Engine System, Engine Failure.","topic":"Emergency procedures"},{"n":136,"q":"During high ambient air temperatures and reverse idle conditions, primary TOLD and allowable cargo load calculations may be overly restrictive. Use secondary TOLD to compare against primary TOLD to determine if allowable cargo load is overly restrictive.","options":{"A":"TRUE","B":"FALSE"},"answer":"A","ref":"1C‐17A‐1, Section 2, Factors Affecting Engine Performance, Temperature.","topic":"Engines & APU"},{"n":137,"q":"If AGS does not deploy on landing, DLC spoilers are available to manually deploy _____ of AGS effectiveness.","options":{"A":"25 percent","B":"5 percent","C":"50 percent","D":"15 percent"},"answer":"A","ref":"1C‐17A‐1, Section 2, Normal Operating Procedures, Landing.","topic":"Normal Procedures"},{"n":138,"q":"Intermediate Thrust Rating (INT) is ____. This is the recommended rating for engine‐out climbs.","options":{"A":"the maximum thrust approved for the engine","B":"The maximum thrust certified for continuous use","C":"The maximum thrust recommended for normal climb operation","D":"The minimum MC calculated thrust setting required to safely perform a takeoff"},"answer":"B","ref":"1C‐17A‐1‐1, Part 2, Definition of Terms, Intermediate Thrust Rating.","topic":"Engines & APU"},{"n":139,"q":"Maximum Continuous Thrust (MCT) rating is ____","options":{"A":"The maximum thrust approved for the engine","B":"This is the recommended rating for engine‐out climb","C":"The maximum thrust recommended for normal climb operation","D":"The minimum MC calculated thrust setting required to safely perform a takeoff"},"answer":"C","ref":"1C‐17A‐1‐1, Part 2, Definition of Terms, Maximum Continuous Thrust Rating.","topic":"Engines & APU"},{"n":140,"q":"Go speed (VGO) is the lowest of _____, _____, or _____.","options":{"A":"V1, VCEF, VBO","B":"VMCO, VMCG, VMCA","C":"VROT, VR, VBMAX","D":"VMFR, VMSR, VTD"},"answer":"C","ref":"1C‐17A‐1‐1, Part 3, Definition of Terms, Go Speed.","topic":"Limitations & Performance"},{"n":141,"q":"The aircraft static air temperature shall not be used for takeoff calculation since heat radiation picked up by the sensing element can cause considerable error. Using an incorrect temperature may result in an unsafe takeoff.","options":{"A":"True","B":"False"},"answer":"A","ref":"1C‐17A‐1‐1, Part 3, Factors/Conditions Affecting Take-off and Climb out Performance, Temperature.","topic":"Limitations & Performance"},{"n":142,"q":"A lineup distance penalty must be applied anytime the takeoff is not commenced from the beginning of the usable runway. Apply a standard distance of ____ feet to account for turning the aircraft around on the runway or accessing the runway from a taxiway","options":{"A":"100","B":"80","C":"250","D":"200"},"answer":"C","ref":"1C‐17A‐1‐1, Part 3, Factors/Conditions Affecting Take-off and Climb out Performance, Line up Distance.","topic":"Limitations & Performance"},{"n":143,"q":"MC TOLD: If VBO LDG DIST exceeds __________ and LDG DIST is valid, VBO LDG DIST is highlighted and VBO LD DIST/nnn.nGW (MSG) is generated. If VBO GND ROLL exceeds __________ and GND ROLL is valid, VBO GND ROLL is highlighted and VBO GD ROLL/nnn.nGW (MSG","options":{"A":"CFL, CFL","B":"RWY AVAIL, RWY AVAIL","C":"GND ROLL + 500 feet, GND ROLL + 500 feet","D":"TORA, TODA"},"answer":"B","ref":"1C‐17A‐1‐2, Section 1, Maximum Breaks on Speed Landing Distance or Ground Roll.","topic":"Limitations & Performance"},{"n":144,"q":"[Block 19D] MC ACC ALT calculations may allow level‐off acceleration altitudes well below obstacle/climb gradient altitudes. Compliance with ___________ is essential in achieving computed performance capability.","options":{"A":"Climb out procedures","B":"ATC instructions","C":"Flight director cues","D":"TAWS alerts"},"answer":"A","ref":"1C‐17A‐1, Section 3, Engine Procedures, MC Three Engine Acceleration Altitude Determination.","topic":"Emergency procedures"},{"n":145,"q":"For ¾ flap precision approaches with glide path angles steeper than 3.2 degrees, increase landing distance by _____ feet and do not exceed _____ feet per minute descent rate.","options":{"A":"300; 900","B":"300; 1,000","C":"500; 900","D":"500; 1,000"},"answer":"A","ref":"1C‐17A‐1 , Section 2, Normal Operating Procedures, Precision Instrument Approaches.","topic":"Avionics, MC & Nav"},{"n":146,"q":"For full flap precision approaches (non‐assault) with glide path angles between 3.8 degrees and the MC calculated full flap approach angle, increase landing distance by _____ feet. This can be accomplished in the MC by reducing runway available by _____","options":{"A":"300; 300","B":"400; 400","C":"500; 500","D":"600; 600"},"answer":"D","ref":"1C‐17A‐1, Section 2, Normal Operating Procedures, Precision Instrument Approaches.","topic":"Avionics, MC & Nav"},{"n":147,"q":"[Block 19D] The MC uses _____________ thrust to compute ACC ALT, including when evaluating three engine climb gradients.","options":{"A":"MAX","B":"INT","C":"The selected takeoff","D":"DRT"},"answer":"C","ref":"1C‐17A‐1, Section 3, Engine Procedures, MC Three Engine Acceleration Altitude Determination.","topic":"Emergency procedures"},{"n":148,"q":"When taking off from an airfield with a pressure altitude over ________ feet, review Operations at High Altitude Airports procedures in Section VII.","options":{"A":"5,000","B":"1,500","C":"8,000","D":"12,500"},"answer":"C","ref":"1C‐17A‐1, Section 2, Normal Operating Procedures, Take Off.","topic":"Normal Procedures"},{"n":149,"q":"After an in‐flight Degraded Mode, the MC re‐enables ____________________, which will assert during subsequent touch‐and go landings or go‐around‐after‐touchdowns.","options":{"A":"Takeoff warnings (“FLAPS,” “STABILIZER,” etc.)","B":"TOGA","C":"Historic TOLD","D":"The secondary flight plan"},"answer":"A","ref":"1C‐17A‐1, Section 2, Normal Operating Procedures, Touch and Go Landings.","topic":"Normal Procedures"},{"n":150,"q":"If ALS is flashing when the aircraft reference symbol representing aircraft pitch attitude is within _____ degrees of the flight path, the ALS is erroneously activating.","options":{"A":"10","B":"16","C":"8","D":"12"},"answer":"C","ref":"1C‐17A‐1, Section 3, Flight Control Procedures, Erroneous ALS/Stall Warnings (Nose Damage).","topic":"Flight Controls & EFCS"},{"n":151,"q":"During touch and go landings, takeoff warnings are inhibited.","options":{"A":"True","B":"False"},"answer":"A","ref":"1C‐17A‐1, Section 2, Normal Operating Procedures, Touch and Go Landings.","topic":"Normal Procedures"},{"n":152,"q":"Flight through extremely heavy rain, particularly with low thrust settings (< 45% N1)","options":{"A":"May result in flameout of one or more engines","B":"May cause fluctuations in engine performance","C":"Should be accomplished using A & B ignition","D":"Provides an acceptable means of tactical threat avoidance"},"answer":"A","ref":"1C‐17A‐1, Section 7, Adverse Conditions, Rain and Hydroplaning.","topic":"Cold & Adverse Weather"},{"n":153,"q":"____ should be used for flight in known or anticipated turbulent air","options":{"A":"The turbulence mode of the auto pilot","B":"Extreme caution","C":"Engine ignition","D":"Slow speeds"},"answer":"C","ref":"1C‐17A‐1, Section 7, Adverse Conditions, Turbulence, Thunderstorms and Heavy Rain/Hail.","topic":"Cold & Adverse Weather"},{"n":154,"q":"During wind shear recovery, unless a sink rate exists, do not exceed ____ degrees of pitch below ____ feet","options":{"A":"12; 200","B":"10‐15; 300","C":"12‐15; 200","D":"15; 200"},"answer":"D","ref":"1C‐17A‐1, Section 7, Adverse Conditions, Windshear, Takeoff Recovery Procedures.","topic":"Cold & Adverse Weather"},{"n":155,"q":"If icing conditions are present, engine anti‐ice must be used continuously to help prevent _______________.","options":{"A":"Engine damage due to ice ingestion","B":"Engine flameout","C":"Reversion to the N1 mode","D":"Severe compressor stalls"},"answer":"A","ref":"1C‐17A‐1, Section 7, Adverse Conditions, Turbulence, Thunderstorms and Heavy Rain/Hail, Inadvertent Thunderstorm/Turbulence or Heavy Rain Penetration.","topic":"Cold & Adverse Weather"},{"n":156,"q":"Takeoff will not be attempted with over ____ inch(es) of slush or water, over ____ inch(es) of wet snow, or over ____ inch(es) of dry snow on the runway.","options":{"A":"1/4, 2, 4","B":"1, 1/2, 3","C":"1/2, 1, 4","D":"1/3, 1, 4/3"},"answer":"C","ref":"1C‐17A‐1, Section 7, Cold Weather, Iceing and Cold Weather Operation, Takeoff.","topic":"Cold & Adverse Weather"},{"n":157,"q":"Failure to periodically perform the ground ice shedding procedure can result in damage to the engines. If more than ___ minutes have expired since engine start and icing conditions persist, delay takeoff until the procedure is accomplished","options":{"A":"5","B":"10","C":"30","D":"20"},"answer":"B","ref":"1C‐17A‐1 Section 7, Cold Weather, Iceing and Cold Weather Operation, Ground Fan Blade Ice Shedding Procedure.","topic":"Cold & Adverse Weather"},{"n":158,"q":"Under no circumstance will flights be planned through ____ icing conditions. Aircraft operation in ____ icing conditions may be tolerated for short periods of time but evasive action should be undertaken to exit icing conditions as soon as practicable.","options":{"A":"Moderate; moderate","B":"Forecast moderate; light","C":"Forecast or known severe; moderate","D":"Suspected clear; light"},"answer":"C","ref":"1C‐17A‐1, Section 7, Cold Weather, Iceing and Cold Weather Operation, Ground Fan Blade Ice Shedding Procedure, Takeoff.","topic":"Cold & Adverse Weather"},{"n":159,"q":"If icing conditions are expected during the descent, engine anti‐ice, wing anti‐ice, and windshield anti‐ice will be turned on at least _____ feet above the expected icing level in order to provide adequate warm up time.","options":{"A":"5,000","B":"10,000","C":"8,000","D":"2,000"},"answer":"B","ref":"1C‐17A‐1, Section 7, Cold Weather, Iceing and Cold Weather Operation, Ground Fan Blade Ice Shedding Procedure, Descent.","topic":"Cold & Adverse Weather"},{"n":160,"q":"The Pre‐Takeoff Contamination Check is required if holdover time has expired or if freezing precipitation is occurring on an aircraft that was not anti‐iced. The contamination check must be completed from OUTSIDE the aircraft within ___ minutes prior to takeoff","options":{"A":"15","B":"10","C":"5","D":"20"},"answer":"C","ref":"1C‐17A‐1, Section 7, Cold Weather, Iceing and Cold Weather Operation, Ground Fan Blade Ice Shedding Procedure, Takeoff. Ground Deicing/Anti-Icing, Definitions.","topic":"Cold & Adverse Weather"},{"n":161,"q":"Fluid Holdover Times: The C‐17 is considered a(n) __________ aircraft.","options":{"A":"aluminium","B":"composite","C":"piezoelectric","D":"ceramic"},"answer":"A","ref":"1C‐17A‐1, Section 7, Cold Weather, Iceing and Cold Weather Operation, Ground Fan Blade Ice Shedding Procedure, Takeoff. Ground Deicing/Anti-Icing, Fluid Holdover Times.","topic":"Cold & Adverse Weather"},{"n":162,"q":"During flight, avoid thunderstorm activity by any means available by at least ____ NM at or above FL 200 and ____ NM below FL 230","options":{"A":"10, 20","B":"20, 10","C":"15, 25","D":"25, 15"},"answer":"B","ref":"2 Gp Ops Manual Part A, Section 8 Operational Procedures, Thunderstorms.","topic":"Cold & Adverse Weather"},{"n":163,"q":"(APS‐150): What mode would be selected on the Radar Control Panel to see rainfall inside/behind areas of turbulence?","options":{"A":"GAIN MAX","B":"MAP1","C":"WX AUTO","D":"WX MAN"},"answer":"D","ref":"1C‐17A‐1, Para: 1‐2155 (C )","topic":"Avionics, MC & Nav"},{"n":164,"q":"APS‐150 Weather Radar: For an aircraft cruising at or above 29,000 feet, when will existing weather be depicted as nonrelevant (striped)?","options":{"A":"When actual weather is not within +/‐ 4,000 feet relative to aircraft’s actual/projected altitude","B":"When actual weather is below 25,000 feet","C":"When a MC altitude constraint is above actual weather","D":"A & B"},"answer":"D","ref":"1C‐17A‐1, Section 1, Weather Radar System AN/APS-150, Automatic Weather Mode.                          oll","topic":"Avionics, MC & Nav"},{"n":165,"q":"APS150: The Magenta areas represent areas of ____________ turbulence and should always be avoided.","options":{"A":"Light to Moderate","B":"Moderate to Severe","C":"Clear Air","D":"Extreme"},"answer":"B","ref":"1C‐17A‐1, Section 1, Weather Radar System AN/APS-150, Predictive Windshear Turbulence Detection","topic":"Cold & Adverse Weather"},{"n":166,"q":"What are the procedures if the spoilers fail to automatically retract during a touch and go?","options":{"A":"1C‐17A‐1 recommends rejecting","B":"The PF rotates with MCT selected and the PM will manually set the Spoilers switch to Off (dearm)","C":"The PF advances the throttles to MAX and the PM will manually set the Spoilers switch to Off (dearm)","D":"No special procedures are required."},"answer":"C","ref":"1C‐17A‐1, Section 2, Normal Operating Procedures, Touch and Go Landings.","topic":"Normal Procedures"}],"docs":[["Items to be presented",["1c-17a-1cl-1 (Pilot Checklist)","1c-17a-1cl-1-1 (Pilot Fanfold Checklist)","UK1c-17a-6cl-1 (CSTOs)","iPad reflecting latest updates","F5000","Logbook","Training Folder (electronic)","Co-pilot Development Folder (co-pilots only)"]],["1c-17a-1cl-1",["Check latest amendment","Check supplements","No other inserts, presented as a single document"]],["1c-17a-1cl-1-1",["Check latest amendment state"]],["iPad",["Latest update as per ops board"]],["F5000",["Most recent F166, Aircraft Cat and Role Cat forms","Date of next check correct – 1 year from the date of the last element of the check, or the date the check was due, whichever is later","All forms are originals","All BCR extensions and med chits are LHS entries"]],["Logbook",["Av Med dates (5 year expiry)","PME dates recorded correctly","Monthly summaries in correct format, signed by Flt Cdr; March summary signed by OC 99","Landings recorded","Sims recorded including IF apps and time, initialled by Flt Cdr","IF time validates IRT (3 hrs in 6 months)","White rating upgraded within 3 months","Annual summaries completed by OC 99"]],["Training folder (electronic)",["Front page signatures complete and matching the Auth matrix","Latest Role Cat, Aircraft Cat and F166","Sim reports present","NVG qualification form if applicable","Co-pilot report forms","Minor quals form for combat offload"]],["Co-pilot development folder",["Sections complete for time since LCR cat achieved and time to expected Captains' Board"]]]},"iret":{"parts":[{"num":"1","name":"Manual of Military Air Traffic Management","sections":[{"code":"1.1","title":"Manual of Military Air Traffic Management","items":[{"code":"1.1.1","q":"Define 3D Approaches","a":"A 3D instrument approach operation uses both lateral and vertical navigational guidance. The navigational guidance can be provided by either:\n\na.ground-based radio navigation aid such as an Instrument Landing System (ILS) or,\n\nb.Computer generated navigation data from ground-based, space-based or self-contained navigation aids, or a combination of these.\n\nA manually calculated rate/angle of descent is not considered vertical guidance, therefore it is not considered a 3D approach operation. 3D approach operations are conducted to a Decision Height (DH)/Decision Altitude (DA), which allows for height loss after the commencement of the missed approach. They can either be:\n\na.Type A – DH of 250ft (75,) or above, or\n\nb.Type B – DH less than 250ft (75m).\n\nAn aircraft is permitted to descend on the glidepath to the declared DH/DA; the options at this point are either to continue the approach visually or go around of the required visual references have not been obtained. If a go around is carried out, the Aircraft is only permitted to descend below DA/DH during the transition from descent to climb using the minimum height loss technique.","ref":"MMATM Ch 2 para 4-7 · ICAO Doc 8161 Vol 1 Ed 6 Part II-Sect 5-Chap2 (2.3)"},{"code":"1.1.2","q":"Define 2D Approaches","a":"A 2D instrument approach operation uses only lateral navigation guidance and is conducted to a Minimum Descent Height (MDH)/ Minimum Descent Altitude (MDA), below which the Aircraft will not descend without the required visual references. 2D approach operations can only be Type A with a MDH of 250ft (75)m or above. Descent to MDH/MDA can be permitted at any stage during the final approach, and it therefore remains a matter of personal preference or standard operating procedure when an immediate descent is carried out at the Final Approach Fix (FAF) or whether a notional glideslope is flown. However,\n\nother factors (such as limited radar cover, Aircraft sequencing requirements or local population considerations) may mean that only a notional glidepath technique is approved. Where such a limit applies, a note will be included in the remarks column of the relevant Terminal Approach Procedures (TAP) Chart. Of note, a No 1 Aeronautical Information Documents Unit (AIDU) chart specification will show a level off at the MDA/MDH until the Missed Approach Point (MAPt) is reached.\n\nThe final approach segment (FAS) begins at the FAF/Final Approach Point (FAP) and ends at the MAPt. The FAF.FAP will be crossed at or above the specified altitude before descent is initiated. When no FAF/FAP is shown, descent will not be initiated until the Aircraft is established within 5° of the final approach track.","ref":"MMATM Ch 2 para 8-10 · ICAO Doc 8161 Vol 1 Ed 6 Part II-Sect 5-Chap2 (2.4)"},{"code":"1.1.3","q":"Describe a CDFA Approach","a":"A CDFA is a technique for flying the FAS of a 2D instrument approach operation as a continuous descent, without level-off, from a height/altitude at or above the FAF height/altitude/height to a point approximately 50ft (15 m) above the landing Runway threshold or the point where the flare manoeuvre begins for the type of Aircraft flown. Where step-down fixes are depicted, associated height/altitude figures will be annotated; these will either be advisory of ‘not below’ figures. CDFAs with advisory vertical navigational (VNAV) guidance calculated by on-board equipment are considered 3D instrument approach operations. CDFAs with manual calculation of the required Rate of Descent (ROD) are considered 2D instrument approach operations. All AMF aircrew should fly 2D approaches using CDFA, unless it is impractical for a particular approach or runway. The CDFA technique requires a DH/DA to be used that ensures that the aircraft does not descend below the MDA/MDH for the approach. The DH/DA is to be the appropriate MDH/MDA + 50’ and may be known as a derived DA/DH. The missed approach shall be executed when reaching the DDA(H) or the MAPt whichever occurs first. If the pilot executes the missed approach prior to the MAPt they should not climb higher than the FAF altitude until past the MAPt to avoid conflict with other aircraft.","ref":"MMATM Ch 2 para 11-12 · 1 Gp Air Staff Orders RA 2314(3) para 21 · ICAO Doc 8161 Vol 1 Ed 6 Part II-Sect 5-Chap2 (2.5)"},{"code":"1.1.4","q":"State the value of any factors that need applying to DH/DA and MDH/MDA","a":"The flowing additional allowances may need to be added to the procedure minima before DH/MDH (DA/MDA) is declared and the pilot is responsible for informing the controller of the minima that they will use.\n\na.Any endorsements resulting from the Instrument Rating\n\nb.Engine Out Allowance (EOA) – Quoted in the ADS ( Not required for C11 Operations)\n\nc.Temperature Error Correction.","ref":"MMATM Ch 2 para 20"},{"code":"1.1.5","q":"State the C-17 Approach category (according to ICAO documentation)","a":"All aircraft are categorised according to their approach speed. Where a range of speeds is possible, an Aircraft may be capable of operating in more than one category. For simplicity the basis for categorisation is the normal approach speed at DH/MDH (DA/MDA) or Vat + 15 knots.\n\nRange of speeds for\n\nRange ofMaximumMaximum\n\ninitialMaximumTypical\n\nspeeds forspeeds for\n\nAircraft approach speeds Aircraft in\n\nVAT  final  intermediate  final\n\ncategory (and reversal for this\n\napproachmissedmissed\n\nandcirclingCategory\n\nspeedsapproachapproach\n\nracetrack procedures) small A <91 90 - 150 70 - 110 100 100 110 single engine\n\n91 -  small multi\n\nB 120 - 180 85 - 130 135 130 150\n\n120  engine\n\nC - 160 - 240 115 - 160 180 160 240 airline jet\n\n141  large\n\nD - 185 - 250 130 - 185 205 185 265 jet/military\n\n165  jet\n\nspecial E - 185 - 250 155 - 230 240 230 275 military\n\nVat = speed at threshold, based upon 1.3 x Vso (stall speed) or 1.25 x Vs1g in the landing configuration at max certified landing mass.\n\nAircraft Commanders have discretion to move the Aircraft into a higher or lower category when circumstances dictate a significantly higher of lower approach speed than normal. – Note 7 states, Aircraft Commanders may choose a LOWER category only when operationally essential and authorised.\n\nThe C-17 is normally Cat D.","ref":"co                                                                              MMATM Ch 2 para 26"},{"code":"1.1.6","q":"State the Instrument Approach Minima","a":"Notwithstanding any policy form ADHs, the lowest minima to which military Aircraft are authorised to make Instrument Approaches to land are:\n\nDH Category I+200 ft true550 m RVR\n\nMDH+250 ft true800 m RVR\n\nDA Category ITDZE +200 ft true550 m RVR\n\nMDATDZE +250ft true800m RVR\n\nCAT IIBelow 200’but300m RVR\n\nabove 100’\n\nCircling  700ft  3600m","ref":"MMATM Ch 2 para 27"},{"code":"1.1.7","q":"State how DA/DH and MDA/MDH are applied","a":"DH/DA. If during a precision approach, the required visual references have not been established when the DH/DA is reached, a missed approach will be initiated using the minimum height loss technique. MDH/MDA. A visual straight-in approach to land can be attempted only when the final approach track is within a maximum of 30° from the Runway\n\ncentreline to be used for landing. When the final approach track differs by more than 30° from the Runway centreline, the MDH/MDA will not be less than the circling minimum. Descent can only be continued below MDH/MDA if the required visual reference is available. Otherwise, the Aircraft will be levelled off at or above MDH/MDA and descent can only be resumed if the visual reference becomes available in time to permit a visual approach. The Aircraft may be circled for landing only if the conditions for a circling approach can be met. If the conditions for descent below MDH/MDA cannot be met, a missed approach will be initiated.","ref":"MMATM Ch 2 para 29"},{"code":"1.1.8","q":"Explain the potential hazard when going around from an approach with the DA/DH and MDA/MDH well above Procedure Minima","a":"If the DH/DA or MDH/MDA is well above the procedure minimum due to the allowances added, pilots will, in effect, be going around early. If a planned turn is required early in the missed approach, this could result in the Aircraft turning before reaching the safe climb-out segment. The same situation could occur during an intentional early go around before MAPt. In these circumstances it is the pilot’s responsibility to delay initiating the turn until the MAPt is reached.","ref":"co                                                                                MMATM Ch 2 para 29c"},{"code":"1.1.9","q":"State the required visual references for different types of approach","a":"No approach can be continued below the DH/DA or MDH/MDA unless at least one of the following visual references for the intended Runway is distinctly visible to, and identifiable, by the pilot:\n\n1)Category I Precision Approach or Non-Precision Approach\n\na.Elements of the approach lighting system\n\nb.The threshold, or its markings, lights or identification lights\n\nc.The visual glideslope indicator(s)\n\nd.The Touchdown Zone (TDZ), zone markings to zone lights\n\ne.The Runway edge lights.\n\n2)Circling Approach. As for non-precision approach, except that for circling approaches pilots will maintain visual references to the Runway\n\nenvironment at all times, i.e. with features such as Runway threshold, approach lighting aids or other features identifiable with the intended Runway.\n\n3)Category II Approach. A segment of at least 3 consecutive lights; either the centreline of the approach lights, TDZ lights, Runway\n\ncentreline lights, Runway edge lights, or a combination of these. The visual reference will include a lateral element of the ground pattern, i.e. an approach lighting crossbar of the landing threshold or a barrette of the TDX lighting.","ref":"MMATM Ch 2 para 29d"},{"code":"1.1.10","q":"State the required meteorological conditions before the commencement of an approach","a":"An Instrument Approach can be commenced regardless of the reported RVR/visibility.","ref":"MMATM Ch 2 para 30 · HQ 1 Gp Air Staff Orders RA 2314 (3)"},{"code":"1.1.11","q":"State the required meteorological conditions to continue an approach beyond the FAF or below 1000ft","a":"A training approach to go-around may be carried out regardless of the reported RVR/visibility.\n\nIf the reported RVR/visibility is less than the applicable minimum, an approach to land or touch and go will not be continued:\n\na.Below 1000ft above the Aerodrome, or\n\nb.Beyond the FAF if the DH/DA or MDH/MDA is more than 1000 ft above the Aerodrome\n\nWhere the RVR is not available, RVR values can be derived by converting the reported visibility. If, after passing 1000 ft above the Aerodrome, the reported RVR/visibility falls below the applicable minimum, the approach can be continued to the DH/DA or MDH/MDA. The approach can be continued below DH/DA or MDH/MDA and the landing completed, provided that the required visual references for the type of approach and intended runway are established at the DH/DA or MDH/MDA and are maintained. Where RVR is used, the controlling RVR is the touchdown RVR, unless otherwise stated. If reported and relevant, the mid-point and stop-end RVR can also be controlling. The minimum RVR value for the mid-point is 125 m or the RVR required for the TDZ if less, and 75 m for the stop-end. ‘Relevant’ in this context, means that part of the Runway used during the high-speed phase of the landing down to a speed of approximately 60 kts.","ref":"MMATM Ch 2 para 30.2 · HQ 1 Gp Air Staff Orders RA 2314 (3)"},{"code":"1.1.12","q":"State when Runway Visual Range Should be provided to pilots","a":"RVR should be provided to pilots whenever 1. The reported meteorological visibility falls to 1500m or less 2. The IRVR (Instrumented RVR) displays a value equal to or less than 1500m 3. Shallow fog is being reported or during a period for which it is forecast.\n\nIRVR values should be passed to pilots at the beginning of each approach and thereafter, whenever there is a significant change in the RVR until the Air System has landed. The IRVR should dalso be passed to the pilot prior to departure and when the IRVR goes below limits for an Air System to make an Approach.\n\nIRVR is reported in the following steps 1. 0 – 400m in 25m steps 2. 400 – 800m in 50m steps\n\n3. 800 – 1500m in 100m steps","ref":"MAA 2000 series RA 3275 (1)"}]}]},{"num":"2","name":"Aviation Duty Holder Orders","sections":[{"code":"2.1","title":"Group Air Staff Orders","items":[{"code":"2.1.1","q":"State the requirements of the IRT on the C-17","a":"Low visibility take-off procedures and a PBN approach (if appropriate for that aircraft type and not already completed as part of the 2D/3D\n\napproach\n\nInstrument Departure (SID, MID or ATC directed)\n\nAirways procedures (if deemed necessary for the issue of an unrestricted rating)\n\nHolding procedures\n\n3D approach (ideally ILS)\n\n2D approach (A PBN approach if appropriate for that type of aircraft and for award of PBN rating)\n\nEO procedures – IF approach and MAP in a simulated asymmetric condition\n\nA candidate failing one of the above should re-fly the failed item during the test. If the re-flown item is satisfactory, a rating may be awarded. Failure of more than one item will normally require a full re-test to be flown.\n\nGround Examination – Within 7 days -\n\nhttps://regulatorylibrary.caa.co.uk/1178-2011/Content/Regs/02720_FCL.615_IR_Theoretical_knowledge_and_flight_instruction.htm","ref":"GASO 2120(2) para 24"},{"code":"2.1.2","q":"State the criteria a candidate should meet prior to the award of on IR","a":"For an IR:\n\nCompletion of an appropriate trg cse prior to IRT.\n\n25 instrument approaches on type in either the AS or an IRT approved simulator.\n\nAll instrument flying time and simulator approaches flown as operating pilot may be counted towards the award or renewal of an IR.","ref":"GASO 2120(1) para 16"},{"code":"2.1.3","q":"State the process for the appointment and award of an IRE ( only for the examination of the IRE)","a":"Sqn Cdrs will appoint IREs. They are to have successfully completed the platform-specific IRE Cse as detailed in the relevant trg syllabus. IREs should be able to deliver IF instruction and IRTs from either seat of the aircraft’s flight deck. Candidates must have successfully passed\n\nPlatform-specific flying examination.\n\nPlatform specific ground examination.\n\nThe award is granted by the DDH who will require the following documentation:\n\nCopy of candidates latest F2020G or STANEVAL report, whichever is most recent.\n\nA copy of the candidate’s IRE Course Report.\n\nRAF F166 – Application for IR.\n\nASACS","ref":"GASO 2125(1) para 2g · GASO 2120(2) para 20"},{"code":"2.1.4","q":"State the No 1 Gp rules regarding operation of IFF","a":"Operation of IFF/SIFF. The rules regarding the use of IFF/SIFF are contained in UK AIP GEN 1.5. Notwithstanding these rules, IFF/SIFF offers a level of electronic conspicuity which is an important barrier to Mid Air Collision (MAC). Therefore, No 1 Gp aircraft are not permitted to take off without a serviceable IFF transponder unless it is:\n\nOperationally necessary (e.g. live QRA Scramble), or\n\nWith the permission of the relevant ADDH, to transit in airspace permitted by relevant national procedures (such as the UK AIP or\n\nequivalent), to recover the aircraft for repairs to the IFF system. If the transponder becomes unserviceable in flight, then the aircraft commander must take steps so obtain an appropriate Air Traffic Service to mitigate the risk of MAC. There after any decision whether to continue the sortie must consider the nature of the task, environment and the airspace in which the flight is taking place.\n\nThe IFF/SIFF may only be deliberately deselected in flight for:\n\n•  Operational reasons (to be approved by the DDH or Operational Commander) or,\n\nFor specific scenario-based training exercise (eg Ex SEIHAN RIVER). These training exercises must take place in segregated airspace\n\nunder the control of ASACS (Air Surveillance and Control System).","ref":"GASO 2307(1) para 4-5 · UK AIP GEN 1.5"},{"code":"2.1.5","q":"State the No 1 Gp rules regarding operation of Mode S","a":"All No 1 Gp aircraft equipped with a mode S transponder are to ensure that Mode S is selected during all stages of flight unless there is a specific operational need to do otherwise.","ref":"GASO 2307(1) para 6"},{"code":"2.1.6","q":"State the No 1 Gp rules regarding operation of TCAS","a":"In summary:\n\nIf fitted, TCAS should be on with RA mode selected.\n\nAll TCAS-generated RA warnings should be followed unless doing so would unequivocally jeopardise the safety of the aircraft.\n\nTA mode may only be used during selected phases of flight specified by DDH-approved and platform specific TCAS SOPs or the platform\n\nADS. RA must be reselected as soon as circumstances permit.\n\nFlight with on unserviceable TCAS requires DDH approval.","ref":"GASO2307(1) para 7"},{"code":"2.1.7","q":"State the requirements of a take-off alternate, use of Independent Landing Runways, Destination alternate, and En-Route alternates","a":"Take-Off Alternate: An airfield shall not be selected as a take-off alternate unless the appropriate weather reports or forecasts of any combination thereof indicate that, during a period commencing one hr before and ending one hr after the estimated time of arrival at the airfield, the weather conditions will be at or above the normal operating RVR and a ceiling at or above DA(H)/MDA(H). The take-off alternate shall be located within 2 hrs flight time, at one-\n\nengine inoperative cruising speed, in still air conditions based on actual take-off weight. Independent Landing Runway: An independent runway is one that is on the same airfield but separate landing surfaces that do not cross or overlay each landing surface should have a separate approach procedure based on a separate aid.\n\nAircraft may nominate an independent runway on the same airfield as the destination rwy as an alternative when the actual and forecast weather is WHITE of better. Destination Alternate:\n\nDiversion Likely – The designated alternate airfield selected should consider such factors as the availability of ground handling agreements and facilities, the ability to handle and disperse passengers/freight and the further tasking of the a/c. If practicable, the AS cdr should consult ASCOT Ops who will liaise with DSCOM, PJHQ/Sponsors and Sqn Ops to agree the preferred alternate airfield. For VIP tasking the outer office should be consulted through ASCOT Ops. or Diversion Unlikely – the designated alternate should be selected to minimise alternate fuel required. This will normally be the closest airfield to the destination. Use of En Route Alternate / Fuel ERA: An en-route alternate is an alternate which may be used in addition to a conventional destination alternate, allowing reduced contingency fuel to be planned. A check must be made at the Decision Point to establish that sufficient fuel is remaining to continue to destination. Should fuel be insufficient, a diversion to the en-route alternate should be initiated to uplift extra fuel. The en-route alternate is to be located in a circle centred on the planned route at a distance from the destination equal to 25% of the total flight plan distance, to 20% of the total flight plan distance plus 50nm, whichever is greater. The radius of the circle is to be 20% of the total flight plan distance. The airfield must be suitable do the aircraft type and promulgated as open.","ref":"GASO 2310(5) para 19,22,3"},{"code":"2.1.8","q":"State when an Equal Time Point must be calculated","a":"An Equal Time Point (ETP), also known as a Critical Point (CP), is to be calculated on all sectors when that aircraft is more than 90 minutes still- air time at the one-engine inoperative cruising speed from a suitable alternate. 1 Gp AMF Ops Man Part A 8.1.8.1.9","ref":"GASO 2310(5 Para 32)"},{"code":"2.1.9","q":"State when a Last Point of Diversion (LPD) / Point of No Return (PNR) must be calculated","a":"A Last Point of Diversion (LPD)/Point of No Return (PNR) is to be calculated for the following conditions:\n\na.If the destination is an Isolated Airfield.\n\nb.If there is any doubt over the ability of the aircraft to land at its destination or alternate airfield.\n\n1 Gp AMF Ops Man Part A 8.1.8.1.10","ref":"GASO 2310(5) para 33"},{"code":"2.1.10","q":"State the relevant procedures that 1 Gp aircraft must comply with prior to operation within RVSM airspace.","a":"RVSM is defined as “special qualification airspace”\n\nAllows reduced vertical separation from 2000’ to 1000’ between FL290 and Fl410.\n\nAircraft state clearance to fly in RVSM airspace\n\nAircraft must have specific equipment\n\no Two air data systems to measure altitude and vertical speed o Autopilot capable of holding the aircraft in level flight o Altitude alerting system\n\nBefore Flight into RVSM airspace\n\nEnsure that the AS serviceability state satisfies requirements for the route intended to be flown, noting any operating limitations that\n\nmight apply.\n\nReview the current flight levels to which RVSM rules apply, noting that there may be differences between regional and national airspace\n\nRVSM applications.\n\nEnter W at item 10 of the ICAO flt plan indicating that the AS has state approval to be flown in RVSM airspace.\n\nEnsure that the pitot and static ports and the surfaces on which these are mounted are free from damage.\n\nConfirm that the F700 contains no entries to show that RVSM requirements cannot be met.\n\nEnsure that 2 primary altitude measuring systems, one automatic altitude control system and one altitude alerting device are serviceable.\n\nWhen checking altimeters/ADCs on the ground, the AS cdr should confirm that the pilots altimeters are set to either QNH/QFE and the\n\ndisplayed altitude/height is within the tolerances specified for the AS (when determining the correct altitude/height, account should be taken of the difference between the actual AS location altitude/height, airfield altitude/height, touchdown altitude/height, and the effect of errors inherited in both the definition and derivation of QNH/QFE).\n\nPrior to Entering RVSM airspace\n\nEnsure that the aircraft has ATC clearance to enter RVSM airspace.\n\nConfirm that the aircraft serviceability still allows flight to be made in RVSM airspace.\n\nCarry out an altimeter check as follows. Shortly before entering RVSM airspace, or after levelling off, the operating pilot should initiate\n\nan “RVSM Altimeter Check”. The non-operating pilot will state the readings of the two main altimeters/ADCs and the standby altimeter. These readings should be recorded on the master log. The two primary altimeters must agree within +/- 200’ of each other.\n\nEnsure that the altitude alerting system in operative by confirming that it displays the correct flt level. If the alerter has functioned\n\ncorrectly since takeoff it is not necessary to artificially induce an audible alert.\n\nDuring Flight in RVSM airspace\n\nThe pilot flying (PF) should ensure that vertical closure speed is not excessive. It is advised that when approaching a cleared flt level to\n\nreduce vertical speed to below 1500’pm and ideally between 1000 – 500’pm with 1500’ to go. Additionally the pilot should ensure that the AS does not undershoot or overshoot the cleared level by more than 150’, manually overriding if necessary.\n\nEnsure that one automatic altitude control system should be operative and engaged throughout the cruise\n\n• At times not exceeding 60 in, PF should carry out cross checks between primary altimeters.\n\nDeviations\n\nAny deviations of greater than 300’ must be reported to ATC via the mandatory occurrence reporting scheme.\n\nATC Reporting\n\nAny event that may affect the ability to comply with the current clearance, such as severe turbulence, loss of thrust, loss of\n\npressurisation, the need to divert or an uncertainty of present position should be reported to ATC as soon as practicable. The following equipment failures must be reported to ATC. o Loss of thrust on one or more engines necessitating descent. o Loss of one or more altimetry systems. o Failure of automatic altitude control systems. o Failure of any other item of equipment that could affect the ability of the aircraft to maintain flt as cleared.","ref":""},{"code":"2.1.11","q":"State the elements that contribute to the required fuel state before departure","a":"The Pre-flight calcualtion of usable fuel required for flight ia to include -\n\nTaxi Fuel – 1500 lbs\n\nTrip Fuel – Take-Off, Climb, Cruise, Descent, Approach to Touchdown\n\nReserve Fuel – consisting of\n\no  Contingency Fuel. To be the higher of:\n\n▪  5% of the trip fuel from departure to destination\n\n▪ Quantity equal to 5 mins at holding speed at 1500ft above destination elevation in ISA conditions at planned landing weight. o Reduced Contingency Fuel. Contingency fuel of less than 5% is permitted if an en-route alternate is used. Contingency fuel is\n\nthen to be 5% of the trip fuel required from the Decision Point between the en-route alternate and the destination, but never less than 5 min hold fuel defined above. o Alternate Fuel.\n\no required from go-around at destination to touchdown at selected alternate using expected routing. Weight is assumed to be planned landing weight at destination minus route contingency fuel. If two alternates are required, fuel for the most distant must be carried. o Final reserve Fuel. Fuel required to hold for 30 minutes, at holding speed, 1500 ft above the alternate in ISA conditions and at the planned landing weight. ( 15000lbs for C17 – 7000lb holding, 4000lb App, 4000lb unreliable) o Equal Time Point Fuel Adjustment. Following an engine or pressurisation failure at the most critical point en-route, sufficient fuel is to be carried to descend as necessary and proceed to a suitable alternate airfield, hold for 30 minutes at 1500 ft above airfield elevation in ISA conditions and make an approach and landing.\n\no  Additional Fuel. As required by the type of operations\n\no Extra Fuel. If required by the Aircraft Commander. Isolated Airfield. If the destination is isolated and no adequate destination alternate exists, then the Alternate Fuel and Final reserve Fuel are replaced by a Holding reserve Fuel calculated as fuel for 2 hrs at normal cruise consumption after arriving overhead the destination airfield.","ref":"GASO 2313(1) para 1-2,4"},{"code":"2.1.12","q":"Describe how to convert Met Vis to RVR and when it is permitted to do so","a":"A MetVis to RVR conversion is not to be used Lighting Elements in Operation RVR/CMV = Reported MetVis Multiplied By: for take-off minima, calculating any other required RVR minimum less than 800 m, or Day Night when reported RVR is available. If the RVR is High Intensity Approach & Runway Lighting 1.5 2.0 reported as being above the maximum value assessed by the airfield operator i.e. ‘RVR Any type of Lighting other than above 1.0 1.5\n\nmore than 1500m’, it is considered a reported No Lighting Available 1.0 N/A value for these purposes. When converting form MetVis to RVR in all other circumstances than those detailed above, the following table can be used:","ref":"GASO 2314(1) para 1-2"},{"code":"2.1.13","q":"State the Minimum RVR for Take-Off","a":"The minima quoted are to keep the aircraft straight on the runway during the take-off run.\n\nThe aircraft commander shall not commence take-off unless the weather conditions at the airfield of departure are equal to or better than\n\napplicable minima for landing at that airfield unless a suitable take-off alternate airfield is available.\n\nWhen the reported MetVis is below that required for take-off and RVR is not reported, a take-off may only be commenced if the Aircraft\n\nCdr can determine that the RVR/Visibility along the take-off run is equal or better than the required minimum.\n\nWhen no reported MetVis or RVR is available, a take-off may only be commenced if the Aircraft Cdr can determine that the RVR/Visibility\n\n• along the take-off run is equal or better than the required minimum. If the runway lighting system, or part of it, is unserviceable, or the runway markings are obscured, the take-off minima are determined by what remains iaw the table.\n\nThe DDH may authorise take-offs for ”operational necessity” in RVR/visibility below those quoted.\n\nFacilitiesRVR/Visibility1\n\nNil (Day Only)500 m\n\nRunway Edge Lighting and/or Centreline Marking250/300 m 2,3\n\nRunway Edge and Centreline Lighting200/250 m 2\n\nRunway Edge and Centreline Lighting and Multiple RVR Information150/200 m 2,4\n\nNotes: 1. The reported RVR/visibility value representative of the initial part of the take-off run can be replaced by pilot assessment. 2. The higher value is for Cat D aircraft only. 3. For night operations, at least runway edge and runway end lights are required.\n\n4. The required RVR value must be achieved for all relevant RVR reporting points except for note 1. Provided the following requirements have been satisfied, the take-off minima may be reduced to 125m RVR for Category A, B and C aircraft or 150m RVR for Category D aircraft when>\n\na.Low Visibility Procedures are in force.\n\nb.High intensity runway centreline lights space 15m or less and high intensity edge lights spaced 60m of less are in operation.\n\nc.Flight crew members have satisfactorily completed training in a flight simulator.\n\nd.A 90m visual segment Is available from the cockpit at the start of the take-off run.\n\ne.The required RVR value has been achieved for all the relevant RVR reporting points.                                GASO 2314(2) para 10","ref":""},{"code":"2.1.14","q":"State the minimum RVR to commence and continue an approach","a":"See 1.1.10 & 1.1.11\n\n2.1.15 State the decision height to be used for an approach\n\nThe decision eight to be used for an approach is the higher of:\n\na.The minimum height to which the approach aid can be used without the required visual references.\n\nb.The OCH for the category of aircraft.\n\nc.The published approach procedures decision height where applicable.\n\nd.200 ft for Cat 1 ops.\n\ne.Any system minima.\n\nf.The lowest decision height if specified in the ADS.                                                                   GASO 2314(3) para 5","ref":""},{"code":"2.1.16","q":"State the required visual references to continue an approach below Minima","a":"See 1.1.9","ref":""},{"code":"2.1.17","q":"State the minimum RVR in which a final approach to land may be flown","a":"The minimum RVR in which a final approach to land may be flown is the higher of:\n\na.For Cat I ILS, LPV and PAR approaches1, the published RVR or 550 m.\n\nb.For all other approaches the published RVR or 800 m.\n\nNote: 1. Requires CDFA technique. If the approach is flown with a planned level flight segment at or above MDH/MDA, 200 m shall be added for Cat A and B aircraft and 400 m for Cat C and D aircraft to the minimum RVR. The added value corresponds to the time/distance required\n\nto establish the aircraft on the final descent.","ref":"GASO2314(3) para 8"},{"code":"2.1.18","q":"State the minimum for each approach system","a":"FacilityLowest DA/DHFacilityLowest DA/DH\n\nor MDA/MDHor MDA/MDH\n\nILS (Cat 1)/PAR200 ftVOR/DME250 ft\n\nRNP(APCH) - LPV200 ftVOR300 ft\n\nRNP(APCH) – LNAV/VNAV250 ftNDB/DME300 ft\n\nRNP(APH) – LNAV250 ftSRA (terminating at 1 nm)300 ft\n\nLOC with or without DME250 ftNDB350 ft\n\nSRA (terminating at ½ nm)250 ftSRA (terminating at 2nm or more)350 ft\n\nTACAN250 ftVDF350 ft\n\nCategory II Minima\n\nDH  Auto-Coupled to below DH\n\nRVR/Aircraft Category A, B & C  RVR/Aircraft Category D\n\n100 – 120’\n\nco  300m  300/350m\n\n121-140’400m400m\n\n141’ & above450m450m\n\n300m may be used for a Category D Aircraft conducting an auto-land","ref":"GASO2314(3) para 9 and 17"},{"code":"2.1.19","q":"Define 2D and 3D approaches","a":"See 1.1.1 and 1.1.2","ref":""},{"code":"2.1.20","q":"State when Stabilised Approaches should be used","a":"All fixed wing approaches shall be flown as stabilised approaches, unless operational circumstances dictate that an approved tactical profile be used. A stabilised approach is defined as an approach which is flown in a controlled and appropriate manner in terms of configuration, energy and control of flight path from a pre-determined point or height/altitude down to a point 50’ above the threshold or the point where the flare manoeuvre is initiated if higher.","ref":"GASO 2314(3) para 12"},{"code":"2.1.21","q":"State the MDH and MDA for Circling approaches","a":"Minimum Descent Height: The MDH for circling shall be the higher of:\n\na.The published circling OCH for the aircraft category.\n\nb.The minimum published circling height.\n\nc.The DH/MDH of the preceding instrument approach procedure.\n\nMinimum Descent Altitude: The MDA for circling shall be calculated by adding the TDZE for the MDH. There is no need to add an additional 50 feet to the MDA which precedes a circling approach.\n\n2.1.22 State the minimum visibility for a circling approach\n\nThe minimum visibility for a circling approach shall be the higher of:\n\na.The circling visibility for the aircraft category, if published.\n\nb.The minimum published visibility.\n\nc.The VR/CMV published for the preceding instrument approach procedure.\n\nd.For the C-17A, the minimum visibility for a circling approach shall be the higher of the above or 3600 m.","ref":"GASO 2314(6) para 22-23 · GASO 2314(6) para 24"},{"code":"2.1.23","q":"State whose IRT rating determines the minima that the crew can operate to (PF/PM)","a":"The most limiting of either the PF or PM, unless the most limiting is under the supervision of a QFI or an IRI/IRE. GASO 2120 (1) para 8","ref":""}]},{"code":"2.2","title":"OM Part A","items":[{"code":"2.2.1","q":"State when Instrument Flying Time should be logged as ‘Sim’","a":"All instrument Flying time should be recorded as ‘Act’. OM A 1.0.4.9. para g","ref":""},{"code":"2.2.2","q":"State the requirements to maintain a current instrument rating","a":"During the preceding 6 months the pilot must fly:\n\nA minimum of 3 hrs IF General Handling (simulated or actual)\n\n3 precision and 3 non-precision instrument approaches of which at least 2 approaches should have been flown procedurally.\n\nIf this is completed an instrument rating remains valid for 13 months","ref":"OM A 5.1.3.2.3.1"},{"code":"2.2.3","q":"State what happened if a pilot does not achieve the requirements to maintain a valid IR","a":"If the currency requirements are not achieved, then a rated pilot drops to un-rated status (at which point they are also downgraded to NCR).","ref":"OM A 5.1.3.2.3"},{"code":"2.2.4","q":"Determine Aerodrome Planning Minima using ‘Application of Airfield Forecasts (TAF and Trend) to Pre-flight Planning’ table at OM A 8.1.8.1.11.1","a":"Candidates should be able to determine the aerodrome planning minima to the satisfaction of the examiner.","ref":""},{"code":"2.2.5","q":"State the requirement for another crew member to check manually entered waypoints","a":"Manual Waypoints. All waypoint positions entered manually as latitudes and longitudes into navigation equipment, that will be used to automatically direct the ac, should be independently checked by another crew member. Wherever possible, the tracks/distance display should be used as a check against the computer flt plan values.","ref":"OM A 8.3.1.1"},{"code":"2.2.6","q":"Describe what is meant by a ‘stabilised approach’","a":"An approach which is flown in a controlled and appropriate manner in terms of configuration, energy and control of flight path from a pre-determined point or height/altitude down to a point 50’ above the threshold or a point where the flare manoeuvre is initiated if higher.\n\nAircraft tracking on the required approach path and profile.\n\nIn the required landing configuration and attitude.\n\nFlying with the require rate of descent (<1000 fpm unless briefed) and speed (V APP +10/-5). The ROD should deviate by no more than\n\n±300fpm from the target.\n\nFlying with the appropriate thrust/power and trim.\n\nAll briefings and checklists complete.\n\nBank angle less the 30 degrees.\n\nAdditional C17 requirements. – by 300’\n\n+10 to -5 knots of computed approach speed\n\nFPV touching the API line\n\nFPV and API must be within the confines of the intended touchdown or landing zone\n\nA stabilized approach is an approach which is flown in a controlled and appropriate manner in terms of configuration, energy and control of the flt path from a predetermined point or altitude/ height down to a point 50’ above the threshold. It is recommended that stabilization during any straight in approach without visual reference to the ground should be achieved at the latest when passing 1000’ above runway threshold elevation. 500’ stabilised in speed if higher than normal approach speeds are required by ATC and 300’ if the pilot has visual reference to the ground.","ref":"OM A 8.4.3"},{"code":"2.2.7","q":"State when it is permissible to carry out Land And Hold Short Ops (LAHSO)","a":"ATC clearance to carry out LAHSO should not be accepted by AMF ac. Passive LAHSO is when the whole runway is available to the aircraft, with LAHSO being carried out on an intersecting runway. Active LAHSO is when only a portion of the runway is available for landing. It requires specific crew training and authorisation from the national aviation authority. No carrier outside the US have met these FAA requirements.","ref":"OM A 8.4.4"},{"code":"2.2.8","q":"Describe what is meant by a Precision Runway Monitor (PRM) Approach","a":"ILS PRM Approach ILS PRM procedures may be authorised at airports with parallel runways spaced between 3000ft and 4300ft apart. A ‘No Transgression Zone’ (NTZ) is established between the parallel approach paths to provide a safety buffer between AS on adjacent ILS approaches. The approach paths are monitored by a high-resolution radar, which provides a fast update rate of display to the ATC final monitor controller. If an AS is observed penetrating the NTZ, a breakout procedure will be initiated by the controller, whereby the AS on the adjacent approach will be turned away.","ref":"OM A 8.4.5.1"},{"code":"2.2.9","q":"Describe what is meant by the ‘breakout manoeuvre’ in relation to a PRM Approach","a":"Breakout Manoeuvre This is an unpublished procedure that will be initiated by ATC. The predictive nature of the high-resolution radar used to initiate the breakout means that crews will have little or no warning prior to the breakout instruction being given by ATC. The pilot must initiate a breakout manoeuvre manually and immediately when directed by ATC. Separation requires that the pilot establish a standard rate turn of 3° per sec (25° angle of bank at approach speeds) within 8 secs. The change of heading will be no more than 45°. A breakout may, exceptionally require a descent. The descent will not be\n\nlower than the minimum vector altitude (MVA) for that sector. The rate of descent expected is no more than1000 ft per min.","ref":"OM A 8.4.5.2"}]},{"code":"2.3","title":"OM Part B (Basic)","items":[{"code":"2.3.1","q":"State at what height should the aircraft be stabilised on an instrument approach","a":"300’ announcing Stabilised Other considerations are 1000’ and 500’","ref":"OM B (Basic) 2.3.2"},{"code":"2.3.2","q":"Describe the Noise abatement departure profile and when you can and can’t use it.","a":"There are 2 designated Noise abatement procedures outlined by PANS-OPS, the C-17 does not theoretically fly these although the\n\no  NADP1 –\n\nalternate and noise abatement procedures are similar.\n\n▪Runway to 1500’ AGL – T/O Power, T/O Flaps, V2 + 10 – 20 kts\n\n▪At 1500’ AGL – reduce to climb thrust, climb at V2 + 10 – 20 kts\n\n▪At 3000’ AGL – Accelerate to Flap up / Slat retraction speed, clean on schedule, climb at en route power and speed\n\noNADP2 – (noise abatement)\n\n▪Runway to 1000’ AGL – T/O Power, T/O Flaps, Climb at V2 + 10 – 20 kts\n\n▪At 1000’ AGL – accelerate to flaps up speed, retract flaps\n\n▪When flaps are up – maintain Flaps up Speed + 10 kts maximum, Reduce to climb thrus\n\n▪At 3000’ AGL – Accelerate to enroute climb speed\n\nC17 noise abatement and alternate Profiles are outlined in both the -1 and the OM Part B\n\nCan only be used if TOLD states STD dep and COF agrees with P 4/5 in 1-1                                           OM B (Basic) 2.7.6","ref":""},{"code":"2.3.3","q":"State the maximum recommended Rate of Climb or descent during the last 1000 ft of a climb or descent","a":"It is generally regarded that rates of climb or descent are reduced below 1500’ (ideally between 500’ – 1000’) within the last 1500’ of climb or descent\n\nRates of climb specified by ATC are to be adhered to until reaching desired altitude.","ref":""},{"code":"2.3.4","q":"State the maximum speed on a circling approach for TERPS and PANS-OPS/MIPS approaches for a Cat D aircraft","a":"TERPS          165 kts\n\nPANS-OPS/TERPS 205 kts                                                                                           OM B (Basic) 2.12.2","ref":""},{"code":"2.3.5","q":"State when altimeters should be cross checked in the climb and descent","a":"Climb\n\nOn passing transition\n\n10 000 ft (FL100) / 20 000ft (FL200) / 30 000’ (FL 300)\n\n‘1000 to go’\n\nAcknowledge approaching a cleared level, altitude or height by announcing ‘ALT’\n\nDescent\n\nOn passing transition\n\n10 000 ft (FL100) / 20 000ft (FL200) / 30 000’ (FL 300)\n\nAcknowledge ‘1000 ft to go’ indications\n\nAt 1000’AGL on any approach alongside a config check\n\nAcknowledge descent below SALT","ref":"OM B (Basic) 2.17"}]},{"code":"2.4","title":"OM Part C Aerodrome Briefing Manual","items":[{"code":"2.4.1","q":"Demonstrate how to access specific airfield operational information","a":"Candidates should be able to show that they can access and interpret any information on specific airfields as request by the IRE. OM Part C","ref":""}]},{"code":"2.5","title":"DHOIs","items":[{"code":"2.5.1","q":"State any DHOIs that affect IF operations","a":"Candidates should be able to reference and explain any extant DHOIs that have an impact on IF operations. As of 13/01/25 there were non Air Safety Cell DHOI/DHAN Tracker","ref":""}]}]},{"num":"3","name":"Information","sections":[{"code":"3.1","title":"Flight Information Handbook","items":[{"code":"3.1.1","q":"State the weight turbulence class of the C-17 Globemaster","a":"Heavy. . According to CAP 413 Chapter 2 papa 2.30 – For aircraft in the SUPER or HEAVY wake turbulence category, the word “super” or “heavy” shall be\n\nincluded, as appropriate, immediately after the aircraft call sign in the initial radiotelephony contact between such aircraft and ATS units.","ref":"FIH Section 2.15 Table 2.15.I"},{"code":"3.1.2","q":"State the minimum separation distance for approach behind SUPER, HEAVY, MEDIUM, SMALL and LIGHT aircraft","a":"Leading AircraftDistance\n\nSUPER5\n\nHEAVY4\n\ncoMEDIUM\n\nSMALL NA NA\n\nLIGHT  NA","ref":"FIH Section 2.15 Table 2.15.III"},{"code":"3.1.3","q":"State the minimum time separation between SUPER, HEAVY, MEDIUM, SMALL and LIGHT aircraft","a":"Leading AircraftConditionTime\n\nSUPERDeparting from the same point position or2 minutes\n\nHEAVYfrom a parallel runway separated by less than4nm or time equivalent\n\n760m\n\nMEDIUM or SMALL  NA\n\nSUPERDeparting form an Intermediate Point on the3 minutes\n\nHEAVYsame runway or from an intermediate point of4nm or time equivalent\n\na parallel runway separated by less than\n\nMEDIUM or SMALL  760m.  NA","ref":"FIH Section 2.14 Table 2.14.IV"},{"code":"3.1.4","q":"Explain the different methods of hold entry","a":"Sector 1 (Parallel Entry)\n\no At the fix the aircraft is turned onto an outbound heading for one minute (below 14000’) o Aircraft turned to the holding side to intercept the inbound track or direct to the fix o Aircraft enters hold over the fix\n\nSector 2 (Offset Entry)\n\no At the fix aircraft turned to make good a track 30 degrees from the reciprocal of the inbound track on the holding side o Flown for 1 minute or until a specified or limiting DME / limiting radial o Aircraft turned to intercept the inbound holding track\n\nSector 3 (Direct Entry)\n\no AT the fix aircraft is turned into the holding pattern\n\nThere is a 5 degree flexibility between hold entry boundaries","ref":""},{"code":"3.1.5","q":"State the Holding Speeds for Cat A through E Aircraft","a":"Levels  Normal Conditions  Turbulence Conditions\n\nUp to 14,000ft230kts280kt\n\n14,000ft - 20,000ft240kts230kt\n\n20,001ft - 34,000ft265kts","ref":"FIH Section 3.3 Table 3.3.II"},{"code":"3.1.6","q":"State the bank angle and rate of turn limits in the hold","a":"25° AoB or 3° per second rate ( rate1) of turn whichever requires the lesser AoB. FIH Section 3.3 para","ref":""},{"code":"3.1.7","q":"Decode NOTAM and SNOWTAMs to the satisfaction of the examiner","a":"Candidates should be able to decode a NOTAM to the satisfaction of the examining officer. FIH Section 10.1","ref":""},{"code":"3.1.8","q":"State the maximum circling speed for Cat D aircraft","a":"180kts (4.20nm PANS-OPS circling Radii). FIH Section 10.3 Table 10.3.I","ref":""}]},{"code":"3.2","title":"1C-17A-1","items":[{"code":"3.2.1","q":"Explain HUD Indications","a":"Candidates should be able to explain all HUD symbology to the satisfaction of the examiner. 1C-17A-1 (pg 1-509, 1-570)","ref":""},{"code":"3.2.2","q":"Explain PFD Indications","a":"Candidates should be able to explain all PFD symbology to the satisfaction of the examiner. 1C-17A-1 (pg 1=570)","ref":""},{"code":"3.2.3","q":"Explain GPWS modes and Alerts","a":"Candidates should be able to explain the GPWS modes and Alerts\n\nMode 1 – Excessive IRU VV with respect to terrain (SINK RATE)\n\nMode 2A – Excessive closure rate to the terrain with non-landing flap (TERRAIN FLY UP)\n\nMode 2B – Excessive closure rate to the terrain with landing flaps (TERRAIN FLY UP)\n\nMode 3B – Cumulative altitude loss after take off or missed approach (SINKING)\n\nMode 4A – Flight into terrain with the gear retracted (TOO LOW, GEAR)\n\nMode 4B – Flight with gear up and flaps in landing mode below 250’ (TOO LOW, GEAR)\n\nMode 4C – Flaps up with gear down below 500’ (TOO LOW, FLAPS)\n\nMode 5A – Glide slope deviation alerting (GLIDESLOPE)\n\nMode 5B – Low glide slope deviation alerting (TOO LOW, POWER)\n\n1C-17A-1 (pg 1-725)","ref":""}]},{"code":"3.3","title":"TCAS","items":[{"code":"3.3.1","q":"Explain TCAS Symbology","a":"Other traffic\n\no Open White Diamond\n\no Aircraft no within +/- 1200’ vertically or 6nm\n\nProximate Traffic\n\no Solid White Diamond o Aircraft within +/- 1200’ vertically and within 6nm\n\nTraffic Advisory\n\no Solid Yellow Circle o Target aircraft are within 6nm and could be potentially hazardous. Depending on altitude the time to closest point of impact is 20 – 48 seconds\n\nResolution advisory\n\no Solid Red Square o Target aircraft are within 6nm and projected to be a collision threat. Depending on altitude the time to closest point of impact is 15 – 35 seconds.\n\nAltitudes for proximate and other traffic are only displayed if they fall within the zone specified on the TCAS modes Page. Above = -2700’ to + 8700’ Norm = +/- 2700’ Below = +2700’ to -8700’ A vertical speed trend arrow is only displayed when its VS is at least +/- 500’pm There is a cone of confusion =/- 10 degrees directly above or below the aircraft. TARA inhibits RAs below 900’ descending – 1100’ ascending Aural Alerts are inhibited 400’ descending and 600’ ascending 1C-17A-1 (Pg 1-749 – 1-757)","ref":""},{"code":"3.3.2","q":"State the actions required in the event of a TA and RA","a":"TRAFFIC TRAFFIC\n\nSelect PPI for TCAS display on an MFD (note traffic will disappear from nav display)\n\nRESOLUTION ADVISORY\n\nDisconnect AP and ATS (pressing AP disconnect will engage TCAS sub mode).\n\nFollow flight director pitch commands and thrust worms.\n\nPM – Radio call “Callsign TCAS RA Standby”.\n\nPM cancel “altitude” warning if triggered.\n\nPM to select TCAS PPI display.\n\nOnce clear of conflict advise ATC that you are returning to assigned altitude or re commencing climb / descent to cleared altitude.\n\nSubmit DASOR upon landing.\n\nOps Man Part B 2.24.1","ref":""}]},{"code":"3.4","title":"MAA Flying 2000 Series Regulatory Articles","items":[{"code":"3.4.1","q":"Explain the reason behind completion the IRT","a":"Pilots are sometimes required to fly Aircraft with insufficient visual references, or in non segregated airspace where VFR may be inappropriate or disallowed. Failure to safely fly their aircraft with insufficient visual references, or failure to comply with IFR for coordination with other aircraft and controllers in non-segregated airspace, increases the RtL posed to Aircraft occupants and third parties on the ground. All pilots who fly UK military aircraft – shall hold a valid IR for their aircraft type. Crewed Aircraft – Pilots of Crewed Aircraft should hold an IR if operating an aircraft 1. In IMC 2. With insufficient visual references 3. Under IFR","ref":"RA 2120 – Pilot’s Instrument Rating Scheme"},{"code":"3.4.2","q":"State the tolerance limits for the award of an Instrument Rating","a":"Instrument Rating Limits:\n\nHEIGHT\n\nGenerally +/- 100’\n\nStarting a go-around at DH/DA +50 / -0 feet\n\nMDH / Missed App point / Altitude +50 / -0 feet\n\nTRACKING\n\nOn radio aids +/-5 degrees\n\nFor Angular deviations Half scale deflection, azimuth and glidepath (LPV, ILS, MLS)\n\n2D LNAV and 3D LNAV / VNAV Cross track error / deviation will normally be limited to +/- half the RNP value associated with the procedure. Brief deviations from this value up to a maximum of the RNP value are allowable 3D Linear vertical deviations (RNP APRCH LNAV/VNAV) Not more than 75’ below the vertical profile and not more than 75’ above the vertical profile at or below 1000’above the Aerodrome level\n\nHEADING All Engines operating +/- 5 Degrees\n\nWith simulated engine failure +/- 10 degrees\n\nSPEED\n\nAll engines operating +/- 5 kts\n\nWith simulated engine failure + 10 kts / -5 kts","ref":"RA 2120 (2)"},{"code":"3.4.4","q":"State and explain the different classifications of airspace in the UK.","a":"Class A Airspace.\n\nIs the most strictly regulated airspace where pilots must comply with ATC instructions at all times. Aircraft are separated from all other\n\ntraffic.\n\n•All control areas and TMAs below FL 195 as notified within the UK FIR\n\n•Channel Islands Terminal Control Area (North and South)\n\n•  Shanwick Oceanic Control Area\n\nClass C Airspace\n\nExtends from FL195 to FL660, Both IFr and VFR flight is permitted but pilots require clearance to enter and must comply with ATC instructions.\n\nAbove FL195 all airspace in the London and Scottish FIR\n\nBelow FL195 see AIP ENR 1.4 para 2.3.1.2 for CTs that are class C.\n\nClass D Airspace\n\nIFR and VFR flight can occur in Class D Airspace\n\nAn ATC Clearance is needed and compliance with ATC instructions is mandatory.\n\nControl areas around aerodromes are generally class D\n\nSee AIP ENR 1.4 para 2.4.2.1 for UK class D airspace\n\nClass E Airspace\n\nIFR and VRF flight is available in Class E Airspace\n\nCompliance with ATC instructions is mandatory\n\nVFR traffic doesn’t not require clearance to enter class E Airspace but pilots must display Mode A 7000 or frequency monitoring code\n\nSee AIP ENR 1.4 Para 2.5.1.1 for UK airspace is Class E below FL195\n\nClass G airspace\n\nAll UK airspace, including above FL660, not included in Class A – F.\n\nPart 3 – Information","ref":""},{"code":"3.4.5","q":"Explain flight rules in terms of VMC, VFR, IMC and IFR","a":"VMC – visual meteorological conditions\n\n•  The weather conditions that permits flight IAW VFR\n\nAltitude Band Airspace Class Flight Visibility Distance from cloud\n\nAt and above 10000’AMSL A(1), B, C, D, E, F,G 8km 1500m Horizontally 1000’ vertically\n\nBelow 10000’ AMSL and above A(1), B, C, D, E, F,G 5km (3) 1500m Horizontally\n\n3000’AMSL, or above 1000’ 1000’ vertically above terrain which ever is the higher\n\nAt and below 3000’AMSL, or A(1), B, C, D (6), E 5km (3) 1500m Horizontally\n\n1000’ above terrain, whichever is 1000’ vertically the higher\n\nAt and below 3000’AMSL, or F,G 5km (4) 1500m Horizontally 1000’ above terrain, whichever is 1000’ vertically the higher Or Clear of Cloud with the surface in sight (5)\n\n(1)– The VMC minima in class A airspace are included for guidance to pilots and do not imply acceptance of VFR flights in Class A airspace\n\n(2)\n\n(3)– The minimum flight visibility above 250kts should be 8km\n\n(4)– Minimum flight visibility outside controlled airspace ( NOT REQUIRED FOR C-17 OPERATIONS)\n\n(5)– Distance from cloud\n\na.AT speeds greater than 250kts the minimum horizontal distance from cloud should be 1500m\n\nb.NOT APPLICABLE FOR UK C-17 OPERATIONS\n\n(6)– Class D Airspace, A VFR flight into class D airspace is also deemed to have complied with Table 1 if the aircraft is flown\n\na.During the day\n\nb.AT an indicated airspeed of 140kts or less to give adequate opportunity to observe other traffic or any obstacles in time to avoid collision;\n\nand\n\nc.Remaining clear of clous, with the surface in sight and a flight visibility of at least 5 km (aircraft other than helicopters.\n\nVFR – Visual Flight Rules\n\n•Flying using primary visual flight reference\n\n•General principle off see and avoid\n\n•Must be flown under VMC\n\nIMC – Instrument Meteorological conditions\n\nAnything that is not VMC\n\nIFR – Instrument Flight Rules\n\nOutside of CAS above TA pilots should select cruising levels according to the UK AIP based on 1013.2hPa\n\nShall be flown at a level which is at least 1000’ above the highest obstacle located within 8 km of the aircraft.\n\nShould be in receipt of a surveillance radar service\n\nShould not normally fly below 3000’ in IMC unless\n\no In Airspace detailed in the AIP or NOTAM for flight not iaw IFR o In a Danger Area which is notified as active and allocated to the flying unit o In accordance with operation order for specific exercises where allocated operating levels preclude flight at the appropriate IFR level o Flying in conformity with instructions by ATC, an HM Ship or and air defence unit.\n\nIFR is mandatory\n\no In IMC o In Class A airspace, except where SVFR is permitted o In Class C airspace when VFR operations are not permitted SVFR – Special Visual Flight Rules – May be authorised within a control zone, subject to ATC clearance\n\nFlight is conducted clear of cloud, with the surface in sight\n\nFlight visibility is not less than 1500m\n\nSpeed is 140kts or less to give adequate opportunity to observe other traffic and any obstacles in time to a avoid a collision\n\nFlight is conducted day only, unless otherwise permitted by ATC\n\nCloud ceiling is not less than 600’AGL","ref":"RA2307 (1) Para 48 – 65"},{"code":"3.4.6","q":"Explain the types of Air Traffic Service outside of controlled airspace (ATSOCAS)","a":"Basic Service\n\n•  Provided for the purpose of giving advice and information useful for the safe and efficient conduct of flights\n\nMay include weather information, changes of serviceability of facilities, conditions at aerodromes, general airspace activity information.\n\nThe avoidance of other traffic is solely at the pilot’s responsibility. – ATS may provide traffic information regarding aerial activity in a\n\ncertain location that may. – This is even if a warning is issues as per point below.\n\nIf a controller considers that a definite risk of collision exists, a warning shall be issued to the pilot.\n\nAvailable under IFR outside of controlled airspace in and meteorological conditions or under VFR.\n\n•  PILOTS SHOULD BE AWARE THAT BASIC SERVICE MIGHT NOT BE APPROPRIATE FOR FLIGHT IN IMC OR WHERE\n\nLOOKOUT IS CONSTRAINED BY OTHER FACTORS.\n\n•  Pilot remains responsible for terrain clearance\n\nA pilot may change heading or level without advising the controller unless they have entered into an agreement with said controller.\n\n•  Generic navigational assistance may be provided by a controller if requested\n\nTraffic Service\n\nA surveillance based ATS where in addition to a basic service the controller provides specific surveillance-derived traffic information.\n\nCan only be provided by a controller with access to an ATS surveillance system.\n\nAvailable under IFR outside of controlled airspace in any meteorological conditions, or under VFR.\n\n•  PILOTS SHOULD BE AWARE THAT TRAFFIC SERVICE MIGHT NOT BE APPROPRIATE FOR FLIGHT IN IMC OR WHERE\n\nLOOKOUT IS CONSTRAINED BY OTHER FACTORS, WHEN OTHER ATSs ARE AVAILABLE.\n\nIf a controller issues a heading or a level that would require flight in IMC, a pilot who is not suitably qualified to fly in IMC shall inform\n\nthe controller and request alternative instructions.\n\nA controller shall identify the aircraft and inform the pilot that they are identified and maintain identity.\n\nThe controller shall pass traffic information on relevant traffic, and shall update the traffic information if it continues to constitute a definite\n\nhazard or if requested by the pilot.\n\nTraffic is normally considered relevant when it may pass within 3nm and 3000’ of the aircraft receiving a traffic service.\n\nControllers should aim to pass relevant information to the pilot when the aircraft is within 5nm to allow the pilot sufficient time to react.\n\nDeconfliction is not provided.\n\nSubject to ATS surveillance system coverage, Traffic service may be provided below ATC unit terrain safe levels, however, pilots remain\n\nresponsible for terrain clearance at all times.\n\nOther than when following a notified instrument flight procedure, a pilot intending to descend below the ATC unit terrain safe level shall\n\nbe reminded that they remain responsible for terrain clearance.\n\nA pilot may operate under their own navigation or a controller may provide headings.\n\nWhen operating under their own navigation, pilots may alter course as required, however, unless safety is likely to be compromised,\n\npilots shall not change their general route or manoeuvring area without first advising and obtaining a response from the controller.\n\nWhen following an ATC heading pilots shall not alter this heading without advising and obtaining a response from the controller, unless\n\nsafety of the aircraft is at risk.\n\nControllers will only instigate heading allocations if the aircraft is above ATS unit Terrain safe levels.\n\nPilots may select their own operating levels or may be provided with level allocations by the controller.\n\nPilots remain responsible for collision avoidance even when operating at a level allocated by an ATS unit\n\nLevels allocated by an ATS unit shall be above the ATS unit terrain safe level unless an agreement is reached with the pilot, or such\n\nlevels form part of a VFR clearance for aerodrome arrival or to enter controlled airspace that by necessity require flight below the unit terrain safe levels. The pilot shall be reminded that they are responsible for terrain clearance.\n\nDeconfliction Service\n\nA surveillance based ATS where in addition to the provisions of a Basic Service, the controller provides specific surveillance-derived\n\ntraffic information and issues headings / levels aimed at achieving planned deconfliction minima.\n\nAvoidance of traffic is ultimately the pilots responsibility.\n\nOnly provided by a controller with access to an ATS surveillance system.\n\nShall only be provided to flights operating under IFR outside controlled airspace, irrespective of meteorological conditions.\n\nController expects pilots to accept headings and level instructions.\n\nA pilot not qualified to operate in IMC shall not request a deconfliction service.\n\nA controller shall identify the aircraft and inform the pilot that they are identified and maintain identity.\n\nA controller may pass traffic information on deconflicted traffic to improve the pilot’s SA.\n\nA controller shall provide traffic information, accompanied with a heading / level aimed at achieving a planned deconfliction minima\n\nagainst all observed aircraft in – o Class G airspace o Active Temporary Reserved Areas (TRA) o Active Military Training Areas (MTA)\n\nDeconfliction minima against uncoordinated traffic is\n\no 5NM laterally o 3000’ vertically and unless the SSR code indicates that the mode C data has been verified, the surveillance returns, however presented, should not merge.\n\nDeconfliction minima against aircraft that are being provided with an ATS by the same controller, or subject to coordination\n\no 3nm laterally o 1000’ vertically (2000’ within an active MDA/MTA above FL140 and above FL290 where both aircraft are not RVSM approved o Or 500’ vertically (subject to regulatory approval).\n\nA pilot shall inform the controller if they elect not to act on the controller’s deconfliction advice. The pilot then accepts responsibility for\n\ninitiating any subsequent collision avoidance against that particular conflicting aircraft\n\nDeconfliction service shall only be provided to aircraft operating at or above the ATC unit terrain safe level unless on departure when\n\nclimbing to unit terrain safe level or to aircraft following notified instrument approach procedures.\n\nIf a pilot requests descent below ATC unit terrain safe level the controller shall no longer provide a deconfliction service but should,\n\nwhere possible, provide a traffic service and inform the pilot.\n\nA pilot may operate under their own navigation, or a controller may provide headings for the purpose of positioning, sequencing,\n\nnavigational assistance or to achieve deconfliction minima. If a heading is unacceptable the pilot shall advise the controller immediately\n\nA pilot shall not alter course without first advising and obtaining a response from the controller unless safety is likely to be compromised.\n\nControllers will normally provide level allocations for positioning, sequencing, navigational assistance, or to achieve deconfliction\n\nminima. If a level is unacceptable the pilot shall advise the controller immediately\n\nA pilot shall not alter levels without first advising and obtaining a response from the controller unless safety is likely to be compromised.\n\nProcedural Service\n\nATS where in addition to the provisions of a Basic Service the controller provides restrictions, instructions and approach clearances,\n\nwhich if complied with, shall achieve deconfliction minima against other traffic participating in the procedural service.\n\nNeither traffic information or deconfliction advice can be passed against unknown traffic.\n\nProcedural service does not require information derived from an ATS surveillance system.\n\nProcedural Service shall only be provided by controllers at ATC units with Regulatory approval to provide such an ATS.\n\nNot all ATC units are able to provide a Procedural Service. However, Procedural Service is most commonly available from ATC units\n\nwithout surveillance equipment that also have notified IFR arrival, departure or en-route procedures. At such units, Procedural Service offers the greatest protection to pilots.\n\nA procedural service shall only provided to flights under IFR irrespective of meteorological conditions.\n\nThe controller will expect the pilot to accept levels, radials, tracks, routes and time allocations that may require flight in IMC. A pilot who\n\nis not suitably qualified to fly in IMC shall not request a Procedural Service unless compliance permits the flight to be continued in VMC.\n\nAircraft do not need to be identified in order to receive a procedural service.\n\nThe pilot is wholly responsible for traffic avoidance although the controller will provide traffic information, if it is considered that a conflict\n\nmay exist, on aircraft in receipt of a basic service or traffic service.\n\nThe controller can only pass information on aircraft they in communication with or have been passed information form a different ATS\n\nunit.\n\nA controller shall allocate levels, radials, tracks, routes and time restrictions to achieve planned deconfliction minima.\n\no 1000’ vertically o 500’ vertically (subject to regulatory approval o Those lateral and longitudinal criteria listed in CAP 493 as lateral and longitudinal separation standards\n\nA pilot shall inform the controller if they elect not to act on the controller’s deconfliction advice. The pilot then accepts responsibility for\n\ninitiating any subsequent collision avoidance against that particular conflicting aircraft\n\nThe pilot remains wholly responsible for terrain clearance.\n\nControllers will normally provide level allocations for positioning, sequencing, navigational assistance, or to achieve deconfliction\n\nminima. If a level is unacceptable the pilot shall advise the controller immediately\n\nA pilot shall not alter levels without first advising and obtaining a response from the controller unless safety is likely to be compromised.","ref":"CAA - UK Flight Information Services · CAP 774 UK Flight Information Services: Fourth Edition"},{"code":"3.4.7","q":"Explain the types of Air Traffic Service inside of controlled airspace","a":"Radar Control Service\n\n•  Should be provided to\n\no All IFR traffic in airspace classes A – E o VFR flights in airspace classes B, C and D o All SVFR flights\n\nShould only be provided where surveillance coverage is available 10nm each side of the aircraft track, between points on the track\n\n10nm form each edge of controlled airspace other than. o Air System’s climbing into CAS subject to the following provisions ▪ The base of surveillance coverage is beneath the base of CAS\n\n▪ Transit is not permitted at a level where 5000’ of surveillance coverage does not exist beneath the Air System unless it is subject to a Civil ATC clearance from the relevant sector controller.\n\nRadar Control Service is an ATS under which pilots follow mandatory instructions to enable the prescribed separation minima between\n\nAir Systems to be maintained. Such mandatory instructions will generally be associated with essential details of conflicting traffic.\n\n•  Pilots will not change heading or level without prior approval of the Radar Controller\n\nWhen an Air System completes a crossing of CAS, and in the absence of a radar request to the contrary, controllers will re apply the\n\ntype of ATS being provided prior to Radar Control Service without recourse to the pilot.","ref":""},{"code":"3.4.8","q":"Explain the importance of safety altitude","a":"En Route\n\nShould be calculated by adding 1000’ to the highest obstacle located, as a minimum, within 5nm of the aircraft position rounded up to the next\n\n100’\n\nIn mountainous terrain this should be a minimum of 2000’\n\nMountainous terrain is defined as an area of changing terrain profile where the changes of terrain elevation exceed 3000’ within a distance of\n\n10nm\n\nWhen severe turbulence is forecast consideration should be given to increasing the safety altitude further\n\nWhere turbulence associated with mountain and lee waves are forecasted or present, a minimum in-flight clearance of 5000’ is necessary above\n\nmountains which are up to 5000’ in height above the surrounding terrain.\n\nFor higher mountains the clearance should be at least equal to their height above the terrain\n\nDescent below Safety altitude\n\nUnless specifically authorised or compelled to do so in an emergency pilots should not descend below safety altitude unless\n\no They are in visual contact with the ground o Using a suitable terrain following radar equipment o Can be let down by a means of an approved radar or radar terminal approach procedure provided by air system ATC units","ref":"RA2307"},{"code":"3.4.9","q":"Explain Performance Based Navigation Operations","a":"ADH and AM(MF) shall ensure PBN operations are only conducted by Air Systems within their AoR that are approved for PBN operations and\n\nby pilots who are appropriately qualified.\n\nArea Navigation (RNAV)\n\nNavigation that permits Air System operations on any desired flight path using ground and space based or on board navigation aids\n\nRequired Navigation Performance (RNP)\n\nRNP is RNAV with the support of on board performance monitoring and alerting\n\nPerformance Based Navigation (PBN)\n\nSpecifies that Aircraft RNAV and RNP system performance requirements are defined in terms of accuracy, integrity, continuity and functionality.\n\nIt enables air systems to fly flexible, accurate and repeatable 2D and 3D flight paths. PBN encompasses both RNAV and RNP navigation specifications. Navigation Specifications\n\nSet of Aircraft and Aircrew requirements needed to support PBN operations within a defined airspace\n\nDefine lateral navigation accuracy in terms of total system error (TES)\n\nRNAV 10 / RNO 10 = lateral TSE must be within 10nm for 95% of the total flight time","ref":""}]},{"code":"3.5","title":"AIDU/MILFLIP","items":[{"code":"3.5.1","q":"Decode TAP symbology for AIDU and Jeppesen plates","a":"Decode TAP symbology for AIDU and Jeppesen plates using appropriate decodes. AIDU Legend Card\n\nAIDU Spec & Legend Airport Chart Legend Jeppesen","ref":""},{"code":"3.5.2","q":"Decode ERC symbology","a":"Decode ERC symbology and Jeppesen charts using appropriate decodes. AIDU Legend 7\n\nAirport Chart Legend Jeppesen","ref":""}]},{"code":"3.6","title":"ICAO / PANS OPS / TERPS departure and arrival information","items":[{"code":"3.6.1","q":"Describe the types of procedural turn","a":"The syllabus leaves 3.6.1 blank. The content below is taken from the TERPS vs PANS-OPS comparison in the Part 8 reference pages of this same document.\n\nPANS-OPS recognises four reversal procedures:\n\n45°/180° procedure turn\n\n80°/260° procedure turn\n\nBase turn\n\nRacetrack procedure\n\nPANS-OPS application:\n\n45/180 and 80/260 — the aircraft must stay within +/- 30° of the outbound track to remain inside the obstacle-clearance area.\n\nBase turn — entry expands on the non-protected side by an extra 30°. There is no entry sector on the protected side.\n\nRacetrack — enter as for a normal hold.\n\nYou are limited to the procedure depicted on the approach plate: you cannot fly a 45/180 where a racetrack is published.\n\nTERPS application:\n\nThe aircraft may manoeuvre in any way it chooses within the protected airspace shown on the barbed-arrow side.\n\nHILOs and teardrops must be flown as published.","ref":""},{"code":"3.6.2","q":"If you are given a direct-to on a SID or STAR, does that cancel the rest of the SID / STAR?","a":"No.. issuing a CLEARED DIRECT clearance for a waypoint on the SID or STAR means that the aircraft will resume its navigation on the SID / STAR at the cleared waypoint. The aircraft is no longer on the lateral profile of the SID / STAR and the restrictions of the bypassed waypoints are cancelled. The pilot will then rejoin the SID / STAR at the given waypoint and comply with all restrictions henceforth. If the aircraft is cleared to a waypoint not on the SID / STAR the SID / STAR is therefore cancelled.\n\nWhen an arriving aircraft is vectored or cleared direct to a point not on the STAR, STAR cancelled. Controlled will notify the pilot cleared level, provide speed and level restrictions if necessary and notify the pilot if it is expected that aircraft will be instructed to subsequently rejoin the STAR (ICAO DOC 4444 6.5.2.4.6). Similar for SIDs in ICAO doc 4444 6.3.2.4.5","ref":""},{"code":"3.6.3","q":"What are the requirements to satisfy an omni-directional departure.","a":"In cases where no suitable navigation aid is available, or no track guidance is provided, omnidirectional procedures are used. Where obstacles do not\n\npermit development of omnidirectional procedures, the pilot shall ensure that ceiling and visibility will permit obstacles to be avoided visually. Omnidirectional departures may specify sectors to be avoided.\n\nThe departure procedure begins at the departure end of the runway (DER), which is the end of the area declared suitable for take-off (i.e. the end of the runway or clearway as appropriate). Since the point of lift-off will vary, the departure procedure assumes that a turn at 120 m (394 ft) above the\n\nelevation of the aerodrome is not initiated by the pilot sooner than 600 m from the beginning of the runway. Procedures are normally designed/optimized for turns at a point 600 m from the beginning of the runway. However, in some cases the pilot shall not be allowed to initiate a turn before the DER (or a specified point), and this information will be noted on the departure chart.\n\nUnless otherwise specified, departure procedures assume a 3.3 per cent PDG and straight climb on the extended runway centre line until reaching 120\n\nm (394 ft) above the aerodrome elevation. The basic procedure ensures: a) the aircraft climbs on the extended runway centre line to 120 m (394 ft) before turning; and b) at least 75 m (246 ft) of obstacle clearance is provided before any turns greater than 15°.\n\n3.6.4 When conducting a procedural approach, at what angle must you approach the IAF to conduct the procedure turn? Entry into a reversal procedure should be from a track within +/- 30 degrees of the outbound track. Where entry is desired from tracks outside these limits, suitably protected airspace must be provided to allow the pilot to manoeuvre onto the outbound track.\n\nHowever, for base turns, where the ±30° direct entry sector does not include the reciprocal of the inbound track, the entry sector is expanded to include it.\n\nFrom the UK AIP: Except where an 80°/260° procedure turn is specifically prescribed, procedure turns specified in instrument approach procedures may be flown as 45°/180° or 80°/260° type, at pilots’ discretion.","ref":""},{"code":"3.6.5","q":"When can you descend when cleared for the approach?","a":"When cleared for the approach the pilot is to maintain the assigned altitude until established on the first segment of the instrument approach procedure Arrival Area sector to the minimum altitude depicted within the defined area/ subdivision unless instructed otherwise by ATC.\n\nHowever, it varies depending on where you are in the world. In the FAA and ICAO, you can only descend along a published portion of an approach procedure, except that in the FAA, if there are TAAs, they are considered operationally usable altitudes, and you are allowed to descend. I have not seen anything explicit in the ICAO docs that say you can descend within a TAA when cleared for an approach.","ref":""},{"code":"3.6.6","q":"What are the requirements of a visual approach?","a":"A visual approach may be offered to aircraft on an IFR flight plan when approaching to land in VMC\n\nAllows pilots to omit more prescribed instrument approach tracks – expedite landings\n\nOnly offered when VMC and Clear of clouds – Ceiling must be at least 1000’ above and a visibility of 3 SM or greater\n\nA visual approach has no missed approach segment – if executing a missed approach maintain clear of cloud and contact ATC for guidance.\n\nSeparation shall be provided between an aircraft cleared to execute a visual approach and other arriving and departing aircraft. For successive\n\nvisual approaches, separation shall be maintained by the controller until the pilot of a succeeding aircraft reports having the preceding aircraft in sight. The aircraft is then responsible for its own separation.\n\nAircraft Operations - Visual Approaches","ref":""},{"code":"3.6.7","q":"When given the clearance straight ahead on a missed approach what are you expected to do?","a":"Where the term 'straight ahead' is used in missed approach procedures, pilots should maintain Final Approach Track (FAT) unless a different track is given. On departure Straight Ahead means track extended runway centerline","ref":""},{"code":"3.6.8","q":"Unless specified on the approach plate, what climb gradient are you expected to fly in a missed approach?","a":"Climb gradients are a minimum of 2.5 degrees up to a maximum of 5 degrees (anything other than 2.5 degrees will be noted on the plate and may have a higher DH/DA. Expected track change is to be no more than 15 degrees unless a turning missed approach and allows for a Min Obstacle Clearance of 30m.","ref":""}]}]},{"num":"4","name":"Flight Instruments and Radio Aids","sections":[{"code":"4.1","title":"Fight Instruments (Generic)","items":[{"code":"4.1.1","q":"Describe the basic principle of operation of an Air Speed Indicator (ASI).","a":"A stationary aircraft is subject only to static (atmospheric) pressure (𝑝𝑠 ). In flight there is additional dynamic pressure (𝑝𝑑 ) on its leading surfaces due to a buildup of the air, the magnitude of which is dependent upon the forward speed of the aircraft (𝑉) and the density of the air (𝜌), and is given by the equation:\n\n𝟏 𝟐\n\n𝒑𝒅 =  𝝆𝑽\n\nThe two pressures combined give the total pressure (𝑝𝑡 ) acting on the aircraft. 𝒑𝒕 = 𝒑 𝒅 + 𝒑𝒔 Since dynamic pressure is a function of airspeed, an instrument able to measure dynamic pressure in isolation from static pressure could be used to indicate airspeed. This is achieved by allowing both static and dynamic pressure to act on the inside of a flexible diagram, while allowing only the static pressure to act on the outside. The magnitude of the distortion is dependent only on the magnitude of the dynamic pressure, the static pressure on each of the diaphragm cancelling each other out: the magnitude of the distortion is dependent on the magnitude of the dynamic pressure which is proportional to the airspeed. Through suitable electro-mechanical links, the distortion of the diaphragm can be presented as an indicated airspeed. Static ports are used to measure static pressure. Dynamic pressure is measured by an open-ended probe mounted in the airstream. The two are often mounted in the same probe: pitot-static probe.","ref":"AP3456 – Volume 5 – Chapter 4"},{"code":"4.1.2","q":"Describe the possible errors of an Air Speed Indicator (ASI)","a":"The ASI is calibrated assuming both constant air density (standard sea level density) and no instrument defects. Any departure from these conditions, or disturbance in the pitot or static pressures being applied to the instrument, will lead to a difference building up between the actual dynamic pressure and the measured dynamic pressure, or, put another way, between the true airspeed and the indicated airspeed. The airspeed displayed will be in error. There are four sources of error, often remembered by the phrase ‘Pressure Instruments Can Deceive’ Pressure Error. Pressure error results from disturbances in the static pressure around the aircraft due to movement through the air. The\n\nerror may be influenced by:\n\n•the position of the pressure head, pitot head or static vent\n\n•the angle of attack of the aircraft\n\n•the speed of the aircraft\n\n•the configuration of the aircraft (i.e. flaps/gear/airbrakes)\n\nthe presence of sideslip.\n\nInstrument Error. Instrument error is caused by manufacturing tolerances in the pitot-static system. The error is determined during calibration and any necessary correction is combined with that for pressure error.\n\nCompressibility Error. As air enters the pitot system it gets compressed. The ASI is calibrated at standard sea level pressure and the compression of the air as it enters the pitot system is accounted for so there is no compressibility error at sea level. At higher altitudes the compression is not correctly accounted for and will cause the instrument to read greater than the Equivalent Air Speed (EAS). Density Error. Standard mean sea level air density is used for instrument calibration. As altitude increases the air density lowers and the IAS, and thus EAS, will begin to underread. To maintain a constant TAS, we need to reduce the IAS in the climb. For example, at 40,000 ft the air density is approximately ¼ that at sea level. Since the dynamic pressure is 𝑝𝑑 = ½𝜌𝑉 2 , we can see that if the density is reduced to ¼ its sea-level value, the speed must double (22 = 4) its value to give the same dynamic pressure (and therefore speed indication). It follows then that if the same IAS were flown, the TAS would double. ‘Pressure Instruments Can Deceive’ Pitot-static systems are subject to blockages and leaks, and the effect of each on the system is worth noting. Blockages Pitot. A total blockage off the pitot probe will not register changes in dynamic pressure and therefore airspeed. However, it may function as a simple barometer, showing an increase in sped with an increase in altitude, as the static pressure around the capsule drops in the climb allowing the capsule to expand and so register an increased speed. If a partial blockage occurs, dynamic pressure will be reduced, and the instrument will under-read, eventually towards zero. Static. If the static tube is blocked, the ASI will over-read at lower altitudes and under-read at higher altitudes than that at which the blockage occurred. Leaks\n\nPitot. A leak in the pitot tube causes the ASI to under-read as the full dynamic pressure is not supplied to the instrument. Static. A leak in the static tube, where the pressure outside the pipe is lower than static (ie most unpressurized aircraft), will cause the ASI to over-read. Where the outside air is higher than static (ie in a pressurized cabin) the ASI will under-read.","ref":"AP3456 – Volume 5 – Chapter 4"},{"code":"4.1.3","q":"Describe the basic principle of operation of a Vertical Speed Indicator (VSI)","a":"A vertical speed indicator (VSI) is a sensitive differential pressure gauge, which displays a rate of change of atmospheric pressure interpreted as a rate of climb or descent. It does this by measuring the difference in pressure between two chambers, one located within the other. Direct static pressure is fed to the inner chamber (an aneroid capsule).\n\nHowever, the air surrounding the capsule must flow in to and out of the outer chamber through a calibrated metering unit which restricts the flow into and out of the case. As the AS changes altitude, the static pressure changes, but the calibrated restriction ensures a pressure differential builds up between the inside of the aneroid capsule and the outer chamber, which causes the capsule to expand or contract. The greater the rate of\n\nclimb/descent, the greater the pressure difference between the inner and outer capsule, and so the greater the deformation of the inner capsule. The amount of deformation can therefore be interpreted as an indication of the rate of climb/descent. Using suitable electro-mechanical links, the expansion of the capsule can be displayed as a rate of climb/descent. After a brief period of level flight, the pressure inside both chambers will equalise and the pointer return to the zero position.\n\nAP3456 – Volume 5 – Chapter 3","ref":""},{"code":"4.1.4","q":"State the possible errors of a Vertical Speed Indicator (VSI)","a":"The VSI only uses the static pressure system so any errors that affect the static system affect it (SLIP). Static Line Blockage. If the static line or vent becomes blocked by ice (or any other obstruction), the VSI will be rendered unserviceable, and the pointer will remain at zero regardless of the vertical speed. Lag Error. Since the instrument relies on there being a differential pressure between the inner and outer chambers, there may be a small lag following the initiation of a climb or descent before the instrument settles down to show the correct rate. A similar delay occurs before the pointer indicates zero when the aircraft is leveled. This is eliminated by using accelerometers that detect a change in vertical speed and produce an immediate response on the needle. This input is quickly phased out once a pressure differential builds up. Instrument Error. Instrument error is the result of manufacturing tolerances in the pitot-static system and is usually insignificant.\n\nPressure Error. A change of pressure not associated with a climb/descent will be indicated if the static pressure over the vent is changed. Pressure errors are caused during accelerations, when changing configuration or if shock waves pass over the vent.","ref":"AP3456 – Volume 5 – Chapter 3"},{"code":"4.1.5","q":"Describe the basic principle of operation of an Altimeter","a":"The Pressure Altimeter is a simple differential pressure gauge. Static pressure is allowed\n\nto act upon several sealed, partially evacuated, aneroid wafers, which expand and contract depending on the difference in pressure between the two. Several capsules are used to increase sensitivity. The deformation of the capsules is transmitted to a dial to provide an indication of altitude. Static pressure does not remain constant, and the altimeter needs to be able to be\n\nrecalibrated to different baseline pressures. The dial setting knob allows the indicator needle to be moved away from the normal datum. Rather than using a simple mechanical link from capsule to dial, servo-assisted altimeters use electrical signals to drive the pointers which increases both the accuracy and\n\nsensitivity of the altimeter.","ref":"co                                                                    AP3456 – Volume 5 – Chapter 1"},{"code":"4.1.6","q":"State the possible errors of an Altimeter","a":"Altimeter errors are broken down in to two categories: Instrument and installation errors, and those due to non-standard atmospheric conditions. In addition, they can be subject to blockages and leaks. Instrument and Installation Errors (PHIL) Pressure Error. Pressure error only applies when the aircraft is moving or airborne and occurs when the true external static pressure is not detected. Although the error is generally negligible at low speeds and altitudes, it can become significant at high speeds, during flight maneuvers, or when services such as flaps, airbrakes, or gear are operated. Careful placement of the static vents greatly reduces the errors. Hysteresis Loss. A capsule under stress exhibits an imperfect elastic response. The capsule will have a different deflection for a given pressure change according to whether height is increasing or decreasing. This effect is difficult to predict and is most noticeable after sharp climbs or descents.\n\nInstrument Error. Instrument error is caused by small irregularities in the manufacture of the pitot-static systems. They are usually insignificant. Lag Error. The response of the capsule and linkage is not instantaneous, so the altimeter lags whenever there is a rapid change in height. Servo-altimeters virtually eliminate this problem. Non-Standard Atmosphere Errors (BOT) Any atmospheric variation from ISA conditions, to which the altimeter is calibrated, can cause an error in the reading.\n\nBarometric Error. Barometric error occurs when the actual datum pressure differs from that to which the altimeter has been set.\n\nIn this example, the AS flies from Point A where the MSL pressure is 1030 mb, to Point B where the MSL pressure is 1010 mb. The 1030 mb setting is retained on the altimeter, and the aircraft is flown at 3,000 ft indicated. As the MSL pressure decreases, the effective level of the\n\npressure datum (1030 mb) becomes progressively lower. As a result, the altimeter would begin to overread, and you’d be flying lower than intended.\n\nConversely, if the flight was from an area of low pressure to one of high pressure the altimeter would read low if not corrected, and you’d be flying higher than intended. In summary, from HIGH to LOW the altimeter reads HIGH and you’re flying LOW, and from LOW to HIGH the altimeter reads LOW, and you’re flying HIGH. Barometric error is overcome by changing the millibar scale, as appropriate, for the region of operation. Pressure Error High to Low you’re flying too Low Low to High you’re flying too High Orographic Error. This error is effectively localized barometric or temperature error. Disturbed airflow over hills/mountains may cause localized low-pressure regions and induce a barometric error. Similarly, if standing waves are present temperature changes as the air rises and falls may induce a localized temperature error.\n\nTemperature Error. Temperature error arises when the atmospheric conditions differ from those assumed by the standard atmosphere used to calibrate the altimeter. ISA assumes a temperature lapse rate of 1.98º C per 1,000 ft up to 36,090 ft, with a constant temperature of –56.5º C above that. If the actual temperatures differ from that, which they always do, then the indicated altitude will be incorrect. In a cold air mass, the air density is greater than in a warm air mass, and 1mb no longer represents ~ 30 ft vertical difference, but something\n\nless. As a result, when flying into a colder air mass, the altimeter will overread and you’ll be flying lower than you think.\n\nThe error is not easy to compensate for without perfect knowledge of the atmosphere temperature structure. The magnitude of the error is approximately 4 ft/1,000 ft for each 1º C of difference from ISA.\n\nWhen the temperature is LESS than ISA the aircraft will be LOWER than the altimeter reading, so a safety factor (TEC) is added to required altitudes based on the aerodrome surface temperature, for aerodromes up to 1000ft above sea level. For aerodromes higher than that, ISA deviation should be used. Temperature Error High to Low you’re flying too Low Low to High you’re flying too High\n\nTemperature Error Corrections should be applied: When the aerodrome temperature is 0 °C or colder, temperature error correction must be added to:\n\na.DH/DA or MDH/MDA and step-down fixes inside the FAF.\n\nb.ALL low altitude approach procedure altitudes in mountainous regions (defined as terrain of 3000 ft amsl or higher).\n\nWhen pilots intend to apply corrections to the FAF crossing altitude, procedure turn or missed approach altitude, they must advise ATC of their intention and the correction to be applied. Pilots may refuse IFR assigned altitudes if altimeter temperature error will reduce obstacle clearance below acceptable minima. However, once an assigned altitude has been accepted, it must not subsequently be adjusted to compensate for temperature error.\n\nMinimum Sector Altitude (MSA). When the aerodrome temperature is –30 °C or colder, add 1000ft to the MSA to ensure obstacle clearance.","ref":"AP3456 - Volume 5 – Chapter 1"},{"code":"4.1.7","q":"Describe the basic principle of operation of a Direct Indicating Compass (DIC)","a":"The direct indicating compass aligns itself with the Earth’s magnetic field and therefore indicates the direction of Magnetic North. However, the Earth’s magnetic field dips into the Earth and therefore has both a horizontal and a vertical component: for direction purposes we are only interested in the horizontal component, but the vertical component affects DIC. For a DIC to work effectively, it must exhibit:\n\nHorizontality. The dip in the Earth magnetic field causes\n\nthe compass magnet to dip.\n\nThe tendency to tilt reduces the magnetic moment in the horizontal plane in which direction is measured. A pendulous suspension system is therefore used to overcome the magnet’s tendency to tilt. When the pendulously suspended magnet tilts to align with then magnetic field, the magnet system’s centre of gravity is displaced from the vertical through the pivot, forming the couple Wd, which acts to restore the compass to the horizontal. However, some dip will remain: in the UK that residual dip is approximately 2º. •\n\nSensitivity. A compass is made more sensitive by: o Increasing the magnetic moment of the magnet system: small powerful magnets. o Reducing the moment of inertia of the magnet system: small powerful magnets.\n\no Reducing the friction at the suspension point: jewelled bearings and suspending magnets in liquid.\n\nAperiodicity. A nice word simply meaning that the compass does wobble/oscillate. This is achieved by designing a compass with a low\n\nmoment of inertia and a high magnetic moment, as well as suspending the compass in fluid.","ref":"AP3456 - Volume 5 – Chapter 9"},{"code":"4.1.8","q":"State the possible errors of a Direct Indicating Compass (DIC)","a":"A Direct Indicating Compass is subject to several errors.\n\nVariation. True North and Magnetic North a not the same and,\n\ntherefore, account must be taken of variation between the two. The amount of variation will depend where on the Earth surface the compass is – in the UK the variation is currently close to 0˚.\n\nDeviation. These are locally induced errors that upset the magnetic\n\nfield: turning on the windshield heating for example.\n\nAcceleration Errors. A simple magnet suspended below a pivot\n\npoint which has a dip angle to the Earth surface, will have a displaced C of G, as shown below for a compass in the Northern hemisphere.\n\nIf the aircraft is accelerated due North or South then there is usually no acceleration error, only more or less dip is created. If the compass, in the Northern hemisphere, is accelerated in either an easterly or westerly direction, the combination of the pendulum effect and dip results in an indication of a turn towards North. It follows that a deceleration indicates a turn towards the South.\n\nThis can be remembered as ANDS: Acceleration gives a turn to the North and a Deceleration to the South in the northern hemisphere. It follows that acceleration errors are at a maximum on E-W headings. The opposite is true in the Southern hemisphere: an acceleration gives a indicates a turn to the South, a deceleration a turn to the North – only ‘ASDN’ is even less memorable than ANDS!. Turning Errors. When in a turn, the magnets are no longer horizontal to the Earth’s surface and lose the property of horizontality: effectively it’s another form of dip. The magnet still tries to align itself with the Earth’s magnetic field and in doing so induced an error in the compass reading.\n\nThe effect depends on the direction and rate of turn. In turns through North, the magnet system turns in the direction of turn and the indicated turn is slower than the actual turn, ie the compass under reads the turn indicating a turn of perhaps 20º for an actual turn through 45º. In turns through South, however, the magnet system turns in the opposite direction to the turn and the indicated turn is greater than the actual turn, ie the compass indicates a turn of perhaps 40º for an actual turn of 20º. These errors are at a maximum on N-S headings where the dip angle is at a maximum.","ref":"AP3456 - Volume 5 – Chapter 9"}]},{"code":"4.2","title":"Gyroscopic Instruments","items":[{"code":"4.2.1","q":"State the Basic principles of the Ring Laser Gyro","a":"The ring laser gyro is one of the modern alternatives to conventional gyros for a number of applications including aircraft inertial navigation systems\n\nand attitude/heading reference systems. The ring laser gyro has no moving parts and is not a gyroscope in the normal meaning of the word. The ring laser gyro is, however, a very accurate device for measuring rotation and became the system of choice for use with strapdown inertial navigation systems. In ring laser gyros, the rotating mass of the conventional gyro is replaced by two\n\ncontra-rotating beams of light. The main body of the gyro consists of a single piece of a vitreous ceramic of low temperature coefficient. A gas-tight cavity is accurately machined into the monoblock and this cavity is then filled with an inert gas, typically a mixture of Helium and Neon. A DC electrical discharge ionizes the gas and causes the lasing action. Two beams of light are produced, flowing in opposite directions in the cavity. Mirrors are used to reflect the beams around the enclosed area, producing a 'laser-in-a-ring' configuration. The frequency of oscillation of each beam corresponds to the cavity resonance condition. This condition requires that the optical path length of the cavity be an integral number of wavelengths. The frequency of each beam is therefore dependant on the optical path length. At rest, the optical path length for each beam is identical; therefore, the frequencies of the two laser beams are the same. However, when the sensor is rotated about the axis perpendicular to the lasing plane, one beam travels an increased path length, whilst the other travels a reduced path length. The two resonant frequencies change to adjust to the longer or shorter optical path, and the frequency difference is directly proportional to the rotation rate. This phenomenon is known as the Sagnac effect. The frequency difference is measured by the beaming of an output signal for each wave on to photo detectors spaced one quarter of a wavelength apart, causing an optical effect known as an interference fringe. The fringe pattern moves at a rate that is directly proportional to the frequency difference between the two beams. It is converted to a digital output, where the output pulse rate is proportional to the input turn rate, and the cumulative pulse count is proportional to the angular change.\n\nThe reason the two beams have to occupy the same physical cavity is the sensitivity of laser light to cavity length. If they did not, a temperature induced difference in path length could result in a large frequency mismatch between the two beams. The path length control mechanism is used to alter the intensity of the laser and thus control expansion due to excess heat. To help avoid perceived differences in path length due to flow of the Helium/Neon gas mix, two anodes are used to balance any flow caused by ionization. The main advantages of the ring laser gyro are:\n\nIts performance is unaffected by high 'g'.\n\nIt has no moving parts and therefore has high reliability and low maintenance requirements.\n\nIt has a rapid turn-on time.\n\nThe technical problems associated with ring laser gyros can all be overcome. However, solution of these problems inevitably increases costs which are already very high due to the complex, 'clean-room' manufacturing facilities needed to provide:\n\nPrecision machining and polishing.\n\nHigh quality mirrors.\n\nVery good optical seals.\n\nA carefully balanced mix of Helium and Neon, free of contaminants.\n\nWhile the ring laser gyro represents a major advance over the traditional spinning gyro, it is only one of a number of alternatives. The search for\n\nnew gyroscopic devices continues, driven by considerations of both cost and accuracy.","ref":"AP3456 - Volume 5 – Chapter 10"},{"code":"4.2.2","q":"State the possible errors in a Ring Laser Gyro","a":"Ring laser gyros are subject to a number of errors, the most notable are:\n\nNull Shift. Null shift arises due to a difference in path length as perceived by the two opposite beams, thus producing an output when no\n\nrotation exists. The major causes of perceived path length difference are: o Differential movement of the gas in the cavity. o Small changes in the refractive index of the monoblock material as the direction of travel of the laser light changes.\n\nLock-in. Lock-in occurs when the input rotation rate of the gyro is reduced below a critical value causing the frequency difference between\n\nthe clockwise and anti-clockwise beams to drop to zero. One of the main causes of this phenomenon is backscatter of light at the mirrors. Some of the clockwise beam is reflected backwards, thereby contaminating the anti-clockwise beam with the clockwise frequency. Similarly, backscattering of the anti-clockwise beam contaminates the clockwise beam. With low input rotational rates, the two beams soon reach a common frequency which renders detection of rotation impossible. Several methods are used to ensure that lock-in is minimized. One method is to physically dither the gyro by inputting a known rotation rate in one direction, immediately followed by a rotation rate in the opposite direction. As the dither rate is known, it can be removed at the output stage. The dither ensures that the two frequencies are kept far enough apart to avoid lock-in. AP3456 - Volume 5 – Chapter 10","ref":""}]},{"code":"4.3","title":"Flight Instruments (C-17)","items":[{"code":"4.3.1","q":"Describe the IRS","a":"IRS stands for Inertial reference system.\n\n2 Inertial reference unit control panels\n\nFour inertial reference units (IRUs)\n\nEach IRU has its own mounting tray and battery\n\nInertial reference units\n\nHas its own stored magnetic heading variation table\n\nWhen GPS updating to the navigation source the position of the PILOT ID switch determines which IRU / GPS blended position is used\n\nby the MC\n\nUtilise accelerometers and ring laser gyros to sense aircraft angular rates and accelerations.\n\n•\n\nCompute and provide o Aircraft attitude o Attitude rates o Heading o Inertial velocity o Acceleration o Uncorrected present position information\n\nAll have embedded GPS receiver capability (MGPS) only 1 and 4 are wired to the antennae and do not supply GPS data","ref":"TO 1C-17A-1 para 1-2321 to 1-2330"},{"code":"4.3.2","q":"Describe the operating modes of the IRS","a":"Pre-Align Mode\n\nOnly pitch/roll information and body rates and accelerations are available for flight control applications.\n\nGyro Compass Alignment Mode\n\nPrimary method of IRU alignment\n\nTakes between 4 min and approx. 8 min to align dependent on latitude\n\nStored Heading Alignment mode.\n\nNormally used for alert starting – fast start takes approximately 30 seconds\n\nLevels to local vertical and aligns to its last internally computed heading\n\nAircraft must not be moved after “cocking” and prior to SH alignment\n\nIf the stored heading differs by more than 3 degrees from the alignment derived heading in any IRU the MC commands a GC alignment\n\nIt will then not align better than DNAV\n\nBest Available True Heading Alignment mode\n\nOnly available when the aircraft is operating beyond latitudes of 78 degrees North or South\n\nDesigned for use in polar regions if the IRS must be shut down for extended ground time\n\nUses present position data and operator entered true heading for alignment\n\nDNAV is the only available mode after a BATH alignment\n\nNavigation mode\n\nNormal node of operation\n\nProvides all system functions\n\nDegraded Navigation mode\n\nIRU in DNAV is not used by the mission computer for the Triple mix solution\n\nBlended solution (Present Position)\n\nSolution computed in one IRU blended from its inertial and GPS data\n\nSolution comes from the pilot ID switch position (IRU1 or 4)\n\nThis is used as long as GPS updating is selected and either IRU 1 or 4 is healthy with its GPS solution passing reasonableness criteria\n\nCGPS used for RAIM containment\n\nCGPS contained within the Precision Landing\n\nTriple Mix\n\nUsed when non GPS electronic NAVAIDS are selected and the NAVAIDS pass all validity criteria\n\nMC updates the triple mix PPOS once each second by a percentage of the difference between its PPOS and the NAVAIDs fis position\n\nTO 1C-17A-1","ref":""}]},{"code":"4.4","title":"Navigation and Radio Aids","items":[{"code":"4.4.1","q":"Explain the basic principle of GPS","a":"The NAVSTAR Global Positioning System (GPS) is a US space-based radio positioning system, using a constellation of satellites to provide highly accurate\n\nposition, velocity, and time (PVT) data. It is one of several GNSS available for use. There are three major segments to the system; Space, Control and User. The system is available globally, continuously, and under all weather conditions to users at or near the Earth’s surface. However, the signals are quasi-optical and there must be a direct line of sight between the satellites and the receiver aerial for full operation. As the\n\nreceivers operate passively there can be an unlimited number of simultaneous users. GPS has features designed to deny an accurate service to unauthorized users, prevent spoofing and to reduce receiver susceptibility to jamming. Each satellite broadcasts radio frequency\n\nranging codes and a navigational data message. The GPS receiver measures the transit time of the signals and can thereby determine its range from a satellite. The data message enables the receiver to determine the position of the satellite at the time of transmission, and thus by ranging from 3 or more satellites a fix can be obtained. Space Segment. The GPS space segment consists of 24 operational satellites. There is a continuing programme to replace and maintain the space segment to account for technical failures of satellites in service and faults during launch so this figure of 24 may vary slightly as new and failing orbiters are exchanged. The satellites are in six orbital planes with three or four operational satellites in each orbit. The orbit height is 20,200 km and the orbital planes are inclined at an angle of 55º to the equator. A satellite takes approximately 12 hours to complete an orbit. The satellites are positioned such that at least 5 satellites are normally observable by a user anywhere on the Earth. Control Segment. The control segment consists of one Master Control Station (MCS) in Colorado Springs (USA) together with additional monitor stations at Hawaii, Kwajalein (Western Pacific), Diego Garcia (Indian Ocean), and Ascension (S Atlantic). User Segment. The user segment comprises a wide variety of military and civilian GPS receivers which can decode and process the satellite signals. The receivers may be 'stand-alone' sets, or part of integrated systems, and can serve a variety of applications such as navigation and surveying. Receivers for different applications can vary significantly in their design and function.","ref":"AP3456 - Volume 7 - Chapter 8"},{"code":"4.4.2","q":"Explain the basic principles of operation of a VOR beacon","a":"The principle of the VOR system is bearing by phase comparison: the aircraft’s equipment derives the bearing from the phase difference between two 30 Hz modulations associated with the radio frequency transmission of the ground beacon. All VORs transmit omni-directional and rotating directional signals, rotating at 30 Hz. On board equipment compares the phase difference between the limacon pattern\n\n(combined signal of the rotating and the static signal) and the static signal, the phase difference between the two indicating the bearing from the beacon. Timed interrogation pulses are used to determine range.","ref":"co                                                                   AP3456 - Volume 7 – Chapter 6"},{"code":"4.4.3","q":"Describe the basic principles of operation of an ILS","a":"The ground transmitters emit localizer and glidepath signals simultaneously which define the approach path. Ground marker beacons radiate vertically to provide range checks. The Localizer. The localizer operates on VHF frequencies in the range 108.1 MHz to 111.95 MHz. The transmitter emits two lobes which overlap. The centre of the region of overlap provides an area of equal signal amplitude defining the approach path (see Fig 1). The two lobes are modulated at different frequencies, the beam to the right of the centreline (when approaching to land) at 150 Hz; that to the left at 90 Hz. The localizer transmitter also emits the identification code for the installation. In an emergency, ATC can interrupt the localizer channel and use that frequency for speech transmissions to the aircraft, but not vice versa. The range of the localizer signal is 25 nm at 2,000 ft within plus or minus 10º of the localizer front course line or 17 nm between 10º and 35º of the localizer front course line. Above 2,000 ft these ranges may be reduced.\n\nThe aircraft localizer receiver detects the two signals and produces two output voltages, determined by the strength of the receive signals. The two\n\nvoltages are compared, and the difference displayed as a deflection of the display deviation bar. The display convention is such that the display centre represents the aircraft, and the deviation bar the ILS centreline. The display sensitivity will dictate at what angle, either side of the centreline, full-scale deflection occurs. This is normally adjusted so that full-scale deflection corresponds to ± 2.5º. It should be noted that the displacement of the deviation bar reflects the angular distance of the aircraft from the centreline and, thus, the\n\ncloser the aircraft is to the transmitter the larger is the displacement of the deviation bar for any given linear distance from the centreline. The Glidepath. The glidepath transmitter frequency is paired with the localizer frequency, but operates on UHF, in the range 328.6 MHz - 335.4 MHz. The glidepath produces two overlapping lobes, analogous to the localizer but in the vertical sense. The upper lobe is modulated at 90 Hz and the lower lobe at 150 Hz. The range of the glidepath signal is 10 nm at 2,000 ft up to 8º in azimuth either side of the localizer front course line.\n\nAs with the localizer, the glidepath receiver compares the signal strength received from each lobe and deflects an indicator accordingly. As with the localizer display, the centre of the indicator represents the aircraft, and the needle the glidepath. The centreline of the glidepath beam is usually set at an angle of 3º but can be varied between 2º and 4º to suit local requirements. The beamwidth is a function of the beam angle (θ) and extends from 0.45θ to 1.75θ above the horizontal. For a 3º beam angle this equates to 1.35º to 5.25º above the horizontal. The edges of the beam correspond to full scale deflection of the indicator needle. AP3456 - Volume 7 – Chapter 13","ref":""},{"code":"4.4.4","q":"State the C-17 radio navigation equipment","a":"The C-17 has:\n\n2 Precision Landing System Receivers (PLSRs) – CGPS containment\n\no Provide inputs for the electronic displays and the flight director system o Combines VOR, ILS, Marker Beacon, MLS receivers and Civil GPS Receivers\n\n2 DME receivers\n\n1 TACAN transceiver.\n\n1 ADF receiver\n\nFCOM – DSC-34-NAV-20","ref":""},{"code":"4.4.5","q":"State the C-17 RAIM predictions","a":"RAIM – Receiver Autonomous Integrity Monitoring\n\nGPS receivers are capable of receiving signals from all functioning GPS satellites above the horizon.\n\nRAIM function determines the uncertainty in aircraft position assuming that one of the satellites has an undetected positional error.\n\nP-RAIM\n\nChecks based upon satellite problems that may affect coverage along primary flight plans path\n\nOnly performed for destination and CARP/HARP waypoints that have a fixed or advisory time constraint\n\nIf an issue detected UNABLE RNP@ XXXX\n\nWhen either MGPS or CGPS is selected to update the MCs position the MC will store RAIM data from both the blended solution MGPS\n\nand the best CGPS\n\nThe P-RAIM function uses the MCs stored RAIM data only\n\nIf CGPS is the selected update source, the MC will use the stored CGPS data\n\nIf MGPS is the selected update source, the MC will use the stored MGPS data","ref":""}]}]},{"num":"5","name":"Meteorology","sections":[{"code":"5.1","title":"Definitions","items":[{"code":"5.1.1","q":"Decode and define (where appropriate) the following terms without reference to other material","a":"AUTO                      •   FU                                     •   PROB                         •   TCU\n\nBCMG                      •   FZ                                     •   RA                           •   TEMPO\n\nBKN                       •   G                                      •   RVR                          •   TS\n\nBR                        •   GR                                     •   SA                           •   UTC\n\nCB                        •   GS                                     •   SCT                          •   VA\n\nDR                        •   HZ                                     •   SFC                          •   VC\n\nDU                        •   ISOL                                   •   SKC                          •   +\n\nDZ                        •   METAR                                  •   SLP                          •   -\n\nFEW                       •   MI                                     •   SN\n\n• • • FG FRQ AUTO – automatic • • • OCNL OVC FU – smoke • • • SS TAF\n\nPROB - probability•TCU – towering\n\nobservation•FZ – freezing•RA – raincumulus\n\nBECMG - becoming          •   G – gust                               •   RVR – runway visual range    •   TEMPO – temporarily\n\nBKN – Broken (5-7         •   GR – hail (>5mm)                       •   SA – Sand                        (<1 hr per event and\n\noktas) • GS – small hail or snow pellets • SCT – scattered (3-4 oktas less than ½ total\n\nBR – Mist                 •   HZ – haze                              •   SFC - surface                    period)\n\nCB – cumulonimbus         •   ISOL - isolated                        •   SKC – Sky clear              •   TS – Thunderstorm\n\nDR – drifting             •   METAR – Meteorological                 •   SLP – sea level pressure     •   UTC – coordinated\n\nDU – dust                     Airfield Report                        •   SN – snow                        universal time\n\nDZ – drizzle              •   MI - shallow                           •   SS – sandstorm               •   VA – volcanic ash\n\nFEW – few (1-2 oktas)     •   OCNL – occasional                      •   TAF – Terminal Aerodrome     •   VC – in vicinity\n\nFG – fog                  •   OVC – overcast                             Forecast                     •   + - heavy\n\nFRQ - frequent                                                                                        •   - - light","ref":""},{"code":"5.1.2","q":"Define the ICAO standard atmosphere","a":"To provide a common reference, the International Standard Atmosphere (ISA) has been established. These standard conditions are a model which allows for the calibration of certain flight instruments and most aircraft performance data. The ISA seldom applies to actual conditions. The assumed characteristics of ISA are:\n\na.The air is dry, and its chemical composition is the same at all altitudes.\n\nb.The value of g is constant at 980.665 cm/sec2.\n\nc.At mean sea level:\n\ni.  The temperature is 15º C\n\nii. The pressure is 1013.25 hPa (29.92 inches Hg). iii. The density is 1.225 kg/m3.\n\nd.The temperature lapse rate is 1.98 ºC per 1,000 ft up to a height of the theoretical tropopause at 36,090 ft. Above this height the\n\ntemperature is assumed to remain constant at –56.5 ºC until 65,617 ft where is then rises at a rate of 0.3° C per 1,000 ft.","ref":""},{"code":"5.1.3","q":"Define Dew Point","a":"The dew point, given in degrees, is the temperature at which a sample of air becomes saturated if cooled at a constant pressure. When the temperature of the air is reduced to the dew point moisture begins to condense in the form of fog, dew, frost, clouds, rain, hail, or snow. There are four methods by which air can reach the saturation point.\n\na.When warm air moves over a cold surface, the air temperature drops and reaches the saturation point.\n\nb.The saturation point may be reached when cold air and warm air mix.\n\nc.When air cools at night through contact with cooler ground, air reaches its saturation point.\n\nd.When air is lifted or is forced upward in the atmosphere.","ref":""}]},{"code":"5.2","title":"Atmospheric Motion (Horizontal)","items":[{"code":"5.2.2","q":"Explain the formation of Thermal Winds","a":"All winds are essentially thermal winds: from sea breezes to jetstreams. When a packet for air is warmed its density reduces and it begins to rise, creating a low-pressure region. The pressure decreases more rapidly with height creating a high-pressure region at height, compared to an area of cooler air. At the surface, air moves from the cooler, higher pressure region towards the warmer, low-pressure region. At height, the air still flows from high pressure to low pressure,\n\nbut this will be in the opposite direction to the air flow at the surface. The air does not move simply from the high pressure to the low pressure. Due to Geostrophic force (caused by the rotation of the Earth), the air is deflected. The resulting wind always blows such that cold air is on the left in the northern hemisphere. In this figure this would mean that the wind was blowing into the page.\n\nIn the lower levels this can lead to local wind effects like sea breezes. However, in the situation as described, it can be seen that as the altitude increases the pressure difference between the two air masses would also increase, leading to ever strong winds. Essentially, the greater the thermal contrast between the two air masses, the greater the pressure difference between the two air masses and the greater the wind speed, leading to Jetstreams. Strong jetstreams are often associated with fronts separating two very different airmasses.","ref":"AP 3456 Volume 10 Chapter 6"}]},{"code":"5.3","title":"Atmospheric Motion (Vertical)","items":[{"code":"5.3.1","q":"Define Dry Adiabatic Lapse Rate (DALR)","a":"An adiabatic process changes the temperature of a gas within a defined system without any transfer of heat energy across the boundaries of the system. If a small mass of air is moved rapidly upwards or downwards, the change in pressure will cause a change in the temperature of the air. The rapid vertical movement of the air parcel will not allow there to be a transfer of heat by conduction, mixing or radiation, thus any temperature change will be just adiabatic. As long as the air remains unsaturated it can be shown that the displaced air changes temperature at a rate of 3° C per 1,000 ft; the Dry Adiabatic Lapse Rate (DALR).","ref":"AP3456 Volume 10 Chapter 2"},{"code":"5.3.2","q":"Define Saturated Adiabatic Lapse Rate (SALR)","a":"Water can exist in one of three forms in the atmosphere, solid, liquid and vapour. Each form can readily change to another, and during such a transformation latent heat is exchanged. Latent heat is the energy released or absorbed during a constant temperature process. The moisture content of the air is affected by its temperature where warm air can hold more than cold air. As moist (Dry) air is cooled it reaches its saturation point, where further cooling will result in the moisture condensing. If the air is cooled further,\n\nbelow its saturation point, cloud, mist or fog will form. Saturated air contains the maximum amount of water vapour that is possible at the given temperature and pressure, i.e. air in which the relative humidity is 100%. Air that is not saturated is unsaturated. When saturated air rises, adiabatic cooling occurs as with dry air, however, the cooling causes condensation and is part offset by the latent heat liberated. The rate of cooling is termed the Saturated\n\nAdiabatic Lapse Rate (SALR) and is less than the DALR. Unlike the DALR, the SALR is not constant and at low levels in temperate latitudes is about 1.5° C per 1,000 ft. In tropical warm saturated air the SALR may fall to about 1° C per 1,000 ft and may exceed 2° C per 1,000 ft in freezing air, eventually approaching the DALR.\n\nWhen saturated air falls the process is a little more complicated. Provided little or no condensed water is held in suspension, adiabatic warming causes the air to become unsaturated almost immediately and it warms at the DALR. If however, all of the condensed water were to be retained, the effect of the descent would be to gradually evaporate the droplets so that the air would remain saturated, thus the air would warm at the SALR. In practice, larger droplets tend to fall as precipitation, while the smaller droplets evaporate, so that descending cloudy air generally clears and warms at the DALR.","ref":"co                                                                     AP3456 Volume 10 Chapter 2"},{"code":"5.3.3","q":"Define Environmental Lapse Rate (ELR)","a":"In the International Standard Atmosphere (ISA) the temperature lapse rate is 1.98 ºC per 1,000 ft up to a height of the theoretical tropopause at 36,090 ft. Above this height the temperature is assumed to remain constant (isothermal) at –56.5 ºC until 65,617 ft where is then rises at a rate of 0.3° C per 1,000 ft. For practical purposes, the lapse rate which can be termed as the Environmental Lapse Rate (ELR) is assumed to be 2 ºC per 1,000 ft. However, the ELR can vary significantly from the ISA standard due to varying conditions within the atmosphere, especially in the lower troposphere and it is how the ELR changes in respect to the DALR and SALR that determines the stability of the atmosphere.","ref":"AP3456 Volume 10 Chapter 2"},{"code":"5.3.4","q":"Explain how lapse rates affect atmospheric stability","a":"Atmospheric stability is an important factor in the process of cloud formation and can help to make predictions about the weather. If air that is displaced tends to return to its original position once the displacing force is removed, the atmosphere is said to be stable. In an unstable atmosphere, displaced air tends to be further displaced\n\neven when the displacement force is removed. It can be deduced from the figures that basic adiabatic processes within the atmosphere are governed by the variable ELR. If the actual ELR for a particular day is known, then an assessment of the atmospheric\n\nstability can be made.\n\nConsider air at point A in the figure below that is lifted adiabatically. If the air is saturated it will follow the SALR line and if it is unsaturated it will follow the DALR line. If the path of the air is compared to the ELR prevailing on the day, three cases may be distinguished.\n\nco  Absolute Instability. When the ELR is greater than the DALR, i.e. when the rate of change\n\nin temperature with height is greater than 3° C per 1,000 ft, a condition of absolute instability is said to exist. If a parcel of unsaturated air at point A were forced to rise, at 1,000 ft its temperature would have fallen at the DALR to 17° C (line 1). With an ELR of 4.5° C per 1,000 ft, for example, as depicted by line 3, it can be seen that the parcel of air will be warmer than its surroundings. As a result, it will be less dense and lighter than its surroundings and so, if the displacement force were to be removed it would continue to rise. On reaching 2,000 ft, the temperature difference would be even greater, increasing the tendency to rise. In the case of saturated air in the same conditions, i.e. the ELR is greater than the SALR, the result will be the same. Absolute Stability. When the ELR is less than the SALR, i.e. when the rate of change in temperature with height is less than 1.5° C per 1,000 ft, a condition of absolute stability is said to exist. Line 5 represents an ELR of less than 1.5° C per 1,000 ft, and so rising saturated or unsaturated air will always be cooler than the surrounding air. Thus, it will be more dense and heavier so there will be a tendency for it to return to the surface.\n\nConditional Stability. Line 4 depicts the conditions where the ELR is less than the DALR but greater than the SALR. If a parcel of unsaturated air rises from point A at the DALR, at 1,000 ft its temperature will be less than the ELR (line 4) and so when the lifting force is removed it will sink back to the surface. Thus, in this case the atmosphere will be stable. On the other hand, a parcel of saturated air rising from point A at the SALR will be warmer than its surroundings at 1,000 ft and thus will tend to continue rising. In this case the atmosphere will be unstable. In this case a state of conditional stability exists. It is evident that humidity affects the stability of the atmosphere. Neutral Stability. In a neutrally stable atmosphere, a parcel of air that is disturbed tends to remain at the level to which it is displaced. This condition only occurs when the ELR equals the DALR, in the case of unsaturated air, or the ELR equals the SALR in the case of saturated air.\n\nCharacteristics of an Unstable Atmosphere. Air that is displaced vertically in an unstable atmosphere will accelerate upwards into the atmosphere generating significant vertical currents. Cloud formed will be cumuliform and may develop into cumulonimbus cloud. With strong up currents pollution at lower levels will be drawn upwards giving excellent visibility below. On warm, clear sunny days, the surface temperature can rise rapidly, increasing the ELR to create an unstable atmosphere with active cumuliform clouds. Characteristics of a Stable Atmosphere. Vertical movement of air is suppressed in a stable atmosphere even when convection is present. Cloud\n\nthat is produced will be mainly stratiform and while some cumulus cloud can form it will not be of any great vertical extent. Without any significant vertical motion of the air, pollutants will be trapped in the lower layers of the atmosphere creating hazy conditions and poor visibility.","ref":"AP3456 Volume 10 Chapter 2"},{"code":"5.3.5","q":"State trigger actions for atmospheric vertical motion","a":"The cooling of air is usually achieved by lifting and there are four trigger actions that facilitate this lifting process.\n\nTurbulence. Turbulence formation is caused by mechanical lifting which forms layers of St and Sc clouds.\n\n• • • Convection. Convection formation is caused by heating from below which forms Cu and Cb clouds. Orographic. Orographic formation is caused where air rises over hills and forms St, Cu, Cb and lenticular Ac clouds. Mass Ascent. Mass ascent formation is associated with depressions and fronts forming Cs, Ci, As, Ns and Cb clouds.","ref":"AP3456 Volume 10 Chapter 7"},{"code":"5.3.6","q":"Describe the formation and hazards of Standing (or Lee or Mountain) Waves","a":"Standing (or Lee or Mountain) Waves. When the conditions are suitable, standing waves can occur to the lee of a range of hills in addition to the disturbance over the ridge. These waves can be thought of as being oscillations about the stable state of the undisturbed air flow with the range of hills providing the initial disturbance. The conditions that favour the formation\n\nof standing waves are as follows:\n\na.Wind direction within about 30° of the perpendicular to the ridge and\n\nlittle change in direction with height.\n\nb.Wind speeds increasing with height, and greater than 15 kts at the\n\ncrest.\n\nc.Markedly stable air (such as a temperature inversion) above the crest\n\nof the hills with less stable air above and below the stable layer. Vertical Currents, Wavelength and Amplitude of Standing Waves. The\n\nfollowing sub-paragraphs give an introduction of the magnitude of these phenomena:\n\na.Vertical Currents. Vertical currents can be quite extensive and\n\nvigorous and speeds of 2000 ft/min (20 kts) have been encountered in the British Isles. They can make it difficult to keep the aircraft at a constant altitude and can also cause significant fluctuations in airspeed. Vertical speeds in excess of 50 kts (5000 ft/min) have been recorded elsewhere in the world.\n\nb.Wavelength. The wavelength is normally only a few miles but can be as much as 30 miles. Generally, light winds and stable conditions\n\nproduce a short wavelength whereas strong winds and less stable conditions produce long wavelengths.\n\nc.Amplitude. The amplitude of a standing wave depends on the size and shape of the high ground. In general, the higher the mountain\n\nrange the greater the amplitude. Turbulence, Cloud and Icing Associated with Standing Waves.\n\na.Turbulence. The friction layer is more variable in depth in mountainous regions than it is over flat terrain, and eddies often form in this\n\nlayer causing severe turbulence. A combination of strong vertical currents and friction may produce rotor zones which also cause severe turbulence. In addition, large fluctuations in surface wind speeds occur, especially below the downdraughts of waves. At higher levels the flow is usually much smoother, but turbulence can occur when waves are breaking up.\n\nb.Clouds. If the air is sufficiently moist, a lens-shaped cloud (lenticularis) frequently forms in the crest of a wave and clouds sometimes occur\n\nin the rotor zone itself. These latter clouds are called roll clouds. Although clouds are visible indications of the presence of standing waves, it must be remembered that waves often occur without cloud formation.\n\nc.Icing. Icing will be discussed more fully in Chapter 11, and it is sufficient to say at this stage that severe icing can be encountered in wave\n\ncloud.","ref":"AP3456 Volume 10 Chapter 8"}]},{"code":"5.4","title":"Visibility","items":[{"code":"5.4.1","q":"Define Met Visibility","a":"Met visibility is defined as the greatest horizontal distance at which known objects can be seen and recognised by an observer on the ground with\n\nnormal eyesight and under conditions of normal daylight illumination. However, reported met visibility may now include a prevailing visibility. Traditionally the lowest observable visibility in any direction was reported as the met visibility and was publish on a METAR. This effectively gave you a worst-case scenario. Prevailing Visibility measurements allow airfields to report the dominant visibility as the value for the airfield. The prevailing visibility is the greatest visibility which is reached or exceeded within at\n\nleast half the horizontal circle or within at least half of the surface of the aerodrome. There are certain circumstances when a lower visibility will be reported alongside the prevailing visibility. These are:\n\nWhen the visibility in the worst direction is 1500m or less\n\nWhen the visibility in the worst direction is less than 50% of the prevailing visibility.\n\nSay the prevailing visibility was 6000m but a fog bank existed to the SE causing the visibility to be reduced to 500m, then is would be reported as, 6000 0500SE. Pilots should bear in mind that the METAR visibility may not be the visibility a pilot experiences on approach – in fact it could be up to 50% worse. This reporting method will naturally lead to a significant difference in the reporting of colour states for civilian airfields and should be kept in mind when choosing diversions.","ref":"AP3456 Volume 10 Chapter 13"},{"code":"5.4.2","q":"Define RVR","a":"RVR is the maximum distance in the direction of take-off or landing at which the runway, or special lights delineating the runway, can be seen from a height corresponding to the average eye-level of the pilot at touchdown. The RVR is measured by an observer (or automatically) from a 15ft high tower near to the runway, corresponding to the average eye level of the pilot at touchdown.","ref":"AP3456 Volume 10 Chapter 13"}]},{"code":"5.5","title":"Clouds and Precipitation","items":[{"code":"5.5.1","q":"Describe the following High Altitude cloud types (appearance, altitude, characteristics, precipitation):","a":"•Cirrus (Ci)\n\n•Cirrostratus (Cs)\n\nCirrocumulus (Cc)                                                                         AP 3456 Volume 10 Chapter 8\n\nCloud Height Appearance Trigger Content Threat Symbol Band\n\nCirrus (Ci) 16500ft - Mass Ice crystals No threat of turbulence\n\n45000ft  ascent  or aircraft icing\n\nCirrostratus (Cs) 16500ft – Mass Ice crystals No threat of turbulence\n\n45000ft  ascent  or aircraft icing\n\nCirrocumulus (Cc) 16500ft – 45000ft\n\nco  Turbulence  Ice crystals  No threat of turbulence\n\nor aircraft icing","ref":""},{"code":"5.5.2","q":"Describe the following Medium Altitude cloud types (appearance, altitude, characteristics, precipitation):","a":"•  Altostratus (As)\n\nAltocumulus (Ac)                                                                            AP3456 Volume 10 Chapter 8\n\nCloud Height Band Appearance Trigger Content Threat Symbol\n\nAltostratus (As) 6500ft - Mass ascent Supercooled water Light icing\n\n23000ft  droplets\n\nNil or Light turbulence Light Rain or snow\n\nAltocumulus 6500ft – Turbulence Supercooled water Light/Mod icing (Ac) 23000ft droplets\n\nConvection  Light/Mod turbulence\n\nOrographic  Nil or rain and snow","ref":""},{"code":"5.5.3","q":"Describe the following Low Altitude cloud types (appearance, altitude, characteristics, precipitation): • • • Stratus (St) Stratocumulus (SC) Nimbostratus (Ns)","a":"Cloud Height Band Appearance Trigger Content Threat Symbol Stratus (St) Surface – Convection Water drops/droplets Light icing during\n\n6500ft  with turbulence  prolonged flight\n\nSupercooled Water\n\nOrographic  droplets above  Nil turbulence\n\nfreezing level Nil or drizzle\n\nStratocumulus Surface – Turbulence Water droplets Light or mod icing (Sc) 6500ft\n\nOrographic  Light turbulence\n\nNil or Light rain, drizzle or snow flurries\n\nNimbostratus Surface – Mass Ascent Water drops/droplets Mod to Sev icing (Ns) 6500ft Mod turbulence\n\nSupercooled Water  Periods of rain or\n\nsnow droplets above freezing level","ref":"co                                                                 AP3456 Volume 10 Chapter 8"},{"code":"5.5.4","q":"Describe the following Heap cloud types (appearance, altitude, characteristics, precipitation):","a":"•  Cumulus (Cu)\n\nCumulonimbus (Cb)                                                                               AP3456 Volume 10 Chapter 8\n\nCloud Height Band Appearance Trigger Content Threat Symbol\n\nCumulus (Cu) Tropopause to low level\n\nco  Turbulence  Water drops\n\nIce crystals Mod/sev icing Mod/sev turbulence Light/heavy showers of rain or snow\n\nCumulonimbus Tropopause Mod to strong Water droplets Sev icing (Cb) to low level convection\n\nSupercooled water  Sev turbulence\n\ndroplets Heavy showers of\n\nMass ascentIce crystalsrain or snow\n\nHailStrong up/downdrafts\n\nOrographic","ref":""}]},{"code":"5.6","title":"Icing","items":[{"code":"5.6.1","q":"Describe the hazards of icing icing","a":"The effects of ice deposits on aircraft may be summarized as follows:\n\na.Aerodynamic. Aerodynamic forces will be changed by the disturbed airflow caused by ice deposits. Drag is increased and lift is reduced.\n\nb.Weight. Weight is increased and the centre of gravity may be displaced.\n\nc.Vibration. Vibration on moving parts, particularly on propellers and helicopter rotors, can be caused by unequal ice deposits.\n\nd.Controls. Control surfaces may become jammed, or their movement may become stiff and erratic.\n\ne.Pressure Instruments. Pressure instrument readings will be incorrect if the pitot or static vents are blocked by ice.\n\nf.Communications. Communications are degraded if the aerials become ice-covered.\n\ng.Vision. Vision through canopies covered in ice is impaired.\n\nh.Undercarriage. Undercarriage retraction/lowering may be hindered.\n\ni.Engine. Engine air intakes may be blocked or restricted, and fuel vapour and air flow hindered.","ref":"AP3456 Volume 10 Chapter 11"},{"code":"5.6.2","q":"Explain what is meant by Light, Moderate and Severe Icing","a":"Generally icing is rated as either light, medium or severe. Light Icing - The rate of ice accumulation that may create a problem if the flight is prolonged in this environment (over one hour). Occasional use of de-icing equipment removes/prevents accumulation. It does not present a problem if de-icing/anti-icing equipment is used. Moderate Icing - The rate of ice accumulation on an aircraft is such that even short encounters becomes potentially hazardous and the use of de- icing/anti-icing equipment or a diversion is necessary. Severe Icing - The rate of ice accumulation on an aircraft is such that de-icing/anti-icing equipment fails to reduce or control the hazard. Immediate diversion is necessary.","ref":""},{"code":"5.6.3","q":"Describe the factors affecting the accumulation of airframe icing","a":"Freezing of Supercooled Water Droplets. The most important factor for the build-up of ice on aircraft is the freezing of supercooled drops - either cloud particles or raindrops - following impact with a cold aircraft. A certain amount of heat is required to melt a given mass of ice without a change in temperature and the same amount of heat is liberated when freezing takes place. This is known as the latent heat of fusion and its value is approximately 80 calories per gram of water or ice. Only 1/80th of a drop can freeze for every degree Celsius by which the temperature is below 0 ºC. Once the temperature of the partly frozen drop is raised, it begins to lose heat by evaporation and conduction to the object in contact with it, so that the remainder of the drop freezes more gradually while assuming the temperature of its surroundings. The higher the temperature of the supercooled drop, the smaller the fraction which will freeze instantly, and the greater the amount of liquid which will freeze progressively.\n\nTemperature of the Free Air. Spontaneous freezing of supercooled drops in the free atmosphere is determined partly by the temperature and size of the drop and partly by other factors. As the temperature falls, the larger drops are likely to freeze first, while at lower temperatures only the smallest drops will remain liquid until a temperature of minus 40 ºC. The higher the temperature of a supercooled drop, the greater the fraction of the drop which remains liquid. The liquid portion then starts to flow over the aircraft thus favouring the formation of clear ice. At lower temperatures, there is a tendency towards the formation of rime ice concentrated near the leading edges. Size of Supercooled Drops. The smallest supercooled drops tend to freeze immediately on striking a cold aircraft; the latent heat of fusion is quickly removed by the airflow and there is little or no spreading of the drop before freezing is complete. At the same time, air is enclosed between the particles, so that accretion takes the form of rime concentrated near the leading edge. On the other hand, large drops are accompanied by\n\nspreading of water over the airframe while the latent heat is being dissipated, so that freezing takes place more slowly and tends to be in the form of clear ice. Drops of moderate size can produce results intermediate between these two. Severity of Ice Accretion. The severity of icing is defined as the rate of accumulation of ice by weight per unit area per unit time. Among the meteorological factors determining this rate are the amount of liquid water present and the size of the droplets. These characteristics are not the\n\nsame throughout a particular cloud, even at one level. A cloud containing both liquid water and ice crystals may have large patches where one or the other predominate and icing will tend to be severe when the temperature is not far below 0 °C. An analysis of reports on ice accretion shows a preponderance of occasions at temperatures above about minus 10 °C and indicates that the frequency diminishes rapidly when the temperature falls below minus 20 °C, although occasional icing has been reported at temperatures below minus 40 °C.\n\nThe severity of ice accretion is also dependent on:\n\nAircraft speed. An aircraft will pick up more icing when travelling faster.\n\nWing shape. A thin, fast-jet type wing will pick up icing quicker than a thick, high-lift wing shape.\n\nSupercooled Rain. Supercooled rain occurs beneath warm fronts and occlusions and occasionally beneath cold fronts. When present, there is necessarily a warmer layer above, in which the temperature exceeds 0 °C. When flying beneath this type of meteorological condition the best procedure is to climb into the warmer layer of air. The belt of frontal\n\ncloud and rain should if possible be crossed at right angles so as to give the shortest traverse through the icing region. A particularly dangerous procedure is to fly parallel to the front in the freezing rain since a heavy accumulation of clear ice could form rapidly.","ref":"AP3456 Volume 10 Chapter 10"}]},{"code":"5.7","title":"Thunderstorms","items":[{"code":"5.7.1","q":"State the conditions necessary for the formation of thunderstorms","a":"There are three conditions necessary for a thunderstorm to develop.\n\na.Instability. Instability must be present so that once the air begins to rise it will continue to rise (e.g. a steep lapse rate with warm air in\n\nlower layers of the atmosphere and cold air in the upper layers).\n\nb.High Humidity. There must be abundant humidity over a considerable depth in the atmosphere such that unsaturated air cools through\n\nlifting sufficiently to cause condensation. Latent heat is released which increases instability.\n\nc.Trigger Action. There must be a trigger action or lifting mechanism to start the air rising. The trigger may be a cold front forcing air aloft,\n\norographic ascent and convective heating from the surface.","ref":"AP3456 Volume 10 Chapter 8"},{"code":"5.7.2","q":"Describe the indications and hazards of thunderstorms","a":"Hazards Associated with Thunderstorms Thunderstorms present several different weather hazards with respect to aviation which occur individually or in combination. Many of the hazards associated with thunderstorms can be encountered outside of the cloud itself, therefore, light aircraft in particular should avoid the storm by at least 10 nm horizontally and 5,000 ft vertically.\n\nSquall Line. A squall line is a narrow band of active thunderstorms which often develop on or ahead of a cold front in moist, unstable air, but may develop in unstable air far removed from any front. The line may be extensive making a detour around it difficult and the severe weather may make it too hazardous to penetrate. The squall often contains steady-state thunderstorms and presents the single most intense weather hazard to aircraft. The Squall Line usually forms rapidly, generally reaching maximum intensity during the late afternoon and the first few hours of darkness. Turbulence. Potentially hazardous turbulence is present in all thunderstorms and a severe thunderstorm can severely damage an aircraft, even to destruction. The strongest turbulence within the cloud is associated with the shear forces between updraft and downdraft boundaries. Outside the cloud, shear turbulence may be encountered several thousand feet above and 20 miles laterally from a severe storm. A low-level turbulent area is the shear zone associated with the gust front. Often, a “roll cloud” on the leading edge of a storm marks the top of the eddies in this shear\n\nand it signifies an extremely turbulent zone. Gust fronts often move far ahead (up to 15 miles) of associated precipitation. The gust front causes a rapid and sometimes drastic change in surface wind ahead of an approaching storm. Microbursts. A significant hazard associated with thunderstorms is the microburst. These are created when strong cold downdraughts under the cloud spread out as they reach the surface. Microbursts can be extremely dangerous to aviation because the sink rate of the air can exceed the\n\nclimb performance of an aircraft, thus forcing the aircraft into the ground. The presence of virga (precipitation that is falling but not reaching the ground) is a good visual indication of microburst activity. Icing. Strong updrafts in a thunderstorm are capable of supporting abundant liquid water with relatively large droplet sizes. When carried above the freezing level, the water becomes super cooled and when the temperature in the upward current cools to about –15 °C, much of the remaining\n\nwater vapour sublimates as ice crystals. Above this level, at lower temperatures, the amount of super cooled water decreases. Super cooled water freezes on impact with an aircraft. Clear icing can occur at any altitude above the freezing level, but at high levels, icing from smaller droplets may be rime or mixed rime and clear ice. The abundance of large, super cooled water droplets within thunderstorms causes the rapid accretion of clear ice between 0 °C and –15 °C. Hail. Hail perhaps presents as great a hazard to aircraft as the turbulence associated with a thunderstorm. Super cooled raindrops above the freezing level begin to freeze. Once a raindrop has frozen, forming a hailstone, other drops can freeze to it, significantly increasing its size. Large hailstones can be present within severe thunderstorms which have a large vertical extent coupled with strong updrafts. Eventually, the hailstones fall, possibly some distance from the storm core and may be encountered in clear air several miles from thunderstorm clouds. As hailstones fall through air whose temperature is above 0 °C, they begin to melt, and precipitation may reach the ground as either hail or the rain. Rain at the surface does not mean the absence of hail aloft. Hail should be anticipated with any thunderstorm, especially beneath the anvil of a large cumulonimbus. Ceiling and Visibility. Generally, visibility is close to zero within a thunderstorm cloud and may be reduced in precipitation and dust between the cloud base and the ground. The hazards to aviation presented by low visibility are multiplied when associated with the other thunderstorm hazards of turbulence, hail, and lightning. Lightning. Lightning can damage the structure of an aircraft along with communication, electronic and navigation equipment. Composite material is especially vulnerable unless it is protected. Magnetic compasses in particular are vulnerable to lightning discharges which can also disrupt radio communications on low and medium frequencies. Although lightning intensity and frequency have no simple relationship to other storm parameters, severe storms, as a rule, have a high frequency of lightning. Lightning is most likely to be present within 5,000 ft of the freezing level within cloud that has a temperature of between -10° C and +20° C.\n\nEffect on Altimeters. Pressure usually falls rapidly with the approach of a thunderstorm, rises sharply with the onset of the first gust and arrival of the cold downdraft and heavy rain showers, and then falls back to normal as the storm moves on. This cycle of pressure change may occur over 15 minutes and can lead to significant errors in indicated altitude; possibly up to 1,000 ft. If a pilot ‘chases’ the altimeter to maintain level flight, there is a danger of overstressing the airframe. It is more important to maintain the aircraft attitude rather than altitude within a storm.","ref":"AP3456 Volume 10 Chapter 8"},{"code":"5.7.3","q":"State the thunderstorm avoidance criteria","a":"The aircraft is to remain at least 3 nm horizontally and 5000 ft vertically outside of unstable or cumulonimbus clouds when weather radar returns are coloured yellow/amber/red/purple. To avoid a large thunderstorm, make decisions when the aircraft is at least 40 NM away from the thunderstorm.\n\nAvoid:\n\nAll yellow, red, or magenta areas by at least 20 NM.\n\nNote: Closely spaced, or thin lines, between colour gradations usually indicate severe turbulence.\n\nSingle magenta areas of turbulence that are not associated with heavy precipitation, by at least 5 NM.\n\nPenetrating a cell.\n\nClearing its top by less than 5 000 ft vertically, because turbulence may occur at the top of the clouds.\n\nOverflying a cell if its top is at or above 25 000 ft, because turbulence may be stronger than expected.\n\nFlying under a thunderstorm, because of possible windshear, microbursts, severe turbulence, or hail.\n\nIf any doubt, perform lateral deviation, instead of vertical deviation. FCOM PRO-SUP-91-30: Weather Radar Active thunderstorms should be avoided by as wide a margin as is practicable. Where possible, thunderstorms should be avoided laterally by at least 10 NM below FL 200 and 20 NM above FL 200; avoid thunderstorms to the upwind side if able to do so. Overflight of a thunderstorm and Cumulonimbus clouds should be avoided laterally where possible and flight underneath should not be attempted. If overflight of a thunderstorm is unavoidable, a vertical clearance of at least 5000 ft should be maintained. OM Part A 8.3.20.3","ref":""},{"code":"5.7.4","q":"Decode a 6-figure turbulence group","a":"A TAF may include a 6-figure turbulence group e.g. 520002 5 - Turbulence group indicator. 2 - Degree of turbulence on the scale 0-9 as follows:\n\n0 = Nil\n\n1 = Light\n\n2 = Moderate, clear air, occasional\n\n3 = Moderate, clear air, frequent\n\n4 = Moderate, in cloud, occasional\n\n5 = Moderate, in cloud, frequent\n\n6 = Severe, clear air, occasional\n\n7 = Severe, clear air, frequent\n\n8 = Severe, in cloud, occasional\n\n9 = Severe, in cloud, frequent.\n\n000 -Base of the turbulence in hundreds of feet.\n\n2 - Thickness of the turbulent layer in thousands of feet. The example means: Moderate occasional clear air turbulence from the surface to 2000 feet.","ref":"AP3456 Volume 10 Chapter 9"}]},{"code":"5.8","title":"Air Masses","items":[{"code":"5.8.1","q":"Describe the general features of a cold front","a":"General Conditions of a Cold Front. A cold front occurs when a mass of cold, dense, and stable air advances and replaces a body of warmer air. Cold fronts move more rapidly than warm fronts, progressing at a rate of 25 to 30 mph. However, extreme cold fronts have been recorded moving at speeds of up to 60 mph. A typical cold front moves in a manner opposite that of a warm front. The air is denser and so it stays close to the ground and slides under the warmer air forcing it to rise. The rapidly ascending air causes the temperature to decrease suddenly, forcing the creation of clouds. The type of clouds that form depends on the stability of the warmer air mass. A cold front in the Northern Hemisphere is normally oriented in a northeast to southwest manner and can be several hundred miles long. Conditions of an Approaching Cold Front. Prior to the passage of a typical cold front, cirriform or towering cumulus clouds are present, and cumulonimbus clouds are possible. Rain showers and haze are possible due to the rapid development of clouds. A high dew point and falling barometric pressure are indicative of imminent cold front passage. Conditions in a Passing Cold Front. As the cold front passes, towering cumulus or cumulonimbus clouds are present. Depending on the intensity of the cold front, heavy rain showers form and might be accompanied by lightning, thunder, and/or hail. During cold front passage, the visibility is poor, with winds variable and gusty, and the temperature and dew point drop rapidly. A quickly falling barometric pressure steadies during frontal\n\npassage and then begins a gradual increase. An aircraft flying through a front which is moving in the opposite direction will experience the wind veering. Conversely, if the aircraft is moving in the same direction as the front, the wind will back. Conditions When the Cold Front has Passed. After the frontal passage, the towering cumulus and cumulonimbus clouds begin to dissipate to cumulus clouds with a corresponding decrease in precipitation. Good visibility eventually prevails, temperatures remain cooler, and the barometric pressure continues to rise.","ref":"AP3456 Volume 10 Chapter 10"},{"code":"5.8.2","q":"Describe the general feature of a warm front","a":"General Conditions of a Warm Front. A warm front occurs where a warm mass of air advances and replaces a body of colder air. Warm fronts move slowly, typically 10 to 25 mph.\n\nThe slope of the advancing front moves up and over the top of the cooler air and gradually pushes it out of the area. Warm fronts contain warm air that often has very high humidity. As the warm air is lifted, the temperature drops,\n\nand condensation occurs. Conditions of an Approaching Warm Front. As a warm front approaches, cirriform or stratiform clouds, along with fog, can form along the frontal boundary. In summer, Cbs are likely to develop. Light to moderate precipitation is probable, usually in the form of rain, sleet, snow, or drizzle, with poor visibility. The outside temperature is cool or cold, with an increasing dew point. The barometric pressure falls until the front passes completely. Conditions in a Passing Warm Front. During the passage of a warm front, stratiform clouds are visible and drizzle may be falling. The visibility is generally poor but improves with variable winds. The temperature rises steadily. For the most part, the dew point remains steady and the barometric pressure stabilizes. An aircraft flying through a front which is moving in the opposite direction will experience the wind veering. Conversely, if the aircraft is moving in the same direction as the front, the wind will back. Conditions When the Warm Front has Passed. After the passage of a warm front, stratocumulus clouds predominate, and rain showers are possible. The visibility eventually improves, but hazy conditions may exist for a short period after passage. The temperature rises, and the dew point rises and then levels off. There is generally a slight rise in barometric pressure, followed by a decrease.","ref":"AP3456 Volume 10 Chapter 10"},{"code":"5.8.3","q":"Identify likely areas of CAT","a":"There are two types of CAT: mechanical, caused by disturbances to the smooth horizontal flow of air, and thermal, due to vertical currents caused by instability. CAT may be encountered therefore, anywhere that conditions exist that cause a rapid change in direction (vertical or horizontal) or speed of airflow. Common causes of CAT are:\n\nJet streams. Jet streams are often associated with considerable windshear, both vertical and horizontal, and these produce CAT.\n\nThe severity of the CAT increases with the magnitude of the shear and is strongest on the cold side of the jet. Not all jets produce Cat, however\n\nHigh ground. High ground naturally disturbs the air flowing over it. The effect can be felt at altitudes well above the tops of the\n\nmountains and hills and even to jet stream levels\n\nRapidly changing contour gradient. Rapid changes in contour gradient means considerable change in wind speed over a short\n\ndistance; this horizontal wind shear can produce CAT\n\nSharply Curved Contours. Sharply curved contours result in large changes in wind direction over a short distance and can result in\n\nCAT\n\nCumulonimbus Complexes. Atmospheric instability often results in strong vertical currents and these are usually at a peak near\n\ncumulonimbus clouds. Significant CAT can exist to above 20nm horizontally from and about 5000ft above the top of a cumulonimbus cloud.","ref":"AP3456 Volume 10 Chapter 19"},{"code":"5.8.4","q":"Describe the ITCZ and its impact on aviation","a":"The ITCZ forms a belt around the equator, where the Trade Winds of the northern and southern hemispheres converge. The convergence zone follows the 'thermal' equator, or 'zone of maximum heating', and shifts north and south of the geographic equator in line with the seasons. However, the ITCZ does not lie uniformly around the globe like a line of latitude because of the differential heating of land and sea. This gives the ITCZ a distinct wave- like formation. Air converging into the ITCZ ascends, and being warm and usually moist, rises producing cumulus and cumulonimbus cloud which can give heavy showers and thunderstorms. The activity of the ITCZ is very variable and depends on such features as the time of day, the location, and whether the air converging is of Maritime (and therefore moist) or Continental (and therefore dry) origin. In active zones the cumulonimbus tops can reach 55,000 - 65,000 ft, with extensive sheets of altostratus and cirrostratus producing significant rain over an extensive area.\n\nThe width of the ITCZ varies from as little as 20-30 miles up to about 300 miles, and at times may disappear altogether from certain localities. Flying Weather in the Oceanic ITCZ. Flying conditions vary considerably, depending on the activity of the ITCZ. If active, typical conditions will include frequent rainstorms with thunder, violent turbulence and squally low-level winds. Above about 15,000 ft, the height of the freezing level, there are often extensive cloud layers with embedded cumulus and cumulonimbus giving severe icing to considerable heights, but below 15,000 ft there may be good clear lanes. Visibility is good, except in heavy rain when the effective visibility from an aircraft may be practically nil. Cloud bases are usually 1,000 ft or more, except in heavy rain when they will be much lower. The squally surface winds are likely to gust to 25 kts, and occasionally up to gale force. The maximum activity occurs late in the night or early morning when, in the absence of the sun, cumulonimbus clouds can achieve their full development, free from evaporation of the cloud tops. It goes without saying that flying in cloud through the ITCZ\n\nshould be avoided as far as possible. If convergence is slight and the ITCZ is inactive, broken cumulus and scattered showers may be expected, with light winds over a wide area. Flying Weather in the ITCZ over Land. When the ITCZ moves well away from the equator over land, the track of the air associated with it becomes considerably modified due to the formation of heat lows. Indeed, the air masses themselves are modified, resulting in greater temperature\n\nand moisture contrasts, and being further away from the equator, there is more rotational deflection due to the Coriolis Force. The ITCZ also marks the limit of the monsoon penetration. Continental air on one side of the zone is warmer in the lower levels than the Maritime air on the other side, but above 10,000 ft the Maritime air will be warmer than the Continental. The result is the Continental air overlies the Maritime air in the lower layers, but above 10,000 ft the position is reversed. The contrasts between the two air masses is greatest near the coasts, but the greatest activity\n\nis not at the surface boundary between the two air masses, but further south, where the monsoon air is not trapped below the Continental air. Inland, in the northern hemisphere, the high land temperatures tend to break down the lower part of the frontal surface. Local heating makes the Monsoon air unstable so that it rises and mixes with the overlying Continental air, resulting in local showers and thunderstorms. Orographic lifting may also modify the structure considerably.","ref":"co                                                                       AP3456 Volume 10 Chapter 21"}]},{"code":"5.9","title":"Interpretation of Meteorological Information","items":[{"code":"5.9.1","q":"Decode METAR information","a":"Candidates should be able to decode METAR information to the satisfaction of the examiner. Met Office METAR Decode","ref":""},{"code":"5.9.2","q":"Decode TAF information","a":"Candidates should be able to decode TAF information to the satisfaction of the examiner. Met Office TAF Decode","ref":""},{"code":"5.9.3","q":"Explain the following meteorological chart symbology","a":"Candidates should be able to explain meteorological chart symbology to the satisfaction of the examiner, including contour charts, synoptic charts, sig weather charts, high altitude charts. MetLink - Royal Meteorological Society Weather Symbols and Synoptic Charts - SIGWX interpretation Guide Draft V1 0 (metoffice.gov.uk)","ref":""}]}]},{"num":"6","name":"Performance","sections":[{"code":"6.1","title":"Definitions","items":[{"code":"6.1.1","q":"Define the following terms","a":"Distances Speeds Other\n\nTORA                                           • VGO                                             • COF\n\nStopway                                        • VROT                                            • RCR\n\nASDA                                           • VMCG                                            • RSC\n\nClearway                                       • VMCO\n\nTODA                                           • VMCA\n\nLineup penalty                                 • VR\n\nCFL                                            • VBMAX\n\nLanding Distance                               • VBO\n\nVBO Landing Distance   • V1\n\nDistances\n\nTake-Off Run Available (TORA). TORA is the length of runway which is declared by the State to be available and suitable for the ground run of an aeroplane taking off. This, in most cases, corresponds to the physical length of the runway pavement. Stopway. A defined rectangular area on the ground, at the end of a runway, in the direction of take-off, designated and prepared by the Competent Authority as a suitable area in which an aeroplane can be stopped in the case of an interrupted take-off (ICAO). The width is the same as the runway. Accelerate Stop Distance Available (ASDA). ASDA is the length of the take-off run available plus the length of stopway available (if stopway is provided) Clearway. Clearway is a defined rectangular area, 300 ft or 90 metres either side of the centreline, on the ground or water at the end of the runway, in the direction of take-off and under control of the Competent Authority, selected or prepared as a suitable area over which an aeroplane may make a portion of its initial climb to a specified height.\n\nTake-Off Distance Available (TODA). TODA is the length of the take-off run available plus the length of the clearway available (if clearway is provided) (ICAO). TODA is not to exceed 1.5 ´ TORA.\n\nLineup Distance Penalty. A lineup distance penalty must be applied anytime the takeoff is not commenced from the beginning of the usable runway. Apply a standard distance of 250 feet to account for turning the aircraft around on the runway or accessing the runway from a taxiway. In addition to any lineup distance penalties, apply a penalty of 100 ft for a rolling or a standing takeoff to account for the runway used during the acceleration of the engines to takeoff setting. CFL. Critical field length is the total length of runway required to accelerate with all engines operating to engine failure speed, experience a critical engine failure, then continue to takeoff or stop. Critical field length is calculated assuming 1.5 seconds of continued acceleration after engine failure to recognize the engine failure and decide to stop. Once the decision to stop has been made, additional time delays are included to reconfigure the aircraft for stopping. A distance penalty equal to 2 seconds at decision speed is included for conservatism prior to considering the activation of deceleration devices. Thrust reduction is assumed to occur at the decision point, followed by a flight test derived transition segment during which the engines spool down, and brakes, spoilers, and reversers become fully effective. Idle reverse thrust on three engines operating is the baseline condition, with corrections for forward idle or symmetric maximum reverse thrust.\n\nPart 6 – Performance\n\nVR (Based on Runway available)\n\nIs higher than\n\nV1 (Based on critical field length)\n\nVmcg < Vr Vrot > Vr Vgo = Vr\n\nWith an engine failure at a speed les than or equal to VGO, the aircraft will always be airborne within the CFL. This is a direct result of the fact that V1 ≤ VGO in any permissible takeoff case. Conversely, the aircraft will not always stop within the CFL in the case of a reject at some speeds <VGO (i.e. when VGO > V1 and the reject occurs at a speed > V1). Landing Distance. Landing distance is the total distance from a 50 foot height to a point where the aircraft can be brought to a full stop. VBO Landing Distance. As above but calculated assuming braking is delayed until reaching V BO.\n\nSpeeds\n\nGo Speed (VGO). VGO is the speed at which the pilot normally becomes committed to continue the takeoff. Go speed is the lowest of rotation speed (VROT) refusal Speed (VR) or maximum brake energy speed (VBMAX)\n\nIf VGO is VR then VR must be greater than or equal to VMCG\n\nIf VGO is VBMAX then VBMAX must be greater than or equal to VMCG and VR\n\nIf VGO is VROT an increase in VROT due to a wind gust increases VGO an equal amount, not to exceed VR or VBMAX\n\nRotation Speed (VROT). VROT is the speed at which rotation from the three-point attitude to the takeoff attitude is initiated by applying back pressure to the control stick\n\nGround Minimum Control Speed (VMCG). VMCG is the minimum speed during the takeoff run at which the aircraft’s engine most critical to the directional control can fail with the remaining engines operating at selected thrust and still maintain directional control. Additionally, a deviation of no more than 28 feet from the ground path originally intended can result, using the elevator, aileron, spoiler, rudder controls, nosewheel steering on a dry hard surface runway with a 1 second pilot reaction time. Minimum Climbout Speed (VMCO). VMCO is the minimum climbout speed recommended for the three-engine obstacle clearance.\n\nAir Minimum Control Speed (VMCA). VMCA is the minimum air speed at which a straight flight path can be maintained with the engine most critical to lateral or directional control failed and with the remaining engines operating at Max thrust. A straight flight shall be maintained with maximum rudder deflection and no more than 5 degrees of bank away from the dead engine.\n\nRefusal Speed (VR). VR is the maximum speed to which the aircraft can accelerate and then stop in the available runway Maximum Brake Energy Speed (VBMAX). VBMAX is the highest speed from which the aircraft can be brought to a stop without exceeding the maximum design energy absorption capability of the brakes. Maximum Brakes-on Speed (VBO) – VBO is the highest speed at which maximum effort braking may be initiated without melting the fuse plugs. Critical Engine Failure Recognition Speed (V1) – Engine failure recognition speed is reached 1.5 seconds after the most critical engine failure which gives the same distance to either continue the takeoff or stop. Other COF. Climbout factor for three or four engines is a nondimensional parameter used to assess climb gradient. It represents the climb gradient capability, in percent, available at VMCO with landing gear retracted, out of ground effect, with flaps and slats set for takeoff. At the gear-up point, the climbout factor and the climb gradient capability are the same. At all other points on the flight path, the climb gradient capability is less than the corresponding climbout factor. Three engine climbout factor is calculated at VMCO. RCR. The Runway Condition Reading is a measure of the coefficient of friction between the tires and the runway surface. A dry, hard surface runway is assigned an RCR value of 23. RCR values less than 23 indicate that stopping performance is degraded.\n\nRSC. The Runway Surface Condition is the average runway surface covering given in depth and type. With RSC, the distance required to accelerate increases due to the additional drag related to the runway surface covering. The distance required to stop increases due to the reduced coefficient of friction between the tires and the runway. 6.2\n\nMC","ref":""},{"code":"6.2.1","q":"Explain all MC TOLD data fields","a":"Candidates should be able to explain to the satisfaction of the examiner the MC data fields.","ref":""},{"code":"6.2.2","q":"Explain TR assumptions for IDLE, INOP, MAX","a":"IDLE: One engine inoperative, 3 engines in reverse idle. INOP: One engine inoperative, 3 engines forward idle. MAX: One engine inoperative, 1 engine reverse idle, 2 symmetrical engines max reverse.","ref":""},{"code":"6.2.3","q":"Describe the 3-eng acceleration altitude hierarchy","a":"The MC uses the selected takeoff thrust to compute ACC ALT, including when evaluating three engine climb gradients. Whenever MAX thrust is used to calculate ACC ALT, thrust is decreased to INT according to the Maximum Thrust Envelope. The MC computes ACC ALT as the lowest of the following parameters which allow all climb gradient and obstacle requirements to be satisfied:\n\n1. 1000 Feet AFE. 2. The highest obstacle or three engine climb gradient requirement, when requirement height is between 1000 ft AFE and 2000 ft AFE. 3. 2000 feet AFE. 4. The highest obstacle or three engine climb gradient requirement, when requirement height is between 2000 feet AFE and item 5 below. 5. The highest altitude where VMSR can be attained at or before 10 minutes has elapsed. 6. If the highest obstacle or three engine climb gradient altitude cannot be satisfied by item 5 above then ACC ALT is set by the MC at the highest obstacle or three engine climb gradient altitude.","ref":""}]},{"code":"6.3","title":"1CL-1","items":[{"code":"6.3.1","q":"Describe the height AFE restrictions for a standard/ noise abatement departure","a":"The data in the COF tables provides the required Minimum Climbout Factor (COF) values to ensure that a Standard Departure Profile can satisfy a given Required Climb Gradient to 8,000 ft. AFE (Noise Abatement to 3,000 ft. AFE).","ref":""},{"code":"6.3.2","q":"Describe COF correction for a standard/ noise abatement departure with a tailwind","a":"Increase Required Climb Gradient by 4 ft/nm for each knot of tailwind (In the table only, not in the MC).","ref":""},{"code":"6.3.3","q":"Describe type II/IV anti-icing fluid penalties","a":"Students should demonstrate use of the table.","ref":""},{"code":"6.3.4","q":"Describe the TOLD adjustments required to fly 3/4 flap precision approaches with glide path angles steeper than 3.2 degrees","a":"3/4 flap precision approaches: For glide path angles steeper than 3.2 degrees, increase landing distance by 300 ft. This can be accomplished in the MC by reducing runway available by 300 ft. Use reference ground speed to check maximum 3/4 flap glide path capability using Maximum Allowable Glide Path with 3/4 Flaps table.","ref":""},{"code":"6.3.5","q":"Describe the TOLD adjustments required to fly full flap precision approaches (non-assault) with pilot entered glide path angles","a":"Full flap precision approaches (non-assault): For pilot entered glide path angles between 3.8 degrees and the MC calculated full flap approach angle, increase landing distance by 600 ft. This can be accomplished in the MC by reducing runway available by 600 ft.","ref":""},{"code":"6.3.6","q":"Describe NEAT correction","a":"For maximum reverse thrust usage with NEAT reversers, the landing distance is affected. To account for the distance penalty, reduce the runway available by the penalty. Separate penalties are defined for two engine maximum reverse and four-engine maximum reverse. The penalty is\n\ndependent on RCR and runway available (to account for weight, altitude, and temperature variations).","ref":""},{"code":"6.3.7","q":"Describe TOLD RSC/RCR hazard","a":"For any valid RSC greater than .00 entered into the MC, the MC uses an RCR of 12 for TOLD computations unless otherwise stated. When an RSC greater than .00 is used, the MC sets the affected TOLD DATA 1 page’s RCR to 12. This is accompanied by the scratchpad annunciation RCR RESET TO 12. Students should demonstrate use of the table.","ref":""},{"code":"6.3.8","q":"Describe the application of the RCAM matrix","a":"Students should demonstrate use of the table.","ref":""}]},{"code":"6.4","title":"Part B","items":[{"code":"6.4.1","q":"TRs authorisation","a":"IDLE/MAX – AS CDR 4 MAX - DDH","ref":""},{"code":"6.4.2","q":"TOLD adjustments for cables","a":"Op Man pt B 4.4.2.","ref":""}]},{"code":"6.6","title":"Net Take-Off Flight Path (NTOFP)","items":[{"code":"6.6.1","q":"Define Reference Zero","a":"Reference Zero is the point 35 ft directly below the aeroplane at the end of TODR. It is the datum to which the co-ordinates of the various points in the take-off flight path are referred. AP3456 Volume 2 Chapter 12","ref":""},{"code":"6.6.2","q":"State the difference between Gross and Net performance","a":"Most of the time, runways have surrounding obstacles which must be taken into account prior to take-off, to ascertain that the aircraft is able to clear them. A vertical margin has to be considered between the aircraft and each obstacle in the take-off flight path. This margin, based on a climb gradient reduction, leads to the definitions of the Gross Take-off Flight Path and the Net take-off flight Path.\n\nGROSS Flight Path = Take-off flight path actually flown by the aircraft.\n\nNET Flight Path = Gross take-off flight path minus a mandatory reduction.\n\nThe net take-off flight path data must be determined so that they represent the actual [Gross] take-off flight path reduced at each point by a gradient equal to 1.0% for four-engine aeroplanes.","ref":""},{"code":"6.6.3","q":"Describe Segment 1 of the NTOFP","a":"This segment extends from the 35 ft point to the point where the landing gear is fully retracted and (if applicable) the propeller of the failed power unit is feathered. This segment is flown at, or above, the Take-off Safety Speed (V2).","ref":"AP3456 Volume 2 Chapter 12"},{"code":"6.6.4","q":"Describe Segment 2 of the NTOFP","a":"This segment is flown at a minimum of V2 and extends from the end of the first segment to the height chosen for the initiation of flap retraction. The\n\nheight chosen for flap retraction depends on the aeroplane. The ODM will give one of the following as the preferred height:\n\nThe attainment of a minimum height of 400 ft.\n\nThe attainment of the maximum level-off height (MLOH). The MLOH results from any limitation if flap retraction is delayed in order to achieve\n\nclearance of obstacles close to Reference Zero.\n\nThe attainment of the maximum height that can be reached within the time limit imposed by use of take-off thrust (typically 5 minutes after\n\nbrake release).\n\nThe attainment of a height of 1,500 ft.                                                                     AP3456 Volume 2 Chapter 12","ref":""},{"code":"6.6.5","q":"Describe Segment 3 of the NTOFP","a":"This segment assumes a period of level flight at take-off thrust, during which the aircraft accelerates, and the flaps are retracted in accordance with the recommended speed schedule. AP3456 Volume 2 Chapter 12","ref":""},{"code":"6.6.6","q":"Describe Segment 4 of the NTOFP","a":"maximum continuous thrust. This segment extends from the level-off height to a net height of 1,500 ft or more. This segment is flown at the final segment climb speed using","ref":"AP3456 Volume 2 Chapter 12"},{"code":"6.6.7","q":"State the vertical obstacle clearance requirements in the obstacle domain","a":"co  Obstacle\n\nclearance margin\n\nBank angle ≤ 15°35 ft\n\nBank angle > 15°50 ft","ref":"JAR-OPS 1.495"},{"code":"6.6.8","q":"State the NTOFP required climb gradients for 4-engine aircraft (1EO)","a":"1st segment0.5%\n\n2nd segment3.0%\n\n3rd segmentLevel Flight\n\n4th segment1.7%","ref":"JAR 25.121"},{"code":"6.6.9","q":"State the required go-around climb gradients (1EO)","a":"In approach configuration2.7%\n\nIn landing configuration3.2%","ref":"JAR 25.121 subpart B"},{"code":"6.6.10","q":"State the en-route terrain clearance requirements (2EO)","a":"The two engines inoperative en-route net flight path data must permit the aeroplane to continue the flight, in the expected meteorological conditions, from the point where two engines are assumed to fail simultaneously, to an aerodrome at which it is possible to land, clearing all terrain and obstructions along the route within 5 nm on either side of the intended track. If the navigational accuracy does not meet the 95% containment level, an operator must increase the width margin 10 nm. The net flight path must clear vertically, by at least 2,000 ft all terrain and obstructions along the route within the prescribed corridor.","ref":"JAR-OPS 1.505"}]}]},{"num":"7","name":"Performance Based Navigation (PBN)","sections":[{"code":"7.1","title":"PBN Principles","items":[{"code":"7.1.1","q":"List the factors used to define area navigation (RNAV) or required navigation performance (RNP) system performance requirements","a":"The PBN concept specifies that aircraft RNAV and RNP system performance requirements be defined in terms of:\n\nAccuracy\n\nIntegrity\n\nContinuity\n\nFunctionality\n\n•\n\nThe aircraft needs to be PBN Approved. – CAT.IDE.A.345\n\nThe Operator needs to establish procedures for PBN.- Annex IV, Subpart B / CAT.OP.MPA.126\n\nThe pilot needs to be PBN approved. – FCL.515(b): FCL.615(b)\n\nThe airspace requires PBN. - Applicable AIP.\n\n•","ref":"Doc 9613 ICAO PBN Manual 1.2"},{"code":"7.1.2","q":"State the advantages of RNAV and RNP systems","a":"Reduces the need to maintain sensor-specific routes and procedures, and their associated costs. For example, moving a single very high\n\nfrequency (VHF) omnidirectional radio range (VOR) ground facility can impact dozens of procedures, as VOR can be used on routes, VOR approaches, missed approaches, etc. Adding new sensor-specific procedures will compound this cost, and the rapid growth in available navigation systems would soon make sensor-specific routes and procedures unaffordable.\n\nAvoids the need to develop sensor-specific operations with each evolution of navigation systems, which would be cost-prohibitive. The\n\nexpansion of satellite navigation services is expected to contribute to the continued diversity of RNAV and RNP systems in different aircraft. Some augmentations support PBN operations, and the introduction of new core-constellations and signals will further improve global navigation satellite system (GNSS) performance. The use of GNSS/inertial integration is also expanding.\n\nAllows for more efficient use of airspace (route placement including the use of free routing, fuel efficiency, noise abatement, etc.).","ref":"Doc 9613 ICAO PBN Manual 1.1.2"},{"code":"7.1.3","q":"State that it is necessary for crews to be aware of the on-board RNAV or RNP system capabilities to determine whether the performance of the RNAV or RNP system is appropriate for the specific airspace requirements","a":"Crews should be aware of the on-board RNAV or RNP system capabilities and performance and ensure that it is appropriate for the current airspace requirements.","ref":"Doc 9613 ICAO PBN Manual – Executive Summary"},{"code":"7.1.4","q":"Define accuracy as the conformance of the true position and the required position","a":"Accuracy is defined as the lateral positional error measured in nautical miles between the calculated aircraft position and the actual aircraft position. During operations in airspace or on routes designated as, for example, RNP X, the lateral total system error (TSE) must be within ±X NM for at least 95 per cent of the total flight time. The along-track error must also be within ±X NM for at least 95 per cent of the total flight time.","ref":"Doc 9613 ICAO PBN Manual"},{"code":"7.1.5","q":"Define continuity as the capability of the system to perform its function without unscheduled interruptions during the intended operation","a":"Continuity is the ability of the system to perform without interruptions. The impact of a loss of function of is classified as either a ‘minor’ or ‘major’\n\nfailure condition depending on the airspace. For example, in remote areas, loss of functionality would be a major failure as there would be no ground based navigational beacons to utilise, whereas over continental airspace it would be considered a minor failure.","ref":"Doc 9613 ICAO PBN Manual"},{"code":"7.1.6","q":"Define integrity as a measure of the trust that can be placed in the correctness of the information supplied by the total system. Integrity includes the ability of a system to provide timely and valid alerts to the user.","a":"Integrity is a measure of the trust that can be placed in the accuracy of the positional information. In this context the ‘total system’ is not just the onboard equipment but also includes database accuracy, procedure construction etc. The requirement to keep the actual airplane position within a radius that is 2xRNP for 99.999 percent of the time. RNP has the additional requirement of system monitoring and crew alert.","ref":"Doc 9613 ICAO PBN Manual"},{"code":"7.1.7","q":"State that, unlike conventional navigation, PBN is not sensor specific","a":"The PBN concept represents a shift from sensor-based navigation and requires the use of an RNAV or RNP system. Operational requirements drive the performance requirements, which are then identified in navigation specifications and determine the specified choices of navigation sensors and equipment that may be used to meet the performance requirements. PBN is therefore not sensor specific and multiple sensors can be used to derive a positional solution.","ref":"Doc 9613 ICAO PBN Manual"},{"code":"7.1.8","q":"Explain the difference between raw data and computed data","a":"Any position data from a source (VOR, TACAN, etc) is considerate raw data. Raw data is combined to generate a position solution – the computed data.","ref":"Doc 9613 ICAO PBN Manual"},{"code":"7.1.9","q":"Define availability as the percentage of time (annually) during which the system is available for use","a":"Availability is a percentage of time (annually) during which a given system is available for use.","ref":"Doc 9613 ICAO PBN Manual"}]},{"code":"7.2","title":"Navigation Specifications","items":[{"code":"7.2.1","q":"State the difference between RNAV and RNP in terms of the requirement for on-board performance monitoring and alerting","a":"Although there are several differences between RNAV and RNP, in terms of procedure construction for example, the main difference is to do with\n\non-board performance monitoring:\n\nRNAV does not require on-board performance monitoring\n\nRNP requires on-board performance monitoring and crew alerts.\n\nThe RNP 10 designation, if used, is an exception in that it does not require on-board performance monitoring. As a result, RNP 10 is often referred\n\nto RNAV 10.","ref":"Doc 9613 ICAO PBN Manual"},{"code":"7.2.2","q":"List the basic functional requirements of the RNAV and RNP specifications","a":"Both RNAV and RNP navigation specifications include requirements for certain navigation functionalities. At the basic level, these functional requirements may include:\n\ncontinuous indication of aircraft position relative to track to be displayed to the pilot flying on a navigation display situated in his primary\n\nfield of view\n\ndisplay of distance and bearing to the active (To) waypoint\n\ndisplay of ground speed or time to the active (To) waypoint\n\nnavigation data storage function\n\nappropriate failure indication of the RNAV or RNP system, including the sensors\n\nMost navigation specifications include the requirement for a navigation database and the capability to retrieve and execute procedures from this database.","ref":"Doc 9613 ICAO PBN Manual"},{"code":"7.2.3","q":"Interpret X in RNAV X or RNP X as the lateral navigation (LNAV) accuracy (total system error) in nautical miles, which is expected to be achieved at least 95 % of the flight time by the population of aircraft operating within the given airspace, route or procedure.","a":"An RNAV or RNP navigation specification is designated as RNV X or RNP X, and indicates the accuracy required, in nautical miles, that must be achieved 95% of the time.","ref":"Doc 9613 ICAO PBN Manual"},{"code":"7.2.4","q":"State that RNAV 10 and RNP 4 are used in the oceanic/remote phase of flight","a":"RNAV 10 and RNP 4 are used in oceanic/remote phases of flight. The minimum route spacing supported by RNP 4 is 30 nm, whereas the minimum route spacing supported by RNAV 10 is 50 nm.","ref":"Doc 9613 ICAO PBN Manual"},{"code":"7.2.5","q":"State that RNAV 5 is used in the en-route and arrival phases of flight","a":"Each RNAV/RNP specification has ‘Required’ and ‘Optional’ NAVAID infrastructure requirements to calculate a positional solution. RNP 4, for example, only requires GNSS (hence oceanic usage), whereas RNP 2 requires GNSS but has DME/DME and DME/DME/INS as optional requirements.\n\nRNAV 5 is an oddity in that is has the greatest flexibility in optional navaid infrastructure to determine its solution – it is the only one that does not require GNSS and that can use VOR/DME. However, it cannot be used in oceanic or remote airspace as ground facilities are potentially required, and so is designated on specific routes that lie within the coverage of station-referenced NAVAIDS.","ref":"Doc 9613 ICAO PBN Manual"},{"code":"7.2.6","q":"State that RNP 2 is used in the en-route and oceanic/remote phases of flight","a":"RNP 2 is primarily intended for a diverse set of en-route applications, particularly in geographic areas with little or no ground NAVAID infrastructure. Use of RNP 2 in continental applications requires a lower continuity requirement than used in oceanic/remote applications. In the latter application, the target traffic is primarily transport category aircraft operating at high altitude, whereas continental applications may include a significant percentage of general aviation aircraft.","ref":"Doc 9613 ICAO PBN Manual"},{"code":"7.2.7","q":"State that RNAV 2 might be used in the en-route continental, arrival and departure phases of flight","a":"Since RNAV 2 does not require GNSS, its use is restricted to continental routes. The accuracy of the solution does allow its use for continental, arrival and departure phases of flight.","ref":"Doc 9613 ICAO PBN Manual"},{"code":"7.2.8","q":"State that RNAV 1 and RNP 1 are used in the arrival and departure phases of flight","a":"RNAV 1 and RNP 1 are used for arrival and departure phases of flight as well as initial and intermediate approach phases.","ref":"Doc 9613 ICAO PBN Manual"},{"code":"7.2.9","q":"State that required navigation performance approach (RNP APCH) is used in the approach phase of flight","a":"RNP APCH has a value of 0.3. Some procedures will indicate RNP 0.3 rather than RNP APCH – this is a helicopter only specification, and is not the same.","ref":"Doc 9613 ICAO PBN Manual"},{"code":"7.2.10","q":"State that required navigation performance authorisation required approach (RNP AR APCH) is not authorised on the C-17A","a":"RNP AR APCH is not authorised on the C-17A. co","ref":""}]},{"code":"7.3","title":"Use of Performance Based Navigation (PBN)","items":[{"code":"7.3.1","q":"Recognise the definition of radius to fix (RF) leg","a":"The RF leg is a leg type that should be used when there is a requirement for a specific curved path radius in a terminal or approach procedure. The radius to fix (RF) leg begins at the fix for the preceding path terminator and is defined by a turn direction, a turn centre point and termination fix that the RNP systems uses to calculate the radius and path. RNP systems supporting this leg type provide the same ability to conform to the track-keeping accuracy during the turn as in the straight-line segments.\n\nIT SHOULD BE NOTED THAT THE C17 IS UNABLE TO FLY SIDs THAT INCLUDE RF LEGS AS PER AFMAN 11-2c-17v3 para 9.3.4.3 and PBN TRANSITION TO FINAL IAPs THAT INCLUDE RF LEGS, AFMAN 11-2C117V3 para 8.3.5.4.3","ref":"ICAO Doc 9613"},{"code":"7.3.2","q":"Explain the difference between a fly-by-turn and a fly-over","a":"A fly-by-turn is one when the aircraft does not fly directly over the waypoint but initiates the turn before the waypoint to transition smoothly to the next path segment. (See 7.3.2). A fly-over waypoint is on where the aircraft must pass directly over the waypoint before a turn is initiated. The fly-over turn is not compatible with RNP flight tracks and will only be used when there is no requirement for repeatable paths.","ref":"ICAO Doc 9613"},{"code":"7.3.3","q":"Define the term ‘offset flight path’","a":"RNP systems may provide the capability for the flight crew to specify a lateral offset from a defined route. Generally, lateral offsets can be specified in increments of 1 NM up to 20 NM. When a lateral offset is activated in the RNP system, the aircraft will leave the defined route and typically intercept the offset at a predefined angle. When the offset is cancelled, the aircraft returns to the defined route in a similar manner. Such offsets can be used both strategically, that is, fixed offset for the length of the route, or tactically, that is, temporarily. Most RNP systems automatically cancel offsets in the terminal area or at the beginning of an approach procedure, at a hold, or during course changes of 90 degrees or greater.","ref":"ICAO Doc 9613"}]},{"code":"7.4","title":"Performance Based Navigation (PBN) Operations","items":[{"code":"7.4.1","q":"Define ‘path definition error’ (PDE)","a":"PDE occurs when the defined path in the aircraft’s navigation system does not correspond to the airspace planner’s or procedure designer’s desired path (the path ATC expects the aircraft to fly over the ground). Use of an RNAV or an RNP system for navigation requires the aircraft’s on- board navigation database be loaded with and contain the defined path representing the PBN route or procedure’s path. Where the database procedure contains segments or path terminators affected by magnetic variation (such as heading), altitude terminated, or fly-by/fly-over requirements, this will result in greater variability in the path flown and greater PDE. The PDE is generally considered negligible but may need to be evaluated for specific procedures. ICAO Doc 9613","ref":""},{"code":"7.4.2","q":"Define ‘flight technical error’ (FTE) and state that the FTE is the error in following the prescribed path, either by the auto-flight system or by the pilot","a":"FTE, sometimes referred to as path steering error, relates to the flight crew or autopilot’s ability to follow the aircraft navigation system’s defined path or track, and this error includes any display error (such as course deviation indicator (CDI) centering error). The flight crew can monitor and\n\ncontrol FTE through their use of the aircraft’s flight guidance system (such as coupling the autopilot to the steering commands from the navigation system) or through flight crew procedures and training requiring monitoring of the FTE displayed on the aircraft display system. Where flight crew monitoring procedures are used, support may be required from other means of monitoring and controlling FTE, depending on the phase of flight and the type of PBN operation. For example, many RNP navigation specifications require the aircraft to provide support for a flight crew by requiring a moving map display showing the desired route or path and the aircraft’s own-ship relative to the path as an aid to situation and position awareness,\n\nwhile also requiring a deviation display in each pilot’s primary field of view.","ref":"ICAO Doc 9613"},{"code":"7.4.3","q":"Define ‘navigation system error’ (NSE) and state that the accuracy of a navigation system may be referred to as NSE","a":"NSE is the difference between the aircrafts estimated position and actual position.","ref":"ICAO Doc 9613"},{"code":"7.4.4","q":"Define ‘total system error’ (TSE) and state that the geometric sum of the PDE, FTE and NSE equals the TSE","a":"TSE is the total error resulting from a combination of PDE, FTE and NSE.","ref":"ICAO Doc 9613"},{"code":"7.4.5","q":"State that navigation accuracy depends on the TSE","a":"Navigational accuracy depends on Total System Error (TSE).\n\n7.4.6 State that on-board performance monitoring and alerting of flight technical errors is managed by on-board systems or flight crew procedures\n\nOn-board monitoring systems should alert crews when on accuracy drops below that required for the RNP level.","ref":"ICAO Doc 9613"},{"code":"7.4.7","q":"State that on-board performance monitoring and alerting of navigation system errors is a requirement of on-board equipment for RNP","a":"The on-board monitoring is achieved by RAIM. On-board monitoring is what differentiates RNP from RNAV.","ref":"ICAO Doc 9613"},{"code":"7.4.8","q":"State that, dependent on the navigation sensor, the Actual Navigation Performance (ANP) is compared with the required navigation specification","a":"The aircrafts MC/EDC systems advise the crew of the current RNP value and provides feedback of how the systems actually perform.\n\nThe ANP ( Actual Navigation Performance) is the MCs estimate of the lateral error of the PPOS The HUD and the MFDs PFD and ND Map and chart formats lateral deviation indicators are scaled appropriately for the current RNP.","ref":""},{"code":"7.4.9","q":"Give an example of how the loss of the ability to operate in RNP airspace may be indicated by the navigation system","a":"There are a number of occasions when the ANP will be greater than the required RNP.\n\nValue vs Delay\n\nRNP Value  Persistence Delay (seconds)\n\nRNP <=1.0  10\n\n1.0<RNP<=2.0  20\n\n2.0<RNP<=4.0  40\n\n4.0<RNP  80\n\nA number of Messages will appear on the WAP or Scratch pad. 1.","ref":""},{"code":"7.4.10","q":"State the C17 RNP Characteristics","a":"Flight phase  Default RNP (NM)  Remarks  Overwrite paged\n\nTerminal 1.0 Within 30NM of the origin or destination, from the ground to 15000’ MSL and not on approach\n\nEnroute/Domestic 2.0 Outside terminal airspace and viable DME updating available.\n\nViable DME updating is when 2NAV SENSOR - RNP\n\neligibleWWNDBDMW,\n\nVOR/DME or VORTAC facilities are within line of sight. Does not require DME updating\n\nOceanic/Remote 4.0 Outside terminal airspace but no viable DME updating available.\n\nApproach 1.0 On a WWNDB ILS, VOR/DME,\n\nTACAN or NDB approach, or less than 2000’ above the destinations\n\nelevation  within  10nm  of\n\ndestination\n\n0.3 On a MC approach or a WWNDB RNAV approach or less than 2000’ above the destinations\n\nelevation  within  10nm  of\n\ndestination\n\nAirdrop CARP: 100 yards When Airdrop IP becomes the ADXX PROGRESS\n\nactive  waypoint  through\n\nHARP: 1013 yards\n\nco  [DZ]/[ESC]. Terminated when\n\nnon-airdrop waypoint becomes active","ref":""},{"code":"7.4.11","q":"State that, unless otherwise specified in the operations documentation or acceptable means of compliance (AMCs), the navigational database must be valid for the current aeronautical information regulation and control (AIRAC) cycle","a":"The navigational database must be current for the duration of the flight.","ref":""}]},{"code":"7.5","title":"Requirements of Specific RNAV and RNP Specifications","items":[{"code":"7.5.1","q":"State the allowable updating sources for the MC Position and RNP operation on the C17","a":"Area of Application Required ANP NAV SENSORS CONTROL PAGE UPDATE STATUS (1L) 1 and Navigation Standard CGPS MGPS 2&3 DME/DME IRU / MCOAST\n\nMNPS ≤ 12.6\n\nOceanic and ≤ 10.0 Remote airspace A A\n\n(RNP10)\n\nA  A\n\nBRNAV (RNP5) ≤ 5.0\n\nOceanic and remote ≤ 4.0 NA\n\nairspace (RNP4)\n\nTERMINAL\n\nP-RNAV ≤ 1.0 co US-RNAV 1 ≤ 1.0\n\nA  A  A  A\n\nUS-RNAV 2 ≤ 2.0 GPS Approach ≤ 0.3 NA (RNP0.3)\n\nA = AUTHORISED SOURCE FOR UPDATING NA = NOT AUTHORISED SOURCE FOR UPDATING 1 = Operation in RNAV/RNP airspace using VOR/VOR/DME, FIX or DR updates is not authorised. 2 = MGPS loaded with PPS codes is authorised as an update source in civil airspace 3 = NO RNP SENSOR MCD message will annunciate whenever MGPS is selected as an update source","ref":""},{"code":"7.5.2","q":"State that RNAV 10 requires that aircraft operating in oceanic and remote areas be equipped with at least two independent and serviceable long-range navigation systems (LRNSs) comprising an INS, an inertial reference system (IRS)/flight management system (FMS) or a GNSS","a":"Since oceanic or remote operations will not have access to ground based navigational aids, the navigation solution requires at least two independent and serviceable long-range navigation systems (LRNSs) comprising an INS, an inertial reference system (IRS)/flight management system (FMS) or a GNSS.","ref":"ICAO Doc 9613"},{"code":"7.5.3","q":"State that pilots must not fly an RNAV 1, RNAV 2, RNP 1 or RNP 2 standard instrument departure (SID) or standard instrument arrival (STAR) unless it is retrievable by route name from the on-board navigation database and conforms to the charted route","a":"Pilots must not fly an RNP 1 SID or STAR unless it is retrievable by procedure name from the on-board navigation database and conforms to the charted procedure.","ref":"ICAO Doc 9613"},{"code":"7.5.4","q":"State that the route may subsequently be modified through the insertion (from the database) or deletion of specific waypoints in response to ATC clearances","a":"Procedures may subsequently be modified through the insertion or deletion of specific waypoints in response to ATC clearances.\n\n7.5.5 State that the manual entry, or creation of new waypoints by manual entry, of either latitude and longitude or\n\nplace/bearing/distance values is not permitted. The manual entry, or creation of new waypoints, by manual entry of latitude and longitude or rho/theta values is not permitted. Additionally, pilots must not change any SID or STAR database waypoint type from a fly-by to a fly-over or vice versa.","ref":"ICAO Doc 9613"},{"code":"7.5.6","q":"State that pilots must not fly an RNP APCH unless it is retrievable by procedure name from the on-board navigation database and conforms to the charted procedure","a":"Pilots can only fly a procedure that is extracted from the database, without any amendment, and which is seen to conform to the charted procedures. The lateral path must not be modified, with the exception of:\n\nAccepting a clearance to go direct to a fix in the approach procedure that is before the FAF and that does not immediately precede an RF\n\nleg.\n\nChanging the altitude and/or airspeed waypoint constraints on the initial, intermediate, or missed approach segments of an approach (e.g.\n\nto apply cold temperature corrections or comply with an ATC clearance/instruction).","ref":"ICAO Doc 9613"},{"code":"7.5.6","q":"Explain why an RNP APCH to LNAV/VNAV minima cannot be flown","a":"The C17 is not authorised to fly approaches to LNAV/VNAV minima only LNAV minima","ref":""}]},{"code":"7.6","title":"Receiver Autonomous Integrity Monitoring (RAIM)","items":[{"code":"7.6.1","q":"State that, although PBN is not a system-based solution, GPS forms and important part of the navigational solution","a":"PBN does not necessarily require use of GNSS. However, GNSS usually forms an essential part of the navigation solution.","ref":"ICAO Doc 9613"},{"code":"7.6.2","q":"Describe how ‘receiver autonomous integrity monitoring (RAIM)’ monitors the integrity of the navigation solution","a":"RAIM uses spare satellite reception to validate the accuracy of those satellites being used as part of the navigation solution. 4 satellites are required to give an accurate 3D position. RAIM uses additional satellites to monitor the performance of the 4 satellites being used to determine the 3D position. A fifth satellite allows RAIM to determine if there is problem with one of the used satellites. A sixth satellite allows RAIM to determine which satellite is in error. Essentially RAIM uses redundant satellite signals to produce multiple positions which are then compared to determine is there are any errors on the satellite signals. If a satellite is found to be at fault it can be excluded from contributing to the position solution.","ref":"ICAO Doc 9613"},{"code":"7.6.3","q":"Describe what is meant by RAIM Prediction","a":"Since the areas on the Earth for which 4+ satellites will be in view will change all the time due to unserviceability or maintenance, it is necessary to determine if the flight path will be over an area in which there will be insufficient satellites in view for RAIM to function correctly, i.e. at least 5 satellites. The Jeppesen Jetplan includes a RAIM report that indicates GSP coverage that will ensure an RNP of 0.3 in the terminal area and 2 in the enroute phase. It will indicate if there are any parts of the flight in which these criteria cannot be met.","ref":"ICAO Doc 9613"}]}]}],"samples":[{"part":"1","name":"MMATM","qs":[{"n":1,"q":"Describe how to fly a CDFA approach.","refs":["1.1.3"],"added":null},{"n":2,"q":"What approach category is the C-17A?","refs":["1.1.5"],"added":null},{"n":3,"q":"Can the approach category for the C-17A be changed?","refs":["1.1.5"],"added":null},{"n":4,"q":"What is the minimum MDA and DA for military aircraft?","refs":["1.1.6","1.1.7"],"added":null},{"n":5,"q":"By how much can the approach track differ from the runway QDM if a straight in approach is to be flown?","refs":["1.1.1"],"added":"Not stated in the syllabus text. For a straight-in approach the final approach track is normally required to be within 30° of the runway centreline (15° for Cat C/D at some states); confirm against MMATM Ch 2 and the plate."},{"n":6,"q":"What visual reference are required to continue an approach at DH/MDH?","refs":["1.1.9","2.1.16"],"added":null},{"n":7,"q":"What is the minimum RVR/visibility required to start a training approach?","refs":["1.1.10","2.1.14"],"added":null},{"n":8,"q":"What visibility do you need to continue past the FAF on an approach to land?","refs":["1.1.11","2.1.17"],"added":null}]},{"part":"2","name":"Aviation Duty Holder orders","qs":[{"n":1,"q":"What documents do you need to present to the IRE before the test?","refs":["2.1.1"],"added":"See also Appendix A — the candidate training sheet lists what to present on the day."},{"n":2,"q":"If you fail to complete an element of the IRT to the required standard is that an automatic fail?","refs":["3.4.2","2.1.2"],"added":null},{"n":3,"q":"How many approaches do you need to complete before being awarded an Instrument Rating?","refs":["2.1.2"],"added":null},{"n":4,"q":"Can you be a CR pilot without an Instrument Rating","refs":["2.1.2","2.2.3"],"added":null},{"n":5,"q":"If no RVR is available, can you adjust met vis to check take off minima?","refs":["2.1.12"],"added":null},{"n":6,"q":"What do you need to do to keep an instrument rating valid?","refs":["2.2.2"],"added":null},{"n":7,"q":"When do you need to nominate a take-off alternate? How close does it have to be?","refs":["2.1.7"],"added":null},{"n":8,"q":"When might a reported mid-point value for RVR become relevant/limiting?","refs":["2.1.13","2.1.14"],"added":null},{"n":9,"q":"What is the absolute min RVR for a NPA & PA in an RAF AM ac?","refs":["2.1.17","2.1.18"],"added":null},{"n":10,"q":"What are required visual references to continue and then descend below minima on circle approach?","refs":["2.1.16","2.1.21"],"added":null},{"n":11,"q":"When do you need to nominate a take-off alternate?","refs":["2.1.7"],"added":null},{"n":12,"q":"It is the 8th of the month & you are flying from Brize Norton to Brussels, due in to EBBR at 1700. The TAF is EBBR 081240Z 0814/0914 25006KT 9999 BKN050 TEMPO 0818/0821 2000 +SHRA BKN025TCU. Do you need to nominate a diversion airfield? Due to problems with MOG, you are now delayed an hour. Does this affect your answer?","refs":["2.2.4"],"added":null},{"n":13,"q":"What planning minima are required for an en-route alternate if it only has a VOR/DME approach?","refs":["2.2.4","2.1.18"],"added":null},{"n":14,"q":"You’re trying to depart an airfield with reduced Rwy lighting at night. There's no RVR published, Met vis is given as 300m. The take-off minima are 500m. Calculate RVR and determine if you can take- off.","refs":["2.1.12"],"added":null},{"n":15,"q":"Can you get airborne without a functioning IFF?","refs":["2.1.4"],"added":null},{"n":16,"q":"When must you calculated an LPD?","refs":["2.1.9"],"added":null},{"n":17,"q":"Explain the elements that go to make up the total fuel figure.","refs":["2.1.11"],"added":null},{"n":18,"q":"It’s nighttime and your operating to a runway that is lit up like a Christmas tree but has not reported RVR. By how much can you multiply the MetVis to calculate the RVR?","refs":["2.1.12"],"added":null},{"n":19,"q":"What is the absolute minimum RVR required for take-off?","refs":["2.1.13"],"added":null},{"n":20,"q":"Do you need to add an additional 50 ft to the MDA for a circling approach?","refs":["2.1.21"],"added":null},{"n":21,"q":"What should you log simulator IF time as, Actual or Simulated?","refs":["2.2.1"],"added":null},{"n":22,"q":"What do you need to do to keep your IRT current?","refs":["2.2.2","2.2.3"],"added":null},{"n":23,"q":"Describe what is meant by a stabilised approach.","refs":["2.2.6","2.1.20"],"added":null},{"n":24,"q":"You are in the USA and are asked to accept LAHSO operations after your landing. Can you accept the request?","refs":["2.2.7"],"added":null},{"n":25,"q":"You’re on an ILS approach to a parallel runway and ATC instructs you to carry out a breakaway manoeuvre by giving you heading change and a climb. What has happened and how long do you have to initiate the change?","refs":["2.2.8","2.2.9"],"added":null},{"n":26,"q":"Describe the two NADPs. And the C-17 version of noise abatement procedure.","refs":["2.3.2"],"added":null},{"n":27,"q":"By what altitude should you be stabilised on an IF approach?","refs":["2.3.1"],"added":null}]},{"part":"3","name":"Information","qs":[{"n":1,"q":"What does EMAS on an airport taxi plate mean?","refs":[],"added":"EMAS — Engineered Materials Arresting System. A bed of crushable material in the runway end safety area that decelerates an aircraft that overruns. It is not a stopway and gives no declared distance credit; an overrun into EMAS will normally damage the aircraft."},{"n":2,"q":"What does (600-1) mean, in the minima for an ILS?","refs":["3.5.1"],"added":"(600-1) is the US/TERPS minima convention: 600 ft RVR equivalent / 1 statute mile visibility."},{"n":3,"q":"What does a highlighted altitude mean on an SID?","refs":["3.5.1"],"added":null},{"n":4,"q":"The information ALS H-C, P3 (57) is given next to a runway. What does it mean?","refs":["3.5.1"],"added":null},{"n":5,"q":"In a Take Off minima table what does LVTO mean?","refs":["3.5.1","2.1.13"],"added":"LVTO — Low Visibility Take-Off: take-off in an RVR below the normal published minimum, needing specific approval, crew qualification and airfield facilities."},{"n":6,"q":"On an enroute chart what does 10g mean when written next to a PMP?","refs":["3.5.2"],"added":null},{"n":7,"q":"What do the two FL number indicate at the base of airways indicate?","refs":["3.5.2"],"added":null},{"n":8,"q":"Why are some airway reporting points clear triangles, others black?","refs":["3.5.2"],"added":"Solid (black) triangles are compulsory reporting points; open (clear) triangles are on-request / non-compulsory."},{"n":9,"q":"What do REDL, RCLL, HRCLL & RETIL mean?","refs":["3.5.1"],"added":"Runway lighting abbreviations: REDL runway edge lights; RCLL runway centreline lights; HRCLL high-intensity runway centreline lights; RETIL rapid exit taxiway indicator lights."},{"n":10,"q":"What do yellow chevrons on the Rwy, prior to the threshold, indicate?","refs":[],"added":"Yellow chevrons mark a pre-threshold paved area that is unsuitable for normal use — not usable for taxi, take-off or landing, only as overrun/blast pavement."},{"n":11,"q":"What do Cable markers look like?","refs":["3.5.1"],"added":null},{"n":12,"q":"Describe Runway visual aiming point markings","refs":[],"added":"The aiming point marking is two broad white rectangular stripes either side of the centreline, starting about 300 m from the threshold — the visual touchdown target on a precision-marked runway."},{"n":13,"q":"What is the min viz for takeoff from Brize?","refs":["2.4.1","2.1.13"],"added":"Airfield-specific — look it up in the Brize TAP and OM Part C (Aerodrome Briefing Manual) rather than memorising it."},{"n":14,"q":"What is min time spacing for your aircraft for take-off after a heavy aircraft","refs":["3.1.3"],"added":null},{"n":15,"q":"What is a Rwy QFU? What is it for Brize (either Rwy)?","refs":[],"added":"QFU is the magnetic orientation of the runway — the runway's magnetic bearing in degrees. Read the current figure for each Brize runway off the TAP; it shifts as magnetic variation is re-surveyed."},{"n":16,"q":"Brize lights are listed on the TAPs as P3° (58) CL5B(H) RTHL(H): REDL(H): RCLL(H): RENL(H). Decode.","refs":["3.5.1"],"added":null},{"n":17,"q":"Brize TAP has ‘ARP N51 45·00 W001 35·02 (WGS 84)’ What does this mean? What is WGS84 & why is this info relevant?","refs":["3.5.1"],"added":"ARP is the Aerodrome Reference Point. WGS 84 is the global geodetic datum ICAO mandates for published coordinates — it matters because GNSS and the FMS work in WGS 84, so a chart on another datum would not agree with the aircraft position."},{"n":18,"q":"What is the comms loss procedure at Brize?","refs":["2.4.1"],"added":"Airfield-specific — Brize comms-loss procedure is in the TAP and OM Part C."},{"n":19,"q":"What is min circling viz for an C-17A (class D) at Brize?","refs":["3.1.8","2.1.21"],"added":null},{"n":20,"q":"What are minima in brackets on BZN TAPs?","refs":["3.5.1"],"added":null},{"n":21,"q":"Brize TAPs refer to MIPS for minima – what does this mean?","refs":["3.5.1","2.3.4"],"added":"MIPS — Military Instrument Procedure Standard, the UK military criteria set used in place of PANS-OPS/TERPS for some UK military plates."},{"n":22,"q":"Do any Brize navigation facilities have protected range?","refs":["2.4.1"],"added":"Airfield-specific — check the designated operational coverage / protected range notes on the Brize TAP and in the AIP."}]},{"part":"4","name":"Flight Instruments and Radio Aids","qs":[{"n":1,"q":"Describe the basic principles of an ASI.","refs":["4.1.1"],"added":null},{"n":2,"q":"Describe the errors of an ASI.","refs":["4.1.2"],"added":null},{"n":3,"q":"Describe the basic principles of an altimeter.","refs":["4.1.5"],"added":null},{"n":4,"q":"Describe the potential errors of an altimeter.","refs":["4.1.6"],"added":null},{"n":5,"q":"Describe the basic principles of the VSI.","refs":["4.1.3"],"added":null},{"n":6,"q":"Describe the potential errors of the VSI.","refs":["4.1.4"],"added":null},{"n":7,"q":"What 3 qualities must a Direct Indicating Compass (DIC) exhibit?","refs":["4.1.7"],"added":null},{"n":8,"q":"What are the 4 potential errors of a DIC?","refs":["4.1.8"],"added":null},{"n":9,"q":"Describe the basic principles of a Ring Laser Gyro.","refs":["4.2.1"],"added":null},{"n":10,"q":"Describe the potential errors of a Ring Laser Gyro.","refs":["4.2.2"],"added":null},{"n":11,"q":"How many GPS receivers does the C-17A have?","refs":["4.4.4"],"added":null},{"n":12,"q":"What does ‘hybridization’ mean?","refs":["4.3.1","4.3.2"],"added":"Hybridisation means blending the inertial solution with GPS so each corrects the other — the IRS gives short-term stability and high update rate, GPS bounds the inertial drift, and the combined solution is better than either alone and degrades gracefully if GPS is lost."},{"n":13,"q":"What are the three segments of a GNSS system?","refs":["4.4.1"],"added":null},{"n":14,"q":"Describe the basic principles of a GNSS system.","refs":["4.4.1"],"added":null},{"n":15,"q":"‘Bearing by phase comparison’ is used by which ground based beacon?","refs":["4.4.2"],"added":null},{"n":16,"q":"How wide is the localiser on an ILS?","refs":["4.4.3"],"added":null},{"n":17,"q":"What are the upper and lower deflection limits on an ILS glideslope?","refs":["4.4.3"],"added":null},{"n":18,"q":"List the radio navigation equipment on the C-17A.","refs":["4.4.4"],"added":null}]},{"part":"5","name":"Meteorology","qs":[{"n":1,"q":"Define TEMPO, TCU and BKN.","refs":["5.1.1"],"added":null},{"n":2,"q":"What would 530002 mean in a TAF?","refs":["5.7.4"],"added":null},{"n":3,"q":"What is meant by dew point?","refs":["5.1.3"],"added":null},{"n":4,"q":"What are DALR, SALR & ELR and what is significant about their relationship?","refs":["5.3.1","5.3.2","5.3.3","5.3.4"],"added":null},{"n":5,"q":"What is a stable/unstable airmass? How might this affect cloud formation & type?","refs":["5.3.4"],"added":null},{"n":6,"q":"Define RVR and explain why it is different to met viz.","refs":["5.4.1","5.4.2"],"added":null},{"n":7,"q":"Explain the development of thermal winds.","refs":["5.2.2"],"added":null},{"n":8,"q":"What trigger actions can start vertical motion in the atmosphere?","refs":["5.3.5"],"added":null},{"n":9,"q":"What are the hazards of mountains waves?","refs":["5.3.6"],"added":null},{"n":10,"q":"By how far should you avoid CBs?","refs":["5.7.3"],"added":null},{"n":11,"q":"What height are cirrus clouds typically found?","refs":["5.5.1"],"added":null},{"n":12,"q":"What are the hazards to aviation of icing?","refs":["5.6.1"],"added":null},{"n":13,"q":"What is meant by ‘severe’ icing?","refs":["5.6.2"],"added":null},{"n":14,"q":"Where are you likely to encounter supercooled water droplets?","refs":["5.6.3"],"added":null},{"n":15,"q":"What three conditions are needed for the formation of thunderstorms?","refs":["5.7.1"],"added":null},{"n":16,"q":"What are the hazards of thunderstorms?","refs":["5.7.2"],"added":null},{"n":17,"q":"By how much should you avoid thunderstorms?","refs":["5.7.3"],"added":null},{"n":18,"q":"Describe the typical weather associated with a warm front, cold front.","refs":["5.8.1","5.8.2"],"added":null},{"n":19,"q":"How are turbulence & icing depicted on a met chart?","refs":["5.9.3"],"added":null},{"n":20,"q":"Where might you find CAT?","refs":["5.8.3"],"added":null},{"n":21,"q":"You’re flying from Dakar to Ascension and will pass through an active ITCZ. What weather might you expect?","refs":["5.8.4"],"added":null},{"n":22,"q":"How do rotors form & what hazards do they present?","refs":["5.3.6"],"added":null},{"n":23,"q":"What are lenticular clouds & how do they form? Why might they be of interest to pilots?","refs":["5.3.6"],"added":"Lenticular (altocumulus lenticularis) are smooth lens-shaped clouds that form in the crests of standing waves downwind of high ground. They are stationary while the air flows through them, and they mark wave activity — so they warn of mountain wave turbulence, strong up/downdraughts and rotor below."},{"n":24,"q":"What are super cooled water droplets, where are they most prevalent & why are they a hazard?","refs":["5.6.3"],"added":null},{"n":25,"q":"What are the different types of ice & which is the most hazardous to ac?","refs":["5.6.1","5.6.3"],"added":null},{"n":26,"q":"The temp at 2000ft above mean sea level is forecast to be 5°C; what ISA deviation is this?","refs":["5.1.2"],"added":null},{"n":27,"q":"Define FEW, SCT, BKN & OVC – which relevant when determining suitability/legality of cloud ceiling in TAF?","refs":["5.1.1"],"added":null},{"n":28,"q":"An ac flies at a constant indicated altitude from airfield A (QNH 1009mb) to airfield B (QNH 1019mb). If the subscale is not reset from 1009, would the ac be higher or lower than indicated on the altimeter?","refs":["5.1.2"],"added":"Classic 'high to low, down you go': flying at a constant indicated altitude from high QNH to low QNH, true altitude decreases — roughly 30 ft per hPa. Work the difference between the two QNH values and apply it."},{"n":29,"q":"What is (D)CRO & how do you use it?","refs":[],"added":"(D)CRO — the (Duty) Chief Range/Rescue Officer in some contexts, but on met products CRO usually refers to the Colour Rank/Code Out system used to express airfield state. Confirm the intended meaning with your examiner — it is not defined in this syllabus."},{"n":30,"q":"Decode the following code contained in a METAR: R17/29//95","refs":["5.9.1"],"added":null},{"n":34,"q":"Decode the following TAF/METARs: CYQX 051139Z 051212 36015G25KT 3SM -SN SCT008 OVC015 TEMPO 1214 1SM -SN BLSN OVC008 FM1400Z 35012G22KT 3SM -SHSN BKN015 OVC090 TEMPO 1424 P6SM NSW SCT015 BKN090 BECMG 1719 34010KT FM1100Z 29012KT P6SM SCT020 BKN100 RMK NXT FCST BY 18Z SBKP 180842Z 181212 14006MPS 6000 DZ SCT020 BECMG 1315 9999 NSW SCT040 BECMG 1820 18005KT NSC BECMG 2224 12010KT CAVOK TX25/18Z TN13/09Z TAF MMMD 180441Z 180606 12010KT P6SM SCT020 SCT080 BECMG 0809 12005KT TEMPO 1214 5SM HZ FM15 12010KT P6SM BKN020 BKN300 TEMPO 2202 VCCB TN23/11Z TX37/19Z UBBB 011100Z 011212 17014KT CAVOK 53003 TEMPO 1218 SCT015 BECMG 1820 VRB04KT TEMPO 2302 0800 FG VV002 TEMPO 0204 SCT007= KABC 121755Z AUTO 21016G24KT 180V240 1SM R11/P6000FT -RA BR BKN015 OVC025 06/04 A2990 RMK A02 PK WND 20032/25 WSHFT 1715 VIS 3/4 V1 1/2 VIS 3/4 RWY11 RAB07 CIG 013V017 CIG 017 RWY11 PRESFR SLP125 POOO3 6OOO9 T00640036 10066 21012 58033 TSNO $","refs":["5.9.1","5.9.2"],"added":null}]},{"part":"6","name":"Performance","qs":[{"n":1,"q":"Define VGO, VROT VR VMCO VMCG VBMAX VBO speeds.","refs":["6.1.1"],"added":null},{"n":2,"q":"Define climb ceiling, optimum altitude and maximum altitude.","refs":["6.1.1"],"added":null},{"n":3,"q":"What speed category of ac is the C-17 for IF approaches?","refs":["1.1.5","3.1.8"],"added":null},{"n":4,"q":"Define TORA, TODA, ASDA, Stopway & Clearway.","refs":["6.1.1"],"added":null},{"n":5,"q":"Why is CFL important when computing take of calculations","refs":["6.2.1"],"added":null},{"n":6,"q":"Describe each of the 4 segments of NTOFP.","refs":["6.6.3","6.6.4","6.6.5","6.6.6"],"added":null},{"n":7,"q":"What is the minimum go-around climb gradient.","refs":["6.6.9"],"added":null},{"n":8,"q":"By how much should the aircraft be able to clear any enroute obstacles?","refs":["6.6.10"],"added":null}]},{"part":"7","name":"Performance Based Navigation","qs":[{"n":1,"q":"What are the 4 terms that define PBN?","refs":["7.1.1","7.1.4","7.1.5","7.1.6","7.1.9"],"added":null},{"n":1,"q":"When holding is followed by the initial segment of an instrument Timing approach procedure promulgated at a higher speed than 230 kts, the holding should also be promulgated at this higher speed whenever possible. At or below 14 000 ft: 1 minute 2. For holding limited to CAT A and B aircraft only Above 14 000 ft: 1 ½ minutes 3. The speed of 280 kts or 0.8 M reserved for turbulence conditions shall be used for holding only after prior clearance with ATC, unless the relevant Bank Angle – 25° or at a rate of 3° per second, whichever is less publications indicate that the holding area can accommodate aircraft flight at these high holding speeds.","refs":["7.1.1","7.1.4","7.1.5","7.1.6","7.1.9"],"added":null},{"n":2,"q":"What is the difference between RNP and RNAV?","refs":["7.2.1"],"added":null},{"n":3,"q":"What does ‘X’ mean in RNP X?","refs":["7.2.3"],"added":null},{"n":4,"q":"What navigation system is mandatory to get RNP performance?","refs":["7.5.1"],"added":null},{"n":4,"q":"Whenever possible, 280 kts should be used for holding procedures associated with airway route structures. Timing co At or below 14 000 ft: 1 minute Above 14 000 ft: 1 ½ minutes Bank Angle – 25° or at a rate of 3° per second, whichever is less Procedure Turn","refs":["7.5.1"],"added":null},{"n":5,"q":"What is RNAV 2 restricted to continental routes?","refs":["7.2.7"],"added":null},{"n":6,"q":"Can you fly an RNP 0.3 approach?","refs":["7.2.9","7.5.1"],"added":null},{"n":7,"q":"What are your minima for a RNP AR APCH?","refs":["7.2.10"],"added":null},{"n":8,"q":"What is the difference ‘radius to fix’ leg?","refs":["7.3.1"],"added":null},{"n":9,"q":"What is a fixed radius transition?","refs":["7.3.1","7.3.2"],"added":null},{"n":10,"q":"What might be the consequences of not following any procedural speeds restrictions with an RF procedure?","refs":["7.3.1"],"added":null},{"n":11,"q":"What errors combine to make up the Total System Error (TSE)?","refs":["7.4.1","7.4.2","7.4.3","7.4.4"],"added":null},{"n":12,"q":"What is RAIM and how does it check the accuracy of the aircraft position?","refs":["7.6.2"],"added":null},{"n":13,"q":"You’re off on a route for 2 weeks starting on the 25th of the month. What must you ensure before departure?","refs":["7.6.3"],"added":"Check RAIM prediction for the period and the validity of the navigation database over the whole two weeks — an AIRAC cycle change mid-trip means the database must be current for every leg."},{"n":14,"q":"ATC give you a heading to intercept the Final Approach Track on an RNP approach that looks like you’ll intercept the FAT about 1 nm before the FAF. Can you accept the vector.","refs":["7.5.3"],"added":"A vector that intercepts inside the FAF does not let the aircraft stabilise on the final approach track — the intercept should be before the FAF with enough track to establish. Query it and request a wider intercept."},{"n":15,"q":"You’re going to a forward operating base that only has RNP approaches available. The approaches are not in the database, but that Captain suggests that, given the circumstances, you can programme the points and fly the approach. Are they right?","refs":["7.5.3"],"added":"No. The procedure must be retrievable from the on-board navigation database by procedure name and must conform to the charted procedure. Manually building waypoints to fly an RNP approach is not permitted."},{"n":16,"q":"Can you fly an RNP approach is the temperature is outside the range given on the plate?","refs":["7.5.6"],"added":"No — published temperature limits on an RNP/Baro-VNAV procedure are a hard constraint, because the baro-derived vertical path is not compensated outside that range."},{"n":17,"q":"What is the lowest DA/DH you can fly on a LPV approach? FAA TERPS Vs PANS-OPS (ICAO) NOTE: Regional deviations from each standard are identified in ICAO Doc 7030 and are summarized in the applicable AP and state AIP. FAA TERPS PANS-OPS Aircraft Category A: less than 91 kts B: 91 to less than 121 kts C: 121 to less than 141 kts D: 141 to less than 166 kts E: 166 or more (to less than 211 kts – PANS-OPS only) ➢ Based on reference approach speed at certified maximum weight or 1.3 times Vso at maximum certified landing weight Circling Radii, speed limit and bank angle A: 1.3 NM (25°) A: 1.68 NM, 100 kts B: 1.5 NM (25°) B: 2.66 NM, 135 kts C: 1.7 NM (20°) C: 4.20 NM, 180 kts D: 2.3 NM (20°) D: 5.28 NM, 205 kts E: 4.5 NM (22°) E: 6.94 NM, 240 kts Speed limits – See Aircraft Category Bank Angle – 20° or angle giving a rate of 3° /sec, whichever is less (all categories) ➢ After 2012, approaches include expanded circling areas based on circling MDA and are identified by Speed Limits (Initial Approach) All Categories: 200 kts, unless specifically charted on the approach ➢ Range based on aircraft category (or as depicted on the approach plate plate) A: 90-150 kts (110kts*) B: 120/180 kts (140kts*) C: 160/240 kts D: 185/250 kts E: 185/250 kts *Maximum airspeed for reversal and racetrack procedures Holding Airspeeds, Time and Bank Angle At or below 6000 ft: 200 KIAS Levels Normal Conditions Turbulence Above 6000 ft up to and including 14 000 ft: 230 KIAS (may be Conditions restricted to 210 KIAS. Will be depicted by an icon) Up to and incl. 14 230 kts¹ 280 kts³ Above 14 000 ft: 265 KIAS 000 ft 170 kts² 170 kts² Shuttle Climb: 310 KIAS (subject to airspace restrictions) Above 14 000 ft up 240 kts⁴ to and incl. 20 000 ft 280 kts or 0.8 M Canadian Military Airfields: 310 kts Above 20 000 ft up 265 kts⁴ whichever is less³ USAF Airfields: 310 kts to and incl. 34 000 ft USN Airfields: 230 kts Above 34 000 ft 0.83 M 0.83 M","refs":["7.2.9"],"added":"Not stated in the syllabus. LPV minima are commonly published down to 200 ft DA where the procedure and facilities support it; check the plate and your ADH approval for what the C-17 is cleared to."}]}]}};